        'আল্লাহ মূসা আলাইহিস সালামকে পাঠালেন ফিরাউনের কাছে '
        'যে ঈশ্বরত্ব দাবি করেছিল এবং পৃথিবীতে অত্যাচার করছিল, '
        'মূসা তাঁর রবের কাছে এই অত্যাচারীর সামনে তাঁর বার্তার '
        'সত্যতা প্রমাণের জন্য একটি নিদর্শন চাইলেন, আল্লাহ তাঁকে '
        'নির্দেশ দিলেন সেই লাঠি ফেলে দিতে যা দিয়ে তিনি হেলান '
        'দিতেন এবং তাঁর ছাগল তাড়াতেন, তিনি তা ফেলে দিলেন এবং '
        'তা এক বিশাল সাপে পরিণত হলো, দ্রুত নড়াচড়া করছিল, মূসা '
        'তা দেখে ভয় পেয়ে পিছনে ঘুরে দৌড়ালেন, তখন তাঁর রব তাঁকে '
        'ডাকলেন: "একে ধরো, ভয় পেয়ো না, আমরা একে আগের '
        'অবস্থায় ফিরিয়ে দেব।" তারপর মূসা তাঁর হাত বুকের পকেটে '
        'ঢুকিয়ে বের করলেন এবং তা কোনো রোগ বা কুষ্ঠ ছাড়াই সাদা '
        'উজ্জ্বল হয়ে বেরিয়ে এলো। মূসা এই দুটি নিদর্শন নিয়ে ফিরাউনের '
        'কাছে গেলেন, সে অহংকার করল এবং তার বড় জাদুকরদের '
        'জড়ো করল মানুষের সমাগমের একটি দিনে মূসার মুখোমুখি '
        'হওয়ার জন্য। জাদুকররা তাদের দড়ি ও লাঠি ফেলল এবং দর্শকদের '
        'কাছে তাদের জাদুর প্রভাবে সাপের মতো নড়তে দেখা গেল, মূসা '
        'একমুহূর্তের জন্য মনে মনে ভয় পেলেন, তখন আল্লাহ তাঁকে '
        'ওহী পাঠালেন: "ভয় পেয়ো না, নিশ্চয়ই তুমিই বিজয়ী, তোমার '
        'ডান হাতে যা আছে তা ফেলো, এটি তাদের তৈরি করা জিনিস গিলে '
        'ফেলবে।" মূসা তাঁর লাঠি ফেললেন, তা মুহূর্তের মধ্যে জাদুকরদের '
        'সব প্রতারণা গিলে ফেলল, তখন জাদুকররা নিজেরাই — যারা '
        'জাদু সম্পর্কে সবচেয়ে ভালো জানত — বুঝতে পারল এটি মানুষের '
        'জাদু নয়, তারা সিজদায় পড়ে গিয়ে বলল: "আমরা হারুন ও '
        'মূসার রবের প্রতি ঈমান আনলাম," যদিও ফিরাউন তাদের হাত-'
        'পা বিপরীত দিক থেকে কেটে ফেলার হুমকি দিয়েছিল।',
    source:
        'সূরা ত্বহা: ১৭-২১, সূরা আল-আরাফ: ১০৭-১২২ ও সূরা '
        'আশ-শুআরা: ৩৮-৫১',
  ),
  'miracle-6': StoryTranslation(
    title: 'বনী ইসরাইলের গরু এবং কথা বলা নিহত ব্যক্তি',
    body:
        'বনী ইসরাইলের মধ্যে একটি রহস্যময় হত্যাকাণ্ড ঘটল: এক '
        'ধনী বৃদ্ধ ব্যক্তিকে রাতে হত্যা করা হলো, তার হত্যাকারী নিশ্চিতভাবে '
        'জানা গেল না, তখন মানুষ মতভেদে পড়ল এবং তর্ক করল, এই '
        'মতভেদ গোত্রগুলোর মধ্যে ফিতনার কারণ হয়ে দাঁড়াল, প্রত্যেকে '
        'অন্যকে হত্যার জন্য অভিযুক্ত করছিল। তারা তাদের নবী মূসা '
        'আলাইহিস সালামের কাছে আশ্রয় নিল যাতে আল্লাহ তাদের '
        'কাছে হত্যাকারীকে প্রকাশ করেন। আল্লাহ মূসাকে ওহী দিলেন '
        'যে তাদের একটি গরু জবাই করার নির্দেশ দিতে, তারপর নিহত '
        'ব্যক্তিকে তার একটি অংশ দিয়ে আঘাত করতে, সে আল্লাহর অনুমতিতে '
        'জীবিত হবে এবং তার হত্যাকারীকে জানাবে। এখানেই বনী '
        'ইসরাইলের সেই সুপরিচিত জিদ শুরু হলো, নির্দেশ অনুযায়ী যেকোনো '
        'গরু তৎক্ষণাৎ জবাই করার পরিবর্তে, তারা এই ভেবে বেশি বেশি '
        'প্রশ্ন করা শুরু করল যে এতে তারা নির্দেশ থেকে রেহাই পাবে: '
        'তারা মূসাকে বলল: "তোমার রবের কাছে দোয়া করো যেন তিনি '
        'আমাদের জানান এটি কেমন?" উত্তর এলো যে তা না বৃদ্ধ না '
        'তরুণী, এই দুইয়ের মাঝামাঝি বয়সের। তারা আবার তার রঙ '
        'সম্পর্কে জিজ্ঞেস করল, তাদের বলা হলো তার রঙ উজ্জ্বল হলুদ '
        'যা দর্শকদের আনন্দিত করে। তবুও তারা সন্তুষ্ট হলো না এবং '
        'তৃতীয়বার জিজ্ঞেস করল: "আমাদের কাছে গরুগুলো একই রকম '
        'মনে হয়, তোমার রবের কাছে দোয়া করো যেন আমাদের জানান '
        'তা কেমন, আল্লাহ চাইলে আমরা অবশ্যই সঠিক পথ পাব।" তখন '
        'শেষ বৈশিষ্ট্য এলো: এমন একটি গরু যা মাটি চাষে বা ক্ষেত '
        'সেচে ব্যবহৃত হয়নি, নিখুঁত, কোনো দাগ ছাড়া। এই বিস্তারিত '
        'বর্ণনায়, তারা এই বৈশিষ্ট্যের সাথে মিলে যাওয়া একটি মাত্র গরু '
        'খুঁজে পেল, যা একজন তরুণ রাখালের কাছে ছিল, তারা এটি তার '
        'চামড়া ভর্তি সোনার সমান উচ্চমূল্যে কিনতে বাধ্য হলো, এবং '
        'নির্দেশ অনুযায়ী এটি জবাই করল। তারপর তারা নিহত ব্যক্তিকে '
        'এর একটি অংশ দিয়ে আঘাত করল, আল্লাহ তাকে তাঁর অনুমতিতে '
        'একমুহূর্তের জন্য জীবিত করলেন, সে প্রকৃত হত্যাকারীর নাম বলল: '
        'সে ছিল তার নিজের ভাতিজা, যে তার উত্তরাধিকারের লোভে এবং '
        'তার মেয়েকে — নিহত ব্যক্তির মেয়েকে — অপেক্ষা বা অনুমতি '
        'ছাড়া বিয়ে করার জন্য তাকে হত্যা করেছিল। হত্যাকারী মনে '
        'করেছিল সে এই সাক্ষীবিহীন অপরাধ থেকে রেহাই পাবে, কিন্তু '
        'আল্লাহ এমন এক উপায়ে সত্য প্রকাশ করলেন যা তার মনে '
        'কখনো আসেনি। নিহত ব্যক্তি এরপর আবার মারা গেল, আর মানুষ '
        'সত্য জানল; এই কাহিনিতে বড় শিক্ষা রয়েছে যে আল্লাহ প্রতিটি '
        'গোপন বিষয় প্রকাশ করতে সক্ষম, এবং দ্বীনে কঠোরতা — যেমন '
        'বনী ইসরাইল তাদের অতিরিক্ত প্রশ্নে করেছিল — মানুষের ওপর '
        'কেবল অতিরিক্ত কষ্টই বাড়ায়।',
    source: 'সূরা আল-বাকারা: ৬৭-৭৩',
  ),
  'miracle-7': StoryTranslation(
    title: 'খন্দকের সৈন্যদের এক সা যব দিয়ে খাওয়ানো',
    body:
        'খন্দক খননের দিনগুলোতে, ক্ষুধা মুসলিমদের গ্রাস করেছিল '
        'যারা টানা কয়েক দিন তীব্র শীতে কাজ করছিল, এমনকি তাদের '
        'কেউ কেউ ক্ষুধার তীব্রতায় পেটে পাথর বেঁধেছিল। জাবির ইবনে '
        'আবদুল্লাহ রাদিয়াল্লাহু আনহু নবী ﷺ-এর ওপর ক্লান্তির চিহ্ন '
        'দেখলেন, তিনি নিজ বাড়িতে যাওয়ার অনুমতি চাইলেন, নিজ '
        'স্ত্রীকে বললেন: "তোমার কাছে কিছু আছে কি? আমি নবী ﷺ-এর '
        'মধ্যে তীব্র ক্ষুধা দেখেছি।" তিনি উত্তর দিলেন: "আমার কাছে '
        'সামান্য যব ও একটি ছোট ছাগল আছে।" জাবির ছাগলটি জবাই '
        'করলেন এবং তাঁর স্ত্রী যব পিষলেন, তিনি নবী ﷺ-কে কয়েকজন '
        'সাথে নিয়ে আসতে অনুরোধ করলেন, কারণ খাবার অল্প ছিল এবং '
        'সবার জন্য যথেষ্ট নয়। কিন্তু নবী ﷺ খন্দকে উচ্চস্বরে ডাক '
        'দিলেন: "হে খন্দকবাসী, জাবির খাবার প্রস্তুত করেছে, চলো!" '
        'জাবির অবাক হলেন এবং মানুষ পৌঁছানোর আগেই দ্রুত নিজ '
        'স্ত্রীর কাছে গেলেন, তাঁকে জানালেন যে নবী ﷺ পুরো খন্দকবাসীকে '
        'দাওয়াত দিয়েছেন যারা এক হাজার লোক ছিল। তিনি জিজ্ঞেস '
        'করলেন: "তিনি কি জিজ্ঞেস করেছিলেন আমাদের কাছে কত '
        'আছে?" জাবির তার অসুবিধা বুঝলেন, কিন্তু নবী ﷺ ঘরে ঢুকলেন '
        'এবং নির্দেশ দিলেন যেন হাঁড়ি ও খামির নামানো না হয় যতক্ষণ '
        'না তিনি নিজে আসেন, তারপর তিনি বরকতের দোয়া করলেন '
        'এবং নিজের পবিত্র হাতে রুটি ভেঙে তাতে মাংস রাখতে শুরু '
        'করলেন, মানুষের মধ্যে দশ দশজন করে ভাগ করে দিলেন যারা '
        'ঢুকে তৃপ্ত হয়ে খেয়ে বেরিয়ে যেত, শেষ পর্যন্ত হাজার লোক '
        'সবাই খেল এবং তৃপ্ত হয়ে বেরিয়ে গেল, আর হাঁড়ি আগের মতোই '
        'ফুটতে থাকল এবং খামিরও আগের মতোই রইল, তাঁর ﷺ দোয়ার '
        'বরকতে।',
    source: 'সহীহ বুখারী ও মুসলিম',
  ),
  'miracle-8': StoryTranslation(
    title: 'নবী ﷺ-এর বৃষ্টির দোয়া এবং বৃষ্টি বর্ষণ',
    body:
        'নবী ﷺ-এর সময়ে মদিনাবাসীর ওপর তীব্র দুর্ভিক্ষ নেমে '
        'এলো, বৃষ্টি বন্ধ হয়ে গেল, মাটি শুকিয়ে গেল এবং প্রাণী মারা '
        'গেল, এমনকি জুমার দিন এক বেদুইন মসজিদে প্রবেশ করল '
        'যখন নবী ﷺ মিম্বারে খুতবা দিচ্ছিলেন, সে বলল: "হে আল্লাহর '
        'রাসূল, সম্পদ ধ্বংস হয়ে গেছে এবং পরিবার ক্ষুধার্ত, আল্লাহর '
        'কাছে দোয়া করুন যেন আমাদের বৃষ্টি দেন।" নবী ﷺ তাঁর পবিত্র '
        'হাত দুটি তুললেন — অথচ আকাশে একটি মেঘখণ্ডও ছিল না — '
        'এবং দোয়া করলেন: "হে আল্লাহ, আমাদের বৃষ্টি দিন, হে আল্লাহ, '
        'আমাদের বৃষ্টি দিন, হে আল্লাহ, আমাদের বৃষ্টি দিন।" এই '
        'হাদীসের বর্ণনাকারী আনাস ইবনে মালিক বলেন: "আল্লাহর '
        'কসম, নবী ﷺ মিম্বার থেকে নামার আগেই আমি তাঁর পবিত্র '
        'দাড়ি থেকে বৃষ্টির ফোঁটা পড়তে দেখলাম।" সেদিন বৃষ্টি নামল '
        'এবং পুরো এক সপ্তাহ ধরে চলল, এমনকি তারা এবার ডুবে যাওয়ার '
        'ভয় পেল, তখন একই ব্যক্তি — বা অন্য কেউ — পরবর্তী জুমায় '
        'এসে বলল: "হে আল্লাহর রাসূল, ঘরবাড়ি ধসে পড়েছে এবং পথ '
        'বন্ধ হয়ে গেছে, আল্লাহর কাছে দোয়া করুন যেন এটি আমাদের '
        'থেকে থামিয়ে দেন।" তখন নবী ﷺ হাসলেন এবং হাত তুলে '
        'বললেন: "হে আল্লাহ, আমাদের চারপাশে বর্ষণ করুন, আমাদের '
        'ওপর নয়, হে আল্লাহ, টিলা, পাহাড়, উপত্যকা এবং গাছপালা '
        'জন্মানোর জায়গায়।" তখন মেঘ মদিনা থেকে সরে গিয়ে তার '
        'চারপাশে ছড়িয়ে পড়ল, যেন কোনো অদৃশ্য হাত আল্লাহর '
        'নির্দেশে তা ছড়িয়ে দিচ্ছে, আর মদিনা তার কেন্দ্রে সব ক্ষতি '
        'থেকে নিরাপদ রইল, এটি ছিল সেই বিস্ময়কর ঘটনাগুলোর একটি '
        'যেখানে তাঁর ﷺ দোয়া এত দ্রুত এবং সবার চোখের সামনে '
        'কবুল হয়েছিল।',
    source: 'সহীহ বুখারী ও মুসলিম',
  ),
  'miracle-9': StoryTranslation(
    title: 'কারুন এবং তার মাটিতে ধ্বসে যাওয়া',
    body:
        'কারুন ছিল মূসা আলাইহিস সালামের সম্প্রদায়ের অংশ, আর '
        'আল্লাহ তাকে এত সম্পদ দিয়েছিলেন যে তার ধনভান্ডারের '
        'চাবিগুলো বহন করাই শক্তিশালী মানুষের একটি দলের জন্য '
        'ভারী ছিল। তার সম্প্রদায় তাকে উপদেশ দিল: "আনন্দে গর্বিত '
        'হয়ো না, নিশ্চয়ই আল্লাহ অহংকারীদের পছন্দ করেন না, আর '
        'আল্লাহ তোমাকে যা দিয়েছেন তার মধ্যে আখিরাতের ঘর খোঁজো, '
        'দুনিয়া থেকে তোমার অংশ ভুলে যেয়ো না, আল্লাহ তোমার প্রতি '
        'যেমন অনুগ্রহ করেছেন তেমনি তুমিও অনুগ্রহ করো, পৃথিবীতে '
        'বিপর্যয় সৃষ্টি করো না।" কিন্তু অহংকার কারুনের অন্তর্দৃষ্টিকে '
        'অন্ধ করে দিল, সে প্রকাশ্য দম্ভের সাথে উত্তর দিল: "আমাকে '
        'এটি কেবল আমার নিজের জ্ঞানের কারণেই দেওয়া হয়েছে," সে '
        'তার প্রতি আল্লাহর অনুগ্রহকে অস্বীকার করছিল এবং দাবি '
        'করছিল যে তার কাছে যা কিছু আছে তা তার নিজের বুদ্ধিমত্তার '
        'ফল। একদিন সে ঝলমলে সাজসজ্জায়, দামি পোশাকে এবং বিশাল '
        'পরিচারকদল নিয়ে তার সম্প্রদায়ের সামনে বের হলো, তার '
        'জাঁকজমক দেখে যারা তা দেখল তাদের কেউ কেউ কারুনকে '
        'দেওয়া দুনিয়ার ভাগ্যের অধিকারী হতে চাইল, অথচ তাদের '
        'মধ্যে যাদের জ্ঞান ও ঈমান ছিল তারা বলল: "তোমাদের জন্য '
        'দুর্ভোগ, যারা ঈমান আনে এবং সৎকর্ম করে তাদের জন্য '
        'আল্লাহর পুরস্কার উত্তম, আর কেবল ধৈর্যশীলরাই তা লাভ করে।" '
        'আল্লাহ তার অহংকার ও অস্বীকৃতির ওপর দীর্ঘ অবকাশ দিলেন '
        'না, তাকে ও তার ঘরকে এক মুহূর্তে মাটিতে ধ্বসিয়ে দিলেন, তার '
        'জন্য আল্লাহ ব্যতীত এমন কোনো দল ছিল না যে তাকে সাহায্য '
        'করবে, আর সে নিজেও নিজেকে সাহায্য করতে পারল না। যারা '
        'গতকালও তার অবস্থানের আকাঙ্ক্ষা করেছিল তারা অনুশোচনা '
        'ও শিক্ষা নিয়ে বলল: "হায়, নিশ্চয়ই আল্লাহ তাঁর বান্দাদের '
        'মধ্যে যাকে ইচ্ছা রিজিক প্রশস্ত করেন এবং সংকুচিত করেন, '
        'আল্লাহ যদি আমাদের প্রতি অনুগ্রহ না করতেন তাহলে আমাদেরও '
        'ধ্বসিয়ে দিতেন, হায়, নিশ্চয়ই অকৃতজ্ঞরা কখনো সফল হয় না," '
        'তখন তারা হঠাৎ বুঝল যে তারা যে সম্পদের প্রতি ঈর্ষা করছিল '
        'তা কোনো হিসাববিহীন নিয়ামত ছিল না, বরং তা এমন একটি '
        'বিশাল পরীক্ষা ছিল যা তার অহংকার ও অস্বীকৃতির কারণে তাকে '
        'ধ্বংস করেছিল।',
    source: 'সূরা আল-কাসাস: ৭৬-৮২',
  ),
  'miracle-10': StoryTranslation(
    title: 'শনিবারের অধিবাসীরা যাদের বানরে রূপান্তরিত করা হয়েছিল',
    body:
        'আল্লাহ সমুদ্রতীরের একটি গ্রামে বসবাসকারী বনী ইসরাইলের '
        'একটি দলকে একটি সূক্ষ্ম পরীক্ষায় ফেললেন: তাদের শনিবার '
        'দিনে মাছ শিকার করতে নিষেধ করা হলো, যা ছিল তাদের '
        'ইবাদত ও বিশ্রামের বিশেষ দিন। আল্লাহ শনিবার দিনে মাছগুলোকে '
        'পানির উপরিভাগে প্রচুর পরিমাণে আসতে দেখাতেন, অথচ '
        'সপ্তাহের বাকি দিনগুলোতে তারা সম্পূর্ণরূপে অদৃশ্য থাকত, '
        'এটি ছিল তাদের আনুগত্যের সত্যতার একটি পরীক্ষা। কিন্তু '
        'তাদের মধ্যে কেউ কেউ এই সাময়িক নিষেধাজ্ঞায় ধৈর্য ধরতে '
        'পারল না, তারা স্পষ্টভাবে তা লঙ্ঘন না করে নির্দেশ এড়ানোর '
        'জন্য একটি চতুর কৌশল খুঁজে বের করল: তারা শুক্রবার পুকুর '
        'ও জাল তৈরি করত যা শনিবার নিজে নিজেই মাছ জড়ো করত, '
        'তারপর শনিবার শেষ হওয়ার সাথে সাথেই তারা এসে সেগুলো '
        'ধরত, তারা মনে করত এভাবে তারা নির্দেশের স্পষ্ট শব্দ লঙ্ঘন '
        'করছে না যদিও তারা এর উদ্দেশ্য ও চেতনা লঙ্ঘন করছিল। '
        'গ্রামের অধিবাসীরা তিন দলে বিভক্ত হলো: এক দল এই হারাম '
        'কৌশল করল, এক দল তাদের থেকে দূরে থেকে এই কাজ থেকে '
        'নিষেধ করল, আর তৃতীয় একটি দল নীরব থাকল, না করল না '
        'নিষেধ করল, বরং নিষেধকারীদের বিস্ময়ে বলল: "তোমরা কেন '
        'সেই সম্প্রদায়কে উপদেশ দিচ্ছ যাদের আল্লাহ ধ্বংস করবেন বা '
        'কঠোর শাস্তি দেবেন? উপদেশের কী লাভ?" তখন উপদেশদাতারা '
        'উত্তর দিল: "তোমাদের রবের কাছে একটি অজুহাত হিসেবে, আর '
        'হয়তো তারা সতর্ক হবে," অর্থাৎ তারা ফলাফল বিবেচনা না করে '
        'তাদের দায়িত্ব পালনের জন্য উপদেশ দিচ্ছিল। যখন অপরাধীরা '
        'অহংকারের সাথে তাদের কৌশল চালিয়ে গেল, তখন আল্লাহর '
        'অপমানজনক শাস্তি তাদের কাছে এলো: তাদের অবমাননাকর ও '
        'বিতাড়িত বানরে রূপান্তরিত করা হলো, এই শাস্তি ছিল প্রতারণার '
        'মাধ্যমে আল্লাহর নির্দেশ এড়ানোর তাদের অপরাধের উপযুক্ত, '
        'পরবর্তীদের জন্য শিক্ষা হিসেবে যে বাহ্যিক চতুরতা দিয়ে '
        'আল্লাহর সীমা প্রতারণা করা তাঁর শাস্তি থেকে রক্ষা করে না, '
        'বরং হয়তো এটিই সবচেয়ে বড় পাপ।',
    source: 'সূরা আল-আরাফ: ১৬৩-১৬৬',
  ),

  // ===== নবীদের কাহিনি =====
  'prophet-1': StoryTranslation(
    title: 'আদম আলাইহিস সালাম ও সৃষ্টির সূচনা',
    body:
        'যখন আল্লাহ আদম আলাইহিস সালামকে সৃষ্টি করার ইচ্ছা '
        'করলেন, তিনি ফেরেশতাদের তা জানালেন, তারা বিস্ময়ে জিজ্ঞেস '
        'করল: "আপনি কি পৃথিবীতে এমন কাউকে সৃষ্টি করবেন যে '
        'বিপর্যয় সৃষ্টি করবে এবং রক্তপাত করবে, অথচ আমরা আপনার '
        'প্রশংসাসহ তাসবীহ করি এবং আপনার পবিত্রতা ঘোষণা করি?" '
        'তাদের রব উত্তর দিলেন: "নিশ্চয়ই আমি জানি যা তোমরা জানো '
        'না।" আল্লাহ আদমকে মাটি দিয়ে সৃষ্টি করলেন, তাঁর মধ্যে '
        'তাঁর রুহ থেকে ফুঁ দিলেন এবং তাঁকে সব কিছুর নাম শেখালেন, '
        'যা ফেরেশতারা জানত না। তারপর তিনি এই জিনিসগুলো '
        'ফেরেশতাদের সামনে উপস্থাপন করলেন এবং তাদের নাম '
        'জিজ্ঞেস করলেন, তারা উত্তর দিতে পারল না, আল্লাহ বললেন: '
        '"আমি কি তোমাদের বলিনি যে আমি আসমান ও জমিনের '
        'গায়েব জানি?" তারপর আল্লাহ ফেরেশতাদের আদমকে সম্মানসূচক '
        'সিজদা করার নির্দেশ দিলেন, ইবাদতের জন্য নয়; জিনদের '
        'মধ্যে থেকে ইবলিস ব্যতীত সবাই সিজদা করল; সে অস্বীকার '
        'করল এবং অহংকার করল ও বলল: "আমি তার চেয়ে শ্রেষ্ঠ, '
        'আপনি আমাকে আগুন দিয়ে সৃষ্টি করেছেন আর তাকে মাটি দিয়ে।" '
        'তখন তাকে আল্লাহর রহমত থেকে বহিষ্কার করা হলো এবং '
        'অভিশপ্ত করা হলো, সে তার রবের কাছে কিয়ামত পর্যন্ত '
        'অবকাশ চাইল আদম সন্তানদের বিভ্রান্ত করার জন্য, আল্লাহ '
        'মানুষের জন্য একটি পরীক্ষা হিসেবে তাকে অবকাশ দিলেন। '
        'আল্লাহ আদম ও তাঁর স্ত্রী হাওয়াকে জান্নাতে বসবাস করালেন, '
        'তাদের জন্য একটি গাছ ব্যতীত সব ফল হালাল করলেন যার '
        'কাছে যেতে তাদের নিষেধ করা হয়েছিল; ইবলিস তাদের '
        'কুমন্ত্রণা দিল এবং মিথ্যা কসম খেল যে সে একজন বিশ্বস্ত '
        'উপদেষ্টা, এবং এই গাছটি চিরন্তনতার গাছ, শেষ পর্যন্ত তারা '
        'তা থেকে খেল; তাদের লজ্জাস্থান তাদের কাছে প্রকাশিত হলো '
        'এবং তারা প্রথমবার লজ্জা অনুভব করল। তারা আল্লাহর কাছে '
        'তওবা করল এবং অনুতপ্ত হলো, আল্লাহ তাদের তওবা কবুল '
        'করলেন এবং তাদের কিছু বাক্য শেখালেন যা দিয়ে তারা দোয়া '
        'করবে, তারপর তাদের পৃথিবীতে নামিয়ে দেওয়া হলো প্রথম দুই '
        'মানুষ হিসেবে যারা এটি আবাদ করবে, আর এখান থেকেই সমগ্র '
        'মানবজাতির কাহিনি শুরু হলো।',
    source: 'সূরা আল-বাকারা: ৩০-৩৯ ও সূরা আল-আরাফ: ১১-২৫',
  ),
  'prophet-2': StoryTranslation(
    title: 'নূহ আলাইহিস সালাম ও নৌকা',
    body:
        'আল্লাহ নূহ আলাইহিস সালামকে সেই সম্প্রদায়ের কাছে পাঠালেন '
        'যারা আল্লাহ ব্যতীত মূর্তির পূজা করত, তিনি তাদের নয়শত '
        'পঞ্চাশ বছর ধরে তাওহীদের দাওয়াত দিলেন, রাত-দিন, গোপনে '
        'ও প্রকাশ্যে, কিন্তু তাঁর দাওয়াত তাদের পলায়ন ও জিদ ছাড়া '
        'আর কিছুই বাড়ায়নি। তাদের নেতারা দরিদ্র ও দুর্বলদের তাঁর '
        'সাথে বসতে বাধা দিত এবং যখনই তিনি তাদের পাশ দিয়ে '
        'যেতেন তারা উপহাস করত, শেষ পর্যন্ত নূহ তাঁর রবের কাছে '
        'অভিযোগ করলেন: "হে আমার রব, আমি আমার সম্প্রদায়কে '
        'রাত-দিন ডেকেছি, কিন্তু আমার আহ্বান তাদের পলায়ন ছাড়া '
        'আর কিছুই বাড়ায়নি।" তখন আল্লাহ তাঁকে একটি নৌকা তৈরি '
        'করার ওহী দিলেন; এটি সমুদ্র থেকে দূরের একটি ভূমিতে একটি '
        'অদ্ভুত নির্দেশ ছিল, নূহ তাঁর সম্প্রদায়ের উপহাসের মধ্যে তা '
        'তৈরি করতে শুরু করলেন, যারা তাঁর পাশ দিয়ে যেতে যেতে '
        'উপহাস করত: "তুমি মরুভূমিতে নৌকা তৈরি করছ, হে নূহ?" '
        'তিনি তাদের উত্তর দিতেন: "তোমরা যদি আমাদের সাথে উপহাস '
        'করো, তাহলে আমরাও তোমাদের সাথে যেমন তোমরা উপহাস '
        'করছ তেমনি উপহাস করব, শীঘ্রই তোমরা জানতে পারবে।" '
        'নৌকা সম্পূর্ণ হলে, আল্লাহর নির্ধারিত নিদর্শন প্রকাশ পেল: '
        'চুলা ফুটে উঠল, অর্থাৎ যে জায়গায় সাধারণত রুটি বেক করা '
        'হতো সেখান থেকে প্রবলভাবে পানি বেরিয়ে এলো, এটি ছিল '
        'মহাপ্লাবনের শুরুর একটি সংকেত। আল্লাহ নূহকে নির্দেশ দিলেন '
        'নৌকায় প্রতিটি প্রজাতির একজোড়া, পুরুষ ও স্ত্রী, এবং তাঁর '
        'সাথে ঈমান আনা লোকদের — যারা খুবই কম ছিল — এবং তাঁর '
        'পরিবারকে তুলে নিতে যাদের সম্পর্কে ইতিমধ্যে সিদ্ধান্ত নেওয়া '
        'হয়েছিল তাদের ব্যতীত। নূহ তাঁর পুত্রকে ডাকলেন যে দূরে '
        'সরে গিয়েছিল এবং তাদের সাথে ওঠেনি: "হে আমার পুত্র, '
        'আমাদের সাথে ওঠো এবং কাফিরদের সাথে থেকো না।" সে '
        'উত্তর দিল: "আমি এমন একটি পাহাড়ে আশ্রয় নেব যা আমাকে '
        'পানি থেকে রক্ষা করবে।" নূহ বললেন: "আজ আল্লাহর নির্দেশ '
        'থেকে কেউ রক্ষাকারী নেই, তবে যার প্রতি তিনি রহমত করেন '
        'সে ব্যতীত।" তখন ঢেউ তাদের মাঝে বাধা হয়ে দাঁড়াল এবং সে '
        'ডুবে যাওয়াদের অন্তর্ভুক্ত হলো একজন নবীর পুত্র হওয়া সত্ত্বেও, '
        'কারণ সে তাঁর দ্বীনে ছিল না। প্লাবন পৃথিবীতে অব্যাহত রইল '
        'যতক্ষণ না পাহাড়গুলো ঢেকে গেল, সব কাফির ধ্বংস হলো; '
        'তারপর আল্লাহ আকাশকে বৃষ্টি বন্ধ করতে এবং পৃথিবীকে তার '
        'পানি শুষে নিতে নির্দেশ দিলেন; নৌকা জুদি পাহাড়ে থেমে '
        'গেল, এবং বলা হলো: "জালিম সম্প্রদায়ের জন্য ধ্বংস হোক।"',
    source: 'সূরা হুদ: ২৫-৪৯ ও সূরা নূহ',
  ),
  'prophet-3': StoryTranslation(
    title: 'ইব্রাহিম আলাইহিস সালাম আগুনে',
    body:
        'ইব্রাহিম আলাইহিস সালাম মূর্তিপূজক সম্প্রদায়ের মধ্যে বড় '
        'হয়েছিলেন, তিনি সত্য অনুসন্ধানে তাঁর চারপাশের মহাবিশ্ব '
        'নিয়ে চিন্তা করতে শুরু করলেন, এমনকি রাতে একটি তারা '
        'দেখে বললেন: "এটি আমার রব," যখন তা অস্ত গেল তিনি '
        'বললেন: "আমি অস্তগামীদের পছন্দ করি না।" তারপর চাঁদকে '
        'উদিত হতে দেখে বললেন: "এটি আমার রব," যখন তাও অস্ত '
        'গেল তিনি বললেন: "আমার রব যদি আমাকে পথ না দেখান '
        'তাহলে আমি অবশ্যই বিভ্রান্তদের অন্তর্ভুক্ত হব।" তারপর সূর্যকে '
        'উদিত হতে দেখে বললেন: "এটি আমার রব, এটি বৃহত্তর," যখন '
        'তাও অস্ত গেল তিনি বুঝলেন যে এই সব সৃষ্টি অস্ত যায় এবং '
        'বিলীন হয়, তিনি বললেন: "আমি আমার মুখ সেই সত্তার দিকে '
        'ফিরিয়েছি যিনি আসমান ও জমিন সৃষ্টি করেছেন, একনিষ্ঠভাবে।" '
        'তারপর তিনি তাঁর সম্প্রদায়ের মূর্তিপূজাকে চ্যালেঞ্জ করতে '
        'শুরু করলেন, একদিন তিনি তাদের মন্দিরে প্রবেশ করলেন '
        'যখন তারা একটি উৎসবের জন্য বেরিয়ে গিয়েছিল, তিনি হাতে '
        'কুড়াল দিয়ে সব মূর্তি ভেঙে ফেললেন সবচেয়ে বড়টি ব্যতীত, '
        'এবং কুড়ালটি তার গলায় ঝুলিয়ে দিলেন। তারা ফিরে এসে '
        'তাদের দেবতাদের ভাঙা দেখে জিজ্ঞেস করল: "আমাদের '
        'দেবতাদের সাথে এটা কে করেছে?" তাদের বলা হলো: "আমরা '
        'একজন যুবককে তাদের সমালোচনা করতে শুনেছি যাকে ইব্রাহিম '
        'বলা হয়।" তারা তাঁকে নিয়ে এলো এবং জিজ্ঞেস করল: "তুমি কি '
        'আমাদের দেবতাদের সাথে এটা করেছ, হে ইব্রাহিম?" তিনি '
        'বুদ্ধিমত্তার সাথে উত্তর দিলেন: "বরং এটি তাদের এই বড়টিই '
        'করেছে, তাদের জিজ্ঞেস করো যদি তারা কথা বলতে পারে।" '
        'তারা একমুহূর্তের জন্য চেতনায় ফিরে এলো এবং তাদের '
        'বোকামি বুঝল, কিন্তু অহংকার তাদের স্বীকার করতে বাধা '
        'দিল, তারা বলল: "তুমি জানো এরা কথা বলে না।" তিনি উত্তর '
        'দিলেন: "তাহলে তোমরা কি আল্লাহ ব্যতীত এমন কিছুর পূজা '
        'করছ যা তোমাদের কোনো উপকার বা ক্ষতি করতে পারে না? '
        'ধিক তোমাদের এবং আল্লাহ ব্যতীত তোমরা যার পূজা করো '
        'তার জন্য, তোমরা কি বুদ্ধি রাখো না?" তারা রাগান্বিত হলো '
        'এবং একটি দৃষ্টান্তমূলক শাস্তিতে একমত হলো: তাকে আগুনে '
        'পুড়িয়ে ফেলা। তারা কয়েক দিন ধরে কাঠ জড়ো করল যতক্ষণ '
        'না এটি এত বড় আগুন হলো যে কাছে যাওয়া যেত না, তারপর '
        'তারা মজানিক দিয়ে তাঁকে তাতে নিক্ষেপ করল আগুনের '
        'তীব্রতার কারণে। সেই মুহূর্তে, আল্লাহ সরাসরি আগুনকে '
        'নির্দেশ দিলেন: "হে আগুন, ইব্রাহিমের জন্য শীতল ও নিরাপদ '
        'হয়ে যাও।" তখন আগুন তাঁকে পোড়াল না, তিনি কোনো ক্ষতি '
        'ছাড়াই নিরাপদে বেরিয়ে এলেন, এমনকি বলা হয় শুধু তার '
        'বাঁধনগুলোই পুড়েছিল, মানুষ তাদের চোখের সামনে একটি '
        'বিশাল মুজিজা দেখল, কিন্তু তাদের অধিকাংশ তা সত্ত্বেও '
        'কুফরে অবিচল রইল।',
    source:
        'সূরা আল-আম্বিয়া: ৫১-৭০, সূরা আল-আনআম: ৭৪-৭৯ ও '
        'সূরা আস-সাফফাত: ৮৩-৯৮',
  ),
  'prophet-4': StoryTranslation(
    title: 'ইউসুফ আলাইহিস সালাম ও তাঁর ভাইয়েরা',
    body:
        'ইউসুফ আলাইহিস সালাম শৈশবে একটি অদ্ভুত স্বপ্ন দেখলেন: '
        'এগারোটি তারা, সূর্য ও চাঁদ তাঁকে সিজদা করছে, তিনি তা তাঁর '
        'পিতা ইয়াকুব আলাইহিস সালামকে বললেন, ইয়াকুব বুঝলেন '
        'যে তাঁর পুত্র একটি মহান মর্যাদায় পৌঁছাবেন, তিনি তাঁকে '
        'সতর্ক করলেন: "হে আমার পুত্র, তোমার স্বপ্ন তোমার ভাইদের '
        'বলো না, তারা তোমার বিরুদ্ধে ষড়যন্ত্র করবে।" কিন্তু তাঁর '
        'ভাইদের ঈর্ষা — তিনি ছিলেন তাদের পিতার সবচেয়ে প্রিয় '
        'সন্তান — সীমা অতিক্রম করল, তারা তাঁর থেকে মুক্তি পাওয়ার '
        'সিদ্ধান্ত নিল, তাদের পিতাকে রাজি করাল তাঁকে তাদের সাথে '
        'খেলতে পাঠাতে, তারপর তারা তাঁকে মরুভূমির একটি পরিত্যক্ত '
        'কূপের তলদেশে ফেলে দিল, তাঁকে একা ও ভীত অবস্থায় রেখে; '
        'তারা তাঁর জামা নিয়ে মিথ্যা রক্তে রঞ্জিত করল, কাঁদতে কাঁদতে '
        'তাদের পিতার কাছে ফিরে এসে মিথ্যা বলল যে নেকড়ে তাঁকে '
        'খেয়ে ফেলেছে। ইয়াকুব গভীর দুঃখে ভুগলেন, এমনকি দুঃখে '
        'তাঁর চোখ সাদা হয়ে গেল, কিন্তু তিনি আল্লাহর রহমতের '
        'আশা হারালেন না। কূপে, একটি কাফেলা পানির খোঁজে গেল, '
        'তারা তাদের বালতি নামাল, ইউসুফ তা ধরলেন, তারা যা পেল '
        'তাতে আনন্দিত হলো এবং তাঁকে মিশরে আজিজ নামক এক '
        'ব্যক্তির কাছে সস্তা দামে বিক্রি করল। ইউসুফ আজিজের ঘরে '
        'বড় হলেন এবং একটি বড় পরীক্ষার মুখোমুখি হলেন যখন আজিজের '
        'স্ত্রী তাঁকে পাপকর্মে প্রলুব্ধ করার চেষ্টা করল, তিনি বললেন: '
        '"আল্লাহর কাছে আশ্রয় চাই, তিনিই আমার প্রভু, তিনি আমাকে '
        'ভালো আশ্রয় দিয়েছেন," তার জোরাজুরি সত্ত্বেও তিনি সতীত্ব '
        'রক্ষা করলেন, পাপের চেয়ে কারাগার বেছে নিলেন এবং সেখানে '
        'বছরের পর বছর অন্যায়ভাবে কাটালেন, কিন্তু তিনি তা বন্দীদের '
        'স্বপ্নের ব্যাখ্যা করার জন্য ব্যবহার করলেন, এমনকি তাঁর খবর '
        'রাজার কাছে পৌঁছাল যখন তিনি এমন একটি স্বপ্ন দেখলেন যা '
        'তাঁর ব্যাখ্যাকারীদের বিভ্রান্ত করল: সাতটি মোটা গরু সাতটি '
        'শীর্ণ গরু দ্বারা খাওয়া হচ্ছে। ইউসুফ তা প্রাচুর্যের বছরগুলোর '
        'পর দুর্ভিক্ষের বছর হিসেবে ব্যাখ্যা করলেন এবং ফসল ব্যবস্থাপনার '
        'পদ্ধতি পরামর্শ দিলেন। রাজা তাঁর প্রজ্ঞায় মুগ্ধ হলেন এবং '
        'তাঁকে কারাগার থেকে মুক্ত করে দেশের ধনভাণ্ডারের দায়িত্ব '
        'দিলেন। দুর্ভিক্ষের বছর এলে, তাঁর ভাইয়েরা খাদ্যের সন্ধানে '
        'মিশরে গেলেন, ইউসুফ তাদের চিনলেন যদিও তারা তাঁকে চিনতে '
        'পারল না, তিনি কৌশলে তাঁর ছোট ভাই বেনইয়ামিনকে নিয়ে '
        'আসালেন, শেষ পর্যন্ত তিনি নিজেকে প্রকাশ করলেন, তারা '
        'লজ্জা ও অনুশোচনায় কাঁপতে লাগল, তিনি তাদের সেই বাক্য '
        'বললেন যা কুরআন চিরস্থায়ী করেছে: "আজ তোমাদের ওপর '
        'কোনো তিরস্কার নেই, আল্লাহ তোমাদের ক্ষমা করুন, তিনি '
        'পরম দয়ালুদের মধ্যে সর্বাধিক দয়ালু।" তিনি তাঁর জামা তাঁর '
        'পিতার কাছে পাঠালেন, তাঁর দৃষ্টি ফিরে এলো, দীর্ঘ বিচ্ছেদের '
        'পর পরিবার আবার একত্রিত হলো।',
    source: 'সূরা ইউসুফ',
  ),
  'prophet-5': StoryTranslation(
    title: 'মূসা আলাইহিস সালাম ও বনী ইসরাইলের বহির্গমন',
    body:
        'ফিরাউন শতাব্দীর পর শতাব্দী ধরে মিশরে বনী ইসরাইলকে '
        'দাসত্বে বাধ্য করেছিল, তাদের পুত্রদের হত্যা করত এবং নারীদের '
        'বাঁচিয়ে রাখত এই ভবিষ্যদ্বাণীর ভয়ে যে তাদের মধ্যে একটি '
        'পুত্র তার রাজত্বের পতনের কারণ হবে। মূসা এই সময়ে জন্মগ্রহণ '
        'করলেন, আল্লাহ তাঁর মাকে ওহী দিলেন যে ভয় পেলে তাঁকে '
        'একটি বাক্সে রেখে নদীতে ভাসিয়ে দিতে, পানি তাঁকে সরাসরি '
        'ফিরাউনের প্রাসাদে পৌঁছে দিল, সেখানে ফিরাউনের স্ত্রী আসিয়া '
        'তাঁকে পেলেন এবং তীব্রভাবে ভালোবাসলেন, ফিরাউনের প্রাথমিক '
        'বিরোধিতা সত্ত্বেও তাঁকে লালন-পালনের জন্য জোর দিলেন। '
        'আর এটা নির্ধারিত ছিল যে মূসা কেবল তাঁর প্রকৃত মায়ের বুকের '
        'দুধ পান করবেন কেউ না জেনে, কারণ তিনি প্রতিটি অন্য দুধ '
        'মায়ের দুধ প্রত্যাখ্যান করছিলেন যতক্ষণ না তারা তাঁর মাকে '
        'নিয়ে এলো, আল্লাহ এভাবে তাঁকে গ্রহণ করালেন তাঁর থেকে '
        'জোরপূর্বক বিচ্ছেদের পর একটি রহমত হিসেবে। মূসা ফিরাউনের '
        'ঘরেই বড় হলেন, বড় হয়ে তিনি ভুলবশত এক মিশরীয়কে হত্যা '
        'করলেন তাঁর সম্প্রদায়ের একজনকে রক্ষা করতে গিয়ে, তিনি '
        'ভয়ে মাদইয়ানে পালিয়ে গেলেন, সেখানে তিনি বিয়ে করলেন '
        'এবং বছরের পর বছর রাখাল হিসেবে কাজ করলেন। ফেরার পথে, '
        'তিনি তুর পাহাড়ের কাছে একটি আগুন দেখলেন, তিনি তা থেকে '
        'একটি অঙ্গার আনতে গেলেন, তাঁর রব সেখানে সরাসরি তাঁকে '
        'ডাকলেন এবং তাঁকে অহংকারী ও ঈশ্বরত্ব দাবিকারী ফিরাউনের '
        'কাছে যাওয়ার নির্দেশ দিলেন, তাঁকে লাঠি ও সাদা হাতের '
        'নিদর্শন দিলেন। মূসা তাঁর ভাই হারুনের সাথে ফিরাউনের কাছে '
        'গেলেন তাঁকে আল্লাহর ইবাদত করতে এবং বনী ইসরাইলকে মুক্ত '
        'করতে আহ্বান জানাতে, সে অহংকার করল এবং পূর্বে বর্ণিত '
        'হিসেবে তার জাদুকরদের নিয়ে তাঁকে চ্যালেঞ্জ করল; যখন '
        'জাদুকররা ঈমান আনল, ফিরাউন তাদের হুমকি দিল, কিন্তু তারা '
        'তাদের ঈমানে অবিচল রইল। ফিরাউন পরপর নিদর্শনগুলো — '
        'বন্যা, পঙ্গপাল, উকুন, ব্যাঙ, রক্ত — সত্ত্বেও তার অহংকারে '
        'অটল রইল, শেষ পর্যন্ত আল্লাহ মূসাকে বনী ইসরাইলসহ রাতে '
        'বের হওয়ার অনুমতি দিলেন। ফিরাউন তার সৈন্যবাহিনী নিয়ে '
        'তাদের অনুসরণ করল এবং সমুদ্রের তীরে তাদের ধরে ফেলল, '
        'মূসার সঙ্গীরা বলল: "আমরা নিশ্চিতভাবে ধরা পড়ব!" মূসা '
        'দৃঢ় বিশ্বাসের সাথে উত্তর দিলেন: "কখনো না, নিশ্চয়ই আমার '
        'রব আমার সাথে আছেন, তিনি আমাকে পথ দেখাবেন।" আল্লাহ '
        'তাঁকে তাঁর লাঠি দিয়ে সমুদ্রে আঘাত করার ওহী দিলেন, সমুদ্র '
        'বারোটি শুকনো পথে বিভক্ত হলো, তাদের মাঝে পানি পাহাড়ের '
        'মতো দাঁড়িয়ে থাকল, বনী ইসরাইল সবাই নিরাপদে পার হলো। '
        'যখন ফিরাউন ও তার সৈন্যবাহিনী একই পথে তাদের অনুসরণ '
        'করার চেষ্টা করল, আল্লাহ সমুদ্রকে তাদের ওপর বন্ধ করে দিলেন '
        'এবং তাদের সবাইকে ডুবিয়ে দিলেন বনী ইসরাইলের চোখের '
        'সামনে, যারা শতাব্দীর পর শতাব্দী তাদের দাসত্বে বাধ্যকারী '
        'অত্যাচারীর সমাপ্তি দেখল একই মুহূর্তে।',
    source:
        'সূরা আল-কাসাস: ৭-৪৩, সূরা আশ-শুআরা: ১০-৬৮ ও সূরা '
        'ত্বহা',
  ),
  'prophet-6': StoryTranslation(
    title: 'ইউনুস আলাইহিস সালাম ও মাছওয়ালা',
    body:
        'ইউনুস আলাইহিস সালামকে নিনেভার অধিবাসীদের কাছে '
        'তাওহীদের দাওয়াত দেওয়ার জন্য পাঠানো হয়েছিল, কিন্তু তারা '
        'প্রজন্মের পর প্রজন্ম কুফরিতে অবিচল রইল যতক্ষণ না তাঁর '
        'হৃদয় সংকুচিত হলো, তিনি তাদের ঈমান না আনলে নিকটবর্তী '
        'শাস্তির হুমকি দিলেন, তারপর তাঁর রবের অনুমতি পাওয়ার আগেই '
        'রাগান্বিত হয়ে তাদের ছেড়ে গেলেন, আল্লাহ পরে এর জন্য তাঁকে '
        'তিরস্কার করলেন। ইউনুস অন্যদের সাথে একটি নৌকায় চড়লেন, '
        'যখন তারা সমুদ্রের মাঝে পৌঁছালেন তখন ঢেউ উত্তাল হলো এবং '
        'বিপদ এত বেড়ে গেল যে নৌকা তার যাত্রীসহ ডুবে যাওয়ার '
        'উপক্রম হলো, তখন যাত্রীরা ভার হালকা করার জন্য কাকে সমুদ্রে '
        'নিক্ষেপ করা হবে তা নির্ধারণের জন্য লটারি করার সিদ্ধান্ত '
        'নিল, লটারিতে ইউনুসের নাম উঠল, তাঁকে উত্তাল সমুদ্রে নিক্ষেপ '
        'করা হলো; আল্লাহর নির্দেশে একটি বিশাল মাছ তাঁকে গিলে '
        'ফেলল, তাঁর মাংস না খেয়ে এবং তাঁর হাড় না ভেঙে, একটি '
        'অস্থায়ী কারাগার হিসেবে। ইউনুস নিজেকে তিন অন্ধকারে খুঁজে '
        'পেলেন: মাছের পেটের অন্ধকার, সমুদ্রের অন্ধকার এবং রাতের '
        'অন্ধকার; তিনি তাঁর সম্প্রদায়কে অনুমতি ছাড়া ছেড়ে যাওয়ার '
        'ভুল বুঝলেন, তিনি তাঁর রবের তাসবীহ পড়তে এবং কুরআনের '
        'চিরস্থায়ী করা সেই দোয়া দিয়ে ক্ষমা চাইতে শুরু করলেন: '
        '"আপনি ব্যতীত কোনো ইলাহ নেই, আপনি পবিত্র, নিশ্চয়ই আমি '
        'জালিমদের অন্তর্ভুক্ত ছিলাম।" আল্লাহ তাঁর দোয়া তৎক্ষণাৎ '
        'কবুল করলেন এবং মাছকে তাঁকে তীরে ফেলে দেওয়ার নির্দেশ '
        'দিলেন; ইউনুস একটি নবজাতকের মতো দুর্বল দেহে বেরিয়ে '
        'এলেন, আল্লাহ তাঁর ওপর একটি লাউ গাছ জন্মালেন যা তাঁকে '
        'ছায়া দিত এবং সূর্যের তাপ থেকে রক্ষা করত যতক্ষণ না তাঁর '
        'শক্তি ফিরে এলো। রাগান্বিত হয়ে তিনি যে সম্প্রদায়কে ত্যাগ '
        'করেছিলেন তারা প্রতিশ্রুত শাস্তির লক্ষণগুলো নিকটবর্তী হতে '
        'দেখল, শেষ মুহূর্তে সবাই আল্লাহর কাছে তওবা করল, আল্লাহ '
        'তাদের থেকে শাস্তি প্রত্যাহার করলেন; ইতিহাসে তারাই একমাত্র '
        'সম্প্রদায় যারা শাস্তির লক্ষণ দেখার পর সম্পূর্ণরূপে ঈমান '
        'এনেছিল এবং তাদের ঈমান তাদের উপকার করেছিল; এটাই '
        'কুরআন ইঙ্গিত করেছে তাঁর বাণীতে: "কেন কোনো জনপদ '
        'ঈমান আনল না যাতে তাদের ঈমান তাদের উপকার করত, শুধু '
        'ইউনুসের সম্প্রদায় ব্যতীত।"',
    source:
        'সূরা আস-সাফফাত: ১৩৯-১৪৮, সূরা আল-আম্বিয়া: '
        '৮৭-৮৮ ও সূরা ইউনুস: ৯৮',
  ),
  'prophet-7': StoryTranslation(
    title: 'আইয়ুব আলাইহিস সালাম ও তাঁর বিপদে ধৈর্য',
    body:
        'আইয়ুব আলাইহিস সালাম ছিলেন একজন ধনী নবী, প্রচুর '
        'সম্পদ ও সন্তানের অধিকারী, প্রতিটি নিয়ামতের জন্য তাঁর রবের '
        'কাছে কৃতজ্ঞ; আল্লাহ তাঁর ধৈর্য পরীক্ষা করার জন্য তাঁকে '
        'বিভিন্ন ধরনের বিপদে ফেললেন: তাঁর সব সম্পদ চলে গেল, '
        'তাঁর সব সন্তান মারা গেল, তারপর তাঁর দেহে এমন তীব্র রোগ '
        'হলো যে তাঁর চামড়া ক্ষতবিক্ষত হলো এবং তাঁর আশেপাশের '
        'মানুষ তাঁর থেকে দূরে সরে গেল কেবল তাঁর স্ত্রী ব্যতীত যিনি '
        'বিশ্বস্ত থেকে বছরের পর বছর তীব্র বিপদ সত্ত্বেও তাঁর সেবা '
        'করলেন। এসব সত্ত্বেও, তাঁর জিহ্বা আল্লাহর স্মরণ থেকে '
        'কখনো থামেনি এবং তিনি তাঁর রবের কাছে অভিযোগ করেননি, '
        'বরং তিনি সব অবস্থায় আল্লাহকে স্মরণ করেছেন এবং পরীক্ষার '
        'আগের নিয়ামতের জন্য তাঁর প্রশংসা করেছেন। রোগের বছরগুলো '
        'দীর্ঘায়িত হলো, বলা হয় আঠারো বছর পর্যন্ত, শেষ পর্যন্ত, যখন '
        'কষ্ট সহনশীলতার বাইরে গেল, তিনি অভিযোগকারীর অভদ্রতা '
        'নয় বরং প্রার্থনাকারীর শিষ্টাচারের সাথে তাঁর হাত তাঁর রবের '
        'দিকে তুললেন এবং বললেন: "আমার ক্ষতি হয়েছে, আর আপনি '
        'পরম দয়ালুদের মধ্যে সর্বাধিক দয়ালু।" তিনি স্পষ্টভাবে বিপদ '
        'অপসারণের অনুরোধ করেননি, বরং শুধু তাঁর অবস্থা তাঁর রবের '
        'কাছে উপস্থাপন করেছিলেন; আল্লাহ তাঁর প্রার্থনা তৎক্ষণাৎ '
        'কবুল করলেন এবং তাঁকে তাঁর পা মাটিতে আঘাত করার নির্দেশ '
        'দিলেন, তার নিচ থেকে শীতল পানি প্রবাহিত হলো, তিনি তা '
        'থেকে পান করলেন এবং গোসল করলেন, তাঁর সব রোগ ও কষ্ট '
        'দূর হলো; আল্লাহ তাঁকে তাঁর পরিবার ফিরিয়ে দিলেন এবং '
        'রহমতস্বরূপ আরও দ্বিগুণ দিলেন, তাঁর স্বাস্থ্য ও যৌবন ফিরিয়ে '
        'দিলেন যেন কিছুই ঘটেনি। আইয়ুবের ধৈর্য আজ পর্যন্ত প্রতিটি '
        'ভাষায় একটি দৃষ্টান্ত হয়ে গেছে, বলা হয়: "আইয়ুবের মতো '
        'ধৈর্য," এটি প্রমাণ করে যে সন্তুষ্টির সাথে সুন্দর ধৈর্যই '
        'স্বস্তির পথ, পরীক্ষা যত দীর্ঘই হোক না কেন।',
    source: 'সূরা আল-আম্বিয়া: ৮৩-৮৪ ও সূরা সাদ: ৪১-৪৪',
  ),
  'prophet-8': StoryTranslation(
    title: 'দাউদ ও সুলাইমান আলাইহিমাস সালাম ফসলের মামলায়',
    body:
        'দুইজন লোক দাউদ আলাইহিস সালামের কাছে বিচারের জন্য '
        'এলো, একজনের ফসল ছিল, অন্যজনের ভেড়া ছিল; একজনের '
        'ভেড়া রাতে অন্যজনের ফসলে ঢুকে না জেনে সবকিছু নষ্ট করে '
        'দিল। দাউদ আলাইহিস সালাম রায় দিলেন যে সব ভেড়া ফসলের '
        'মালিককে তার ক্ষতিপূরণ হিসেবে দেওয়া হবে, এটি বাহ্যত '
        'একটি ন্যায্য রায় ছিল। কিন্তু তাঁর পুত্র সুলাইমান, যিনি তখনও '
        'অল্প বয়সী ছিলেন, তাঁর পিতাকে আরেকটি মতামত উপস্থাপন '
        'করলেন যা উভয় পক্ষের প্রতি আরও নরম ছিল: ফসলের মালিক '
        'সাময়িকভাবে ভেড়াগুলো ব্যবহারের জন্য নিয়ে যাবেন, তাদের '
        'দুধ, পশম ও বাচ্চা থেকে উপকৃত হবেন, আর ভেড়ার মালিক '
        'জমি চাষ করে তা পূর্বাবস্থায় বা আরও ভালোভাবে ফিরিয়ে '
        'আনবেন; ফসল ভালো হলে ভেড়া তার মালিকের কাছে এবং ফসল '
        'তার মালিকের কাছে ফিরিয়ে দেওয়া হবে, যাতে কারো স্থায়ী '
        'ক্ষতি না হয়। দাউদ আলাইহিস সালাম তাঁর ছেলের গভীর প্রজ্ঞায় '
        'মুগ্ধ হলেন তাঁর কম বয়স সত্ত্বেও, এবং তাঁর রায় গ্রহণ করলেন '
        'কারণ এটি মানুষের প্রতি আরও নরম এবং পূর্ণ ন্যায়বিচার '
        'অর্জনে আরও সঠিক ছিল। আল্লাহ কুরআনে তাদের উভয়কেই '
        'প্রশংসা করেছেন: "তখন আমরা এটি সুলাইমানকে বুঝিয়ে দিলাম, '
        'আর প্রত্যেককেই আমরা হিকমত ও জ্ঞান দিয়েছি," এটি স্পষ্ট '
        'করার জন্য যে বিচারে ইজতিহাদ জ্ঞানীদের মধ্যেও ভিন্ন হতে '
        'পারে, আর আল্লাহ যাকে চান তাকে আরও সঠিক ও নরম পথের '
        'দিকে পরিচালিত করেন অন্যের কোনো ত্রুটি ছাড়াই।',
    source: 'সূরা আল-আম্বিয়া: ৭৮-৭৯',
  ),
  'prophet-9': StoryTranslation(
    title: 'সুলাইমান আলাইহিস সালাম, হুদহুদ ও সাবার রানী',
    body:
        'আল্লাহ সুলাইমান আলাইহিস সালামকে একটি বিশাল রাজত্ব '
        'দিলেন, বাতাস, জিন ও পাখিদের তাঁর অধীন করে দিলেন এবং '
        'তাঁকে প্রাণীদের ভাষা শেখালেন, তিনি তাঁর সৈন্যদের পর্যবেক্ষণ '
        'করতেন এবং গণনা করতেন, একদিন তিনি পাখিদের পর্যবেক্ষণ '
        'করলেন এবং তাদের মধ্যে হুদহুদকে খুঁজে পেলেন না, তিনি '
        'তাকে কঠোর শাস্তি বা জবাই করার হুমকি দিলেন যদি সে স্পষ্ট '
        'অজুহাত না দেয়। কিছুক্ষণ পরেই হুদহুদ একটি বড় খবর নিয়ে '
        'ফিরে এলো যা কাহিনির গতিপথ পরিবর্তন করে দিল: "আমি একজন '
        'নারীকে দেখলাম যে তাদের শাসন করছে, তাকে সবকিছু দেওয়া '
        'হয়েছে এবং তার একটি বিশাল সিংহাসন আছে; কিন্তু সে ও তার '
        'সম্প্রদায় আল্লাহ ব্যতীত সূর্যকে সিজদা করে, শয়তান তাদের '
        'কর্মকে তাদের কাছে সুশোভিত করেছে এবং তাদের সঠিক পথ '
        'থেকে বাধা দিয়েছে।" সুলাইমান হুদহুদকে শাস্তি দিলেন না, তার '
        'খবরের সত্যতা যাচাই করলেন, তিনি সেই রানীকে — সাবার রানী '
        'বিলকিসকে — একটি চিঠি লিখলেন এবং হুদহুদের মাধ্যমে '
        'তার কাছে পাঠালেন। বিলকিস তার সম্প্রদায়ের নেতাদের সামনে '
        'চিঠিটি পড়ল এবং বলল: "এটি সুলাইমানের পক্ষ থেকে এবং এটি '
        '— আল্লাহর নামে, যিনি পরম করুণাময়, অতি দয়ালু, তোমরা '
        'আমার বিরুদ্ধে অহংকার করো না এবং আত্মসমর্পণকারী হয়ে '
        'আমার কাছে এসো।" সে তার সম্প্রদায়ের পরামর্শ নিল, তারা '
        'শক্তির পরামর্শ দিল কারণ তারা শক্তিশালী ছিল, কিন্তু তার '
        'প্রজ্ঞা তাকে সংঘর্ষের চেয়ে প্রজ্ঞা বেছে নিতে পরিচালিত করল, '
        'সে সুলাইমানের কাছে একটি উপহার পাঠাল তার উদ্দেশ্য যাচাই '
        'করতে, কিন্তু সুলাইমান তা ফিরিয়ে দিলেন, বললেন যে আল্লাহ '
        'তাঁকে যা দিয়েছেন তা তাকে দেওয়া জিনিসের চেয়ে ভালো, এবং '
        'তাকে এমন সৈন্যবাহিনীর হুমকি দিলেন যা সে সহ্য করতে '
        'পারবে না যদি সে আত্মসমর্পণকারী হয়ে না আসে। বিলকিস '
        'নিজে আসার সিদ্ধান্ত নিল, সুলাইমান একজন শক্তিশালী জিনকে '
        'তার আসার আগে তার সিংহাসন আনতে বললেন, সে নিজের '
        'জায়গা থেকে ওঠার আগে তা আনার প্রস্তাব দিল, কিন্তু যার '
        'কাছে কিতাবের কিছু জ্ঞান ছিল সে বলল: "আমি তোমার চোখের '
        'পলক ফেলার আগেই তা তোমার কাছে নিয়ে আসব," আর আল্লাহর '
        'অনুমতিতে তাই হলো। যখন বিলকিস এলো এবং তার সিংহাসন '
        'তার সামনে দেখল যা তাকে পরীক্ষা করার জন্য সামান্য পরিবর্তন '
        'করা হয়েছিল, সে তা চিনল; আর যখন সে একটি কাচের প্রাসাদে '
        'প্রবেশ করল তখন সে তা পানি মনে করে তার পা খুলল, তখন '
        'সুলাইমান তাকে জানালেন যে এটি কাচ দিয়ে তৈরি মসৃণ প্রাসাদ; '
        'তখন সে তার রাজত্বের মহত্ত্ব উপলব্ধি করল এবং বলল: "হে '
        'আমার রব, নিশ্চয়ই আমি নিজের প্রতি অন্যায় করেছি, আর '
        'আমি সুলাইমানের সাথে বিশ্বজগতের রব আল্লাহর কাছে '
        'আত্মসমর্পণ করলাম।"',
    source: 'সূরা আন-নামল: ২০-৪৪',
  ),
  'prophet-10': StoryTranslation(
    title: 'ঈসা আলাইহিস সালামের অলৌকিক জন্ম',
    body:
        'ইমরানের কন্যা মারইয়াম ছিলেন একজন ধার্মিক কন্যা যিনি '
        'তাঁর পরিবার থেকে আলাদা হয়ে তাঁর নিজস্ব একটি মিহরাবে '
        'ইবাদতে নিমগ্ন ছিলেন, তখন জিবরাইল আলাইহিস সালাম '
        'তাঁর কাছে একজন পূর্ণাঙ্গ মানুষের রূপে এলেন, তিনি ভয় '
        'পেয়ে বললেন: "আমি আপনার থেকে পরম করুণাময়ের কাছে '
        'আশ্রয় চাই, যদি আপনি আল্লাহভীরু হন।" তিনি তাঁকে আশ্বস্ত '
        'করলেন: "আমি তো কেবল আপনার রবের প্রেরিত দূত, আপনাকে '
        'একটি পবিত্র পুত্র দান করার জন্য।" মারইয়াম অত্যন্ত বিস্মিত '
        'হয়ে বললেন: "আমার কীভাবে পুত্র হবে যখন কোনো মানুষ '
        'আমাকে স্পর্শ করেনি এবং আমি ব্যভিচারিণীও নই?" তিনি উত্তর '
        'দিলেন: "এমনই হবে, আপনার রব বলেছেন: এটি আমার জন্য '
        'সহজ, আর আমরা তাকে মানুষের জন্য একটি নিদর্শন এবং '
        'আমাদের পক্ষ থেকে একটি রহমত বানাব।" মারইয়াম কেবল '
        'আল্লাহর নির্দেশে গর্ভবতী হলেন, পিতা ছাড়াই; মানুষের '
        'কথার ভয়ে তিনি তাঁর সম্প্রদায় থেকে দূরে একটি স্থানে সরে '
        'গেলেন, প্রসববেদনা তাঁকে একটি পুরনো খেজুর গাছের কাণ্ডের '
        'কাছে নিয়ে এলো, তীব্র বেদনা ও একাকীত্বে তিনি বললেন: '
        '"হায়, আমি যদি এর আগে মারা যেতাম এবং সম্পূর্ণ বিস্মৃত হয়ে '
        'যেতাম!" তখন তাঁর নিচ থেকে — বা জন্মগ্রহণকারী শিশু নিজেই '
        '— তাঁকে ডাকল: "দুঃখ করবেন না, আপনার রব আপনার নিচে '
        'একটি ঝর্ণা প্রবাহিত করেছেন, খেজুর গাছের কাণ্ড আপনার '
        'দিকে নাড়ান, এটি আপনার জন্য তাজা পাকা খেজুর ঝরাবে।" '
        'আল্লাহ তাঁকে তাঁর একাকীত্বে এই রিজিক দিয়ে সম্মানিত '
        'করলেন। মারইয়াম তাঁর শিশুকে তাঁর সম্প্রদায়ের কাছে নিয়ে '
        'এলেন, তাঁকে দেখে তারা নিন্দা করল এবং তাঁর কাছ থেকে '
        'একটি কথাও না শুনে অন্যায়ভাবে তাঁকে অভিযুক্ত করল, তিনি '
        'শিশুর দিকে ইশারা করলেন যাতে তারা তার সাথে কথা বলে; '
        'তারা বিস্মিত হয়ে বলল: "কোলে থাকা শিশুর সাথে আমরা কীভাবে '
        'কথা বলব?" ঈসা আরেকটি মুজিজায় কথা বললেন যদিও তিনি '
        'তখনও কথা বলার বয়সে পৌঁছাননি এমন একজন শিশু ছিলেন, '
        'তিনি বললেন: "আমি আল্লাহর বান্দা, তিনি আমাকে কিতাব '
        'দিয়েছেন এবং আমাকে নবী বানিয়েছেন, আমি যেখানেই থাকি '
        'তিনি আমাকে বরকতময় করেছেন, আমাকে জীবিত থাকা পর্যন্ত '
        'সালাত ও যাকাতের নির্দেশ দিয়েছেন, আমার মায়ের প্রতি '
        'সদাচরণেরও, তিনি আমাকে অহংকারী দুর্ভাগা বানাননি।" '
        'সবাই স্তম্ভিত হয়ে গেল এবং তাদের সন্তানের কোলে থেকে '
        'কথা বলার মুজিজায় মারইয়ামের পবিত্রতা জানল।',
    source: 'সূরা মারইয়াম: ১৬-৩৩ ও সূরা আলে ইমরান: ৪৫-৪৭',
  ),
  'prophet-11': StoryTranslation(
    title: 'মূসার মায়ের তাঁকে নদীতে ভাসিয়ে দেওয়া',
    body:
        'সেই সময়ে যখন ফিরাউন বনী ইসরাইলের প্রতিটি নবজাত '
        'পুত্রকে হত্যা করত এই ভবিষ্যদ্বাণীর ভয়ে যে তাদের মধ্যে '
        'একটি পুত্র তার রাজত্বের পতনের কারণ হবে, মূসার মা তাঁর '
        'পুত্রকে সবচেয়ে বিপজ্জনক সময়ে জন্ম দিলেন, তাঁর হৃদয় '
        'ফিরাউনের গুপ্তচরদের ভয়ে কাঁপছিল যারা প্রতিটি ঘর অনুসন্ধান '
        'করছিল। আল্লাহ তাঁকে ওহী দিলেন — নবুওয়তের ওহী নয়, '
        'ইলহামের ওহী — এমন একটি নির্দেশ যা প্রথম দৃষ্টিতে বাড়িতে '
        'রাখার চেয়ে আরও বিপজ্জনক মনে হয়েছিল: "তাকে দুধ পান '
        'করান, যখন আপনি তার জন্য ভয় পান তখন তাকে নদীতে '
        'ভাসিয়ে দিন, ভয় পাবেন না এবং দুঃখ করবেন না, নিশ্চয়ই '
        'আমরা তাকে আপনার কাছে ফিরিয়ে দেব এবং তাকে রাসূলদের '
        'অন্তর্ভুক্ত করব।" এটি একজন মায়ের ঈমানের জন্য একটি বিশাল '
        'পরীক্ষা ছিল তাঁর শিশুকে নিজ হাতে প্রবাহিত নদীতে ফেলে '
        'দেওয়া, কিন্তু তিনি বিস্ময়কর বিশ্বাসের সাথে আনুগত্য করলেন, '
        'তাঁকে একটি শক্তভাবে বন্ধ বাক্সে রাখলেন এবং নীল নদের '
        'পানিতে ভাসিয়ে দিলেন। তিনি তাঁর কন্যাকে — মূসার বোনকে '
        '— বাক্সটি দূর থেকে অনুসরণ করতে নির্দেশ দিলেন যাতে '
        'কেউ টের না পেয়ে দেখতে পারেন এটি কোথায় থামে। ঢেউ '
        'বাক্সটিকে সরাসরি ফিরাউনের প্রাসাদে নিয়ে গেল, প্রাসাদের '
        'লোকেরা তা তুলে নিল; ফিরাউনের স্ত্রী আসিয়া প্রথম দৃষ্টিতেই '
        'তাকে তীব্রভাবে ভালোবাসলেন এবং ফিরাউনের প্রাথমিক হত্যার '
        'ইচ্ছা সত্ত্বেও তাকে দত্তক নিতে জোর দিলেন। এখানেই দ্বিতীয় '
        'মুজিজা ঘটল: আল্লাহ শিশুটিকে যেকোনো দুধ মায়ের দুধ '
        'গ্রহণ করা থেকে বিরত রাখলেন যাকে আনা হতো, সে যতই '
        'চেষ্টা করুক না কেন সবাইকে প্রত্যাখ্যান করত, এমনকি প্রাসাদের '
        'লোকেরা তার ক্ষুধা নিয়ে উদ্বিগ্ন হয়ে পড়ল। তখনই তাঁর বোন '
        '— যিনি দূর থেকে পর্যবেক্ষণ করছিলেন — চতুরতার সাথে '
        'এগিয়ে এসে তাদের প্রস্তাব দিলেন: "আমি কি আপনাদের এমন '
        'একটি পরিবার দেখাব যারা তার জন্য যত্ন নেবে এবং তার প্রতি '
        'মঙ্গলাকাঙ্ক্ষী হবে?" তারা তার উদ্দেশ্য নিয়ে সন্দেহ না করে '
        'রাজি হলো, তিনি তাঁর প্রকৃত মাকে নিয়ে এলেন, তখন শিশুটি '
        'সাথে সাথে বিনা দ্বিধায় তার দুধ গ্রহণ করল। এভাবে আল্লাহ '
        'মূসাকে তাঁর মায়ের কোলে ফিরিয়ে দিলেন যাতে তিনি ফিরাউনের '
        'প্রাসাদেই তাঁকে দুধ পান করান, সেই ভাণ্ডার থেকে পারিশ্রমিক '
        'নিয়ে যার মালিক তাঁর ছেলেকে হত্যা করতে চেয়েছিল — এটি '
        'ছিল আল্লাহর সেই প্রতিশ্রুতির পূর্ণতা যা দিয়ে তিনি তাঁকে '
        'শান্ত করেছিলেন: "যাতে তার চোখ শীতল হয় এবং সে দুঃখ না '
        'করে, আর যাতে সে জানে যে আল্লাহর প্রতিশ্রুতি সত্য, কিন্তু '
        'অধিকাংশ মানুষ জানে না।"',
    source: 'সূরা আল-কাসাস: ৭-১৩',
  ),
  'prophet-12': StoryTranslation(
    title: 'আসিয়া, ফিরাউনের স্ত্রী',
    body:
        'মুজাহিমের কন্যা আসিয়া ছিলেন স্বয়ং ফিরাউনের স্ত্রী, তিনি '
        'পৃথিবীর সবচেয়ে বড় ও জাঁকজমকপূর্ণ প্রাসাদে বাস করতেন, '
        'কিন্তু তাঁর হৃদয় তাঁর অত্যাচারী স্বামীর মতো ছিল না। যখন '
        'তাঁর দাসরা নীল নদের পানিতে ভাসমান একটি বাক্স পেল '
        'যাতে একটি সুন্দর শিশু ছিল, তিনি তৎক্ষণাৎ তাকে তীব্রভাবে '
        'ভালোবাসলেন এবং ফিরাউনের কাছে তাকে হত্যা না করার '
        'জন্য অনুরোধ করলেন সেই কথাগুলো দিয়ে যা কুরআন চিরস্থায়ী '
        'করেছে: "এ আমার ও তোমার চোখের শীতলতা, একে হত্যা '
        'করো না, হয়তো সে আমাদের উপকার করবে বা আমরা তাকে '
        'সন্তান হিসেবে গ্রহণ করব।" তখন ফিরাউন অনিচ্ছায় রাজি হলো, '
        'না জেনে যে সে তার ঘরেই এমন একজনকে বড় করছে যে '
        'তার ধ্বংসের কারণ হবে। বছরের পর বছর ধরে, আসিয়া নিজ '
        'চোখে মূসার মুজিজা এবং তাঁর দাওয়াতের সত্যতা দেখলেন, '
        'তখন তাঁর হৃদয় গোপনে কেবল মূসা ও হারুনের রবের ওপর '
        'ঈমান আনল, অথচ তাঁর স্বামী তখনও ঈশ্বরত্ব দাবি করছিল। '
        'তিনি তাঁর স্বামীর অত্যাচারের ভয়ে দীর্ঘ বছর তাঁর ঈমান '
        'গোপন রাখলেন, কিন্তু শেষ পর্যন্ত বিষয়টি প্রকাশ পেল, তখন '
        'ফিরাউন তার নিজের স্ত্রীর প্রতি তীব্রভাবে ক্রুদ্ধ হলো এবং '
        'তার অসুস্থ চিন্তাধারায় তার ইলাহ ছাড়া অন্যের প্রতি ঈমান '
        'আনার "অপরাধের" উপযুক্ত মনে হওয়া একটি শাস্তি দেওয়ার '
        'সিদ্ধান্ত নিল: সে নির্দেশ দিল তাঁর হাত-পা খুঁটি দিয়ে জ্বলন্ত '
        'মরুভূমির সূর্যের নিচে মাটিতে বেঁধে রাখতে, আর তাঁর ওপর '
        'একটি ভারী পাথর রাখতে যাতে তাঁর যন্ত্রণা বাড়ে। তাঁর '
        'জীবনের এই শেষ মুহূর্তগুলোতে, দেহের কষ্ট ও ঈমানের '
        'দৃঢ়তার মধ্যে, আসিয়া তাঁর হৃদয় তাঁর রবের দিকে তুললেন '
        'এমন একটি বিস্ময়কর দোয়া দিয়ে যাতে তিনি দুনিয়ার শাস্তি '
        'অপসারণের প্রার্থনা করেননি, বরং তার চেয়ে অনেক বড় কিছু '
        'চাইলেন: "হে আমার রব, আপনার কাছে জান্নাতে আমার জন্য '
        'একটি ঘর নির্মাণ করুন, আর আমাকে ফিরাউন ও তার কাজ '
        'থেকে মুক্তি দিন, আর আমাকে জালিম সম্প্রদায় থেকে মুক্তি '
        'দিন।" আল্লাহ তাঁর দোয়া কবুল করলেন এবং তাঁর মৃত্যুর '
        'আগে তাঁকে জান্নাতে তাঁর ঘর দেখালেন, তখন দুনিয়ার সব '
        'কষ্ট তাঁর জন্য সহজ হয়ে গেল যখন তিনি নিজ চোখে তাঁর '
        'ধৈর্যের ফল দেখলেন। নবী ﷺ তাঁকে ইমরানের কন্যা মারইয়াম, '
        'খাদিজা ও ফাতিমা রাদিয়াল্লাহু আনহুন্নার সাথে সমগ্র বিশ্বের '
        'সর্বোত্তম নারীদের একজন হিসেবে উল্লেখ করেছেন।',
    source:
        'সূরা আত-তাহরিম: ১১ ও সূরা আল-কাসাস: ৯ — সহীহ '
        'বুখারী',
  ),
  'prophet-13': StoryTranslation(
    title: 'মূসা আলাইহিস সালাম ও খিজির',
    body:
        'একদিন মূসা আলাইহিস সালাম বনী ইসরাইলের মধ্যে বক্তৃতা '
        'দিচ্ছিলেন, তখন তাঁকে জিজ্ঞেস করা হলো: পৃথিবীর মানুষের '
        'মধ্যে সবচেয়ে জ্ঞানী কে? তিনি বললেন: আমি, এই বিশ্বাস '
        'করে যে ওহীর মাধ্যমে তাঁর জ্ঞান তাঁকে তেমনই করে তোলে। '
        'তখন আল্লাহ তাঁকে জ্ঞান তাঁর কাছে ফিরিয়ে না দেওয়ার '
        'জন্য তিরস্কার করলেন এবং তাঁকে জানালেন যে তাঁর একজন '
        'বান্দা দুই সমুদ্রের মিলনস্থলে আছেন যিনি নির্দিষ্ট কিছু বিষয়ে '
        'তাঁর চেয়ে বেশি জ্ঞানী, তখন মূসা তাঁর সাথে সাক্ষাতের '
        'ইচ্ছা প্রকাশ করলেন যাতে তিনি শিখতে পারেন, আর সাক্ষাতের '
        'চিহ্ন নির্ধারিত হলো তাঁর থলিতে বহন করা লবণাক্ত মাছটি '
        'হারানো যখন তা জীবিত হয়ে সমুদ্রে ঝাঁপ দেবে। আর সত্যিই, '
        'মূসা ও তাঁর সঙ্গী একটি পাথরের কাছে মাছটি ভুলে গেলেন, '
        'তখন তাঁরা তাঁদের পদচিহ্ন অনুসরণ করে ফিরে এলেন শেষ '
        'পর্যন্ত খিজিরকে খুঁজে পেলেন। মূসা বিনয়ের সাথে অনুরোধ '
        'করলেন তাঁর সাথে থাকতে যাতে তিনি আল্লাহ তাঁকে যা '
        'শিখিয়েছেন তা থেকে শিখতে পারেন, তখন খিজির তাঁকে '
        'একটি স্পষ্ট শর্ত দিলেন: "আপনি আমার সাথে ধৈর্য ধরতে '
        'পারবেন না, আর আপনি যে বিষয়ে জ্ঞান রাখেন না তাতে '
        'কীভাবে ধৈর্য ধরবেন?" মূসা প্রতিশ্রুতি দিলেন যে তিনি '
        'ধৈর্য ধরবেন এবং তিনি নিজে না বলা পর্যন্ত কিছু জিজ্ঞেস '
        'করবেন না। তাঁরা দুজন একটি নৌকায় বিনামূল্যে চড়লেন, '
        'তখন হঠাৎ খিজির তা ছিদ্র করলেন! মূসা তাঁর প্রতিশ্রুতি '
        'সত্ত্বেও নিজেকে সংযত রাখতে পারলেন না এবং বললেন: '
        '"আপনি কি একে ছিদ্র করলেন এর যাত্রীদের ডুবিয়ে দেওয়ার '
        'জন্য? আপনি তো ভয়ানক একটি কাজ করেছেন।" তখন খিজির '
        'তাঁকে তাঁর প্রথম শর্ত স্মরণ করিয়ে দিলেন। তারপর তাঁরা '
        'দুজন একটি ছোট বালকের সাথে সাক্ষাৎ করলেন, তখন খিজির '
        'কোনো স্পষ্ট কারণ ছাড়াই তাকে হত্যা করলেন, তখন মূসা '
        'দ্বিতীয়বার আপত্তি জানিয়ে চিৎকার করে বললেন: "আপনি কি '
        'একটি নিষ্পাপ প্রাণকে অন্য কোনো প্রাণের বিনিময় ছাড়াই '
        'হত্যা করলেন? আপনি তো অত্যন্ত জঘন্য একটি কাজ করেছেন।" '
        'খিজির তাঁকে বললেন: "আমি কি আপনাকে বলিনি যে আপনি '
        'আমার সাথে ধৈর্য ধরতে পারবেন না?" আর তাঁরা দুজন সম্মত '
        'হলেন যে এটিই শেষ সুযোগ। একটি তৃতীয় গ্রামে, তাঁরা '
        'গ্রামবাসীদের কাছে খাবার চাইলেন কিন্তু তাদের তীব্র ক্ষুধা '
        'সত্ত্বেও তারা আপ্যায়ন করতে অস্বীকার করল, তবুও তাঁরা '
        'একটি দেয়াল খুঁজে পেলেন যা ধসে পড়ার উপক্রম ছিল, তখন '
        'খিজির কোনো মজুরি না চেয়ে তা সোজা করে দিলেন! তখন '
        'মূসা তৃতীয়বার জিজ্ঞেস করলেন: "আপনি ইচ্ছা করলে এর '
        'জন্য মজুরি নিতে পারতেন।" খিজির বললেন: "এটিই আমার ও '
        'আপনার মধ্যে বিচ্ছেদ," এবং তিনি তাঁকে সবকিছু ব্যাখ্যা '
        'করলেন: নৌকাটি সমুদ্রে কাজ করা কিছু দরিদ্র মানুষের ছিল, '
        'তিনি এটিকে ত্রুটিযুক্ত করেছিলেন যাতে জোরপূর্বক প্রতিটি '
        'ভালো নৌকা নেওয়া একজন অত্যাচারী রাজা এটি না নেয়। '
        'আর বালকটি, তার পিতামাতা মুমিন ছিলেন এবং সে বড় হলে '
        'তার অবাধ্যতা ও কুফরি দিয়ে তাদের কষ্ট দিত, আল্লাহ '
        'চেয়েছিলেন তাদের রব তার বদলে তার চেয়ে বেশি পবিত্র '
        'ও দয়ায় নিকটতর একটি সন্তান দিন। আর দেয়ালটি, তার '
        'নিচে শহরের দুই এতিমের একটি ধনভাণ্ডার ছিল আর তাদের '
        'পিতা একজন সৎ ব্যক্তি ছিলেন, তখন আপনার রব চেয়েছিলেন '
        'তারা তাদের যৌবনে পৌঁছে তাদের ধনভাণ্ডার বের করুক, '
        'আপনার রবের পক্ষ থেকে একটি রহমত হিসেবে, আর আমি '
        'এটি নিজের ইচ্ছায় করিনি, অর্থাৎ এটি আল্লাহর পক্ষ থেকে '
        'ওহী ছিল ব্যক্তিগত মতামত নয়।',
    source: 'সূরা আল-কাহফ: ৬০-৮২',
  ),
  'prophet-14': StoryTranslation(
    title: 'ইসমাইলের কুরবানি ও মহান মুক্তিপণ',
    body:
        'ইব্রাহিম আলাইহিস সালাম স্বপ্নে দেখলেন তিনি তাঁর পুত্র '
        'ইসমাইলকে কুরবানি করছেন, আর নবীদের স্বপ্ন সত্য ওহী '
        'যাতে দ্বিধা করা বৈধ নয়। ইব্রাহিম তাঁর সিদ্ধান্ত তাঁর পুত্রের '
        'ওপর চাপিয়ে দিলেন না, বরং একজন স্নেহময় পিতার '
        'কোমলতার সাথে বিষয়টি তাঁর কাছে উপস্থাপন করলেন: "হে '
        'আমার পুত্র, আমি স্বপ্নে দেখছি যে আমি তোমাকে কুরবানি '
        'করছি, তুমি ভেবে দেখো তোমার মত কী?" ইসমাইল তখন '
        'তাঁর সাথে চলাফেরা করার বয়সে পৌঁছানো একটি ছোট বালক '
        'ছিলেন, তিনি তাঁর বয়সের চেয়ে বেশি ঈমান দিয়ে উত্তর '
        'দিলেন: "হে আমার পিতা, আপনাকে যা নির্দেশ দেওয়া হয়েছে '
        'তা করুন, আল্লাহ চাইলে আপনি আমাকে ধৈর্যশীলদের মধ্যে '
        'পাবেন।" শয়তান তাদের দুজনকে এই কঠিন নির্দেশ পালন '
        'থেকে বিরত রাখার চেষ্টা করল, সে ইব্রাহিমের সামনে তিন '
        'জায়গায় এসে তা না করার কুমন্ত্রণা দিল, তখন ইব্রাহিম '
        'প্রতিবার তার কুমন্ত্রণাকে সম্পূর্ণরূপে প্রত্যাখ্যান করে তাকে '
        'পাথর ছুঁড়ে মারলেন, আর এই তিনটি স্থানই আজ পর্যন্ত হজের '
        'অনুষ্ঠানে জামারাতে কংকর নিক্ষেপের উৎস। যখন পিতা ও '
        'পুত্র উভয়ে সম্পূর্ণরূপে আল্লাহর নির্দেশের কাছে আত্মসমর্পণ '
        'করলেন, আর ইব্রাহিম তাঁর পুত্রকে কপালের ওপর শুইয়ে '
        'দিলেন হাত দিয়ে নির্দেশ কার্যকর করার জন্য প্রস্তুত হয়ে, '
        'তখন নির্ণায়ক মুহূর্তে ঐশ্বরিক আহ্বান এলো: "হে ইব্রাহিম, '
        'তুমি স্বপ্নটি সত্য প্রমাণ করেছ, নিশ্চয়ই আমরা এভাবেই '
        'সৎকর্মশীলদের প্রতিদান দিই, নিশ্চয়ই এটি ছিল একটি '
        'স্পষ্ট পরীক্ষা।" প্রকৃতপক্ষে যা চাওয়া হয়েছিল তা রক্তপাত '
        'ছিল না, বরং পরীক্ষাটি ছিল পিতা ও পুত্র একসাথে বিনা '
        'দ্বিধায় প্রদর্শিত আত্মসমর্পণের সত্যতা ও পূর্ণ আনুগত্যের। '
        'আল্লাহ তাঁকে একটি মহান কুরবানি দিয়ে মুক্তিপণ দিলেন — '
        'জিবরাইল আলাইহিস সালামের মাধ্যমে জান্নাত থেকে '
        'নামানো একটি দুম্বা — যা ইসমাইলের পরিবর্তে জবাই করা '
        'হলো, আর আল্লাহ এই ঘটনাকে একটি চিরন্তন স্মৃতি বানালেন '
        'যা মুসলিমরা প্রতি বছর ঈদুল আজহায় পালন করে, যখন তারা '
        'এই মহান মুক্তিপণ অনুসরণ করে পশু কুরবানি দেয় এবং '
        'আল্লাহর নির্দেশের প্রতি এই বিরল আত্মসমর্পণকে স্মরণ করে।',
    source: 'সূরা আস-সাফফাত: ১০০-১১১',
  ),
  'prophet-15': StoryTranslation(
    title: 'লুত আলাইহিস সালাম ও তাঁর সম্প্রদায়',
    body:
        'লুত আলাইহিস সালামকে এমন একটি সম্প্রদায়ের কাছে '
        'পাঠানো হয়েছিল যারা এমন একটি অশ্লীলতা উদ্ভাবন করেছিল '
        'যা তাদের আগে বিশ্বের কেউ কখনো করেনি, তিনি তাদের '
        'বারবার এই মন্দ কাজ ছাড়ার আহ্বান জানালেন, কিন্তু তাদের '
        'উত্তর ছিল কেবল তাঁকে ও তাঁর পরিবারকে তাদের গ্রাম থেকে '
        'বহিষ্কারের হুমকি, তারা বলল: "লুতের পরিবারকে তোমাদের '
        'গ্রাম থেকে বের করে দাও, নিশ্চয়ই তারা পবিত্রতা রক্ষাকারী '
        'মানুষ," তারা তাদের সততা ও পবিত্রতা চাওয়ার কারণে '
        'উপহাস করছিল! গ্রামের বাসিন্দাদের মধ্যে তাঁর পরিবার '
        'ব্যতীত কেউ লুতের প্রতি ঈমান আনেনি, কেবল তাঁর স্ত্রী '
        'ব্যতীত যিনি তাদের কাজে তাঁর সম্প্রদায়কে সমর্থন করতেন, '
        'তখন তিনিও তাদের সাথে ধ্বংসপ্রাপ্তদের অন্তর্ভুক্ত হলেন। '
        'আল্লাহ তাঁর ফেরেশতাদের সুদর্শন যুবকদের রূপে পাঠালেন, '
        'তারা প্রথমে ইব্রাহিম আলাইহিস সালামের কাছে গিয়ে তাঁকে '
        'একটি জ্ঞানী পুত্রের সুসংবাদ দিল, তারপর তারা তাদের যাত্রা '
        'লুতের দিকে চালিয়ে গেল, তখন তাঁকে দেখে তাঁর হৃদয় '
        'সংকুচিত হলো একটি সুদর্শন অতিথির প্রতি করুণা না করা '
        'তাঁর সম্প্রদায়ের কাছ থেকে তাদের ভয়ে, তিনি বললেন: "এটি '
        'একটি কঠিন দিন।" আর সত্যিই, গ্রামবাসীরা লুতের কাছে '
        'অতিথি থাকার কথা শোনামাত্র ঘৃণ্য জোরাজুরি নিয়ে তাঁর '
        'দিকে দৌড়ে এলো, তখন লুত প্রতিটি সম্ভাব্য উপায়ে তাদের '
        'বাধা দেওয়ার চেষ্টা করলেন, শেষ পর্যন্ত দুঃখের সাথে বললেন: '
        '"যদি আমার তোমাদের বিরুদ্ধে শক্তি থাকত বা আমি কোনো '
        'শক্তিশালী আশ্রয়ে আশ্রয় নিতে পারতাম।" সেই মুহূর্তে '
        'ফেরেশতারা লুতকে স্বস্তি দিতে তাদের প্রকৃত পরিচয় প্রকাশ '
        'করলেন এবং আক্রমণকারী সম্প্রদায়ের দৃষ্টিশক্তি এক মুহূর্তে '
        'কেড়ে নিলেন যাতে তারা কিছুই দেখতে না পায়, আর লুতকে '
        'নির্দেশ দিলেন রাতের বেলা তাঁর পরিবার নিয়ে বের হতে '
        'এবং তাদের কেউ যেন পিছনে না তাকায়, কেবল তাঁর স্ত্রী '
        'ব্যতীত যাঁর ওপর সেই একই বিপদ আসবে যা তাঁর সম্প্রদায়ের '
        'ওপর এসেছে। সকাল হলে, আল্লাহর চূড়ান্ত নির্দেশ এলো: '
        'আল্লাহ গ্রামের ওপরের অংশকে নিচে করে দিলেন — অর্থাৎ '
        'একে সম্পূর্ণ উল্টে দিলেন — এবং তাদের ওপর কঠোর মাটির '
        'পাথর বর্ষণ করলেন — তাদের প্রত্যেকের জন্য বিশেষভাবে '
        'চিহ্নিত — তখন তা সম্পূর্ণরূপে ধ্বংস করে দিলেন যাতে '
        'এর কোনো চিহ্ন অবশিষ্ট রইল না, এটি ছিল অশ্লীলতার '
        'পরিণতি নিয়ে চিন্তা করা মানুষের জন্য একটি শিক্ষা।',
    source:
        'সূরা হুদ: ৭৭-৮৩, সূরা আল-হিজর: ৫৭-৭৭ ও সূরা '
        'আল-আরাফ: ৮০-৮৪',
  ),
  'prophet-16': StoryTranslation(
    title: 'শুআইব আলাইহিস সালাম ও মাদইয়ানবাসী',
    body:
        'শুআইব আলাইহিস সালামকে মাদইয়ানবাসীদের কাছে পাঠানো '
        'হয়েছিল, যারা তাদের ব্যবসায় ওজন ও মাপে প্রতারণা করত, '
        'প্রতিটি লেনদেনে ছোট একটি কৌশল দিয়ে মানুষের অধিকার '
        'কমিয়ে দিত এই ভেবে যে কেউ তা লক্ষ্য করবে না, সাথে '
        'যাত্রীদের পথ কেটে দিত এবং পৃথিবীতে বিপর্যয় সৃষ্টি করত। '
        'শুআইব তাদের প্রথমে তাওহীদের দিকে ডাকলেন, তারপর '
        'ব্যবসায় সততার দিকে: "হে আমার সম্প্রদায়, ন্যায্যতার সাথে '
        'মাপ ও ওজন পূর্ণ করো, মানুষকে তাদের জিনিসপত্র কমিয়ে '
        'দিয়ো না, পৃথিবীতে বিপর্যয় সৃষ্টি করে বেড়িয়ো না।" তখন '
        'তারা অদ্ভুত বিদ্রূপ ও উপহাসের সাথে উত্তর দিল: "তোমার '
        'সালাত কি তোমাকে নির্দেশ দেয় যে আমরা আমাদের '
        'পূর্বপুরুষদের পূজিত জিনিস ছেড়ে দিই বা আমাদের সম্পদে '
        'আমরা যা ইচ্ছা করা থেকে বিরত থাকি? তুমি তো নিশ্চয়ই '
        'ধৈর্যশীল, সঠিক বুদ্ধিমান," তারা এটি প্রশংসা হিসেবে নয় '
        'বরং বিদ্রূপ করে বলছিল। তারা শুআইব ও তাঁর সাথে ঈমান '
        'আনাদের পাথর ছুঁড়ে মারা বা গ্রাম থেকে বহিষ্কারের হুমকি '
        'দিল যদি তারা তাদের ধর্মে ফিরে না আসে, তখন শুআইব '
        'দৃঢ়তার সাথে তাদের উত্তর দিলেন: "যদিও আমরা অপছন্দ করি '
        'তবুও কি?" আমরা যদি তোমাদের ধর্মে ফিরে যাই আল্লাহ '
        'আমাদের তা থেকে মুক্তি দেওয়ার পরে তবে আমরা নিশ্চয়ই '
        'আল্লাহর ওপর মিথ্যা রচনা করব। তিনি তাদের সামনে আসা '
        'সম্প্রদায়গুলোর পরিণতি স্মরণ করিয়ে দিলেন যারা তাদের '
        'অহংকারের কারণে ধ্বংস হয়েছিল — নূহ, হুদ, সালিহ ও '
        'লুতের সম্প্রদায় — এবং তারা স্থান বা কালে তাদের থেকে '
        'দূরে নয়, আর তিনি তাদের সময় শেষ হওয়ার আগে ক্ষমা '
        'প্রার্থনা ও তওবার দিকে আহ্বান জানালেন। কিন্তু তাদের '
        'অহংকার তাদের শুনতে বাধা দিল, তখন কুরআনে উল্লেখিত '
        'দুটি রূপে তাদের কাছে আজাব এলো: একটি প্রচণ্ড ভূমিকম্প '
        'যা তাদের নিচের মাটি কাঁপিয়ে দিল, আর একটি আজাবের '
        'ছায়া যা একটি ভয়ানক অন্ধকার দিনের আজাব থেকে তাদের '
        'ঢেকে ফেলল, তখন তারা তাদের ঘরে মৃতদেহ হয়ে পড়ে '
        'রইল, নিশ্চল, যেন তারা কখনো সেখানে বাস করেনি। শুআইব '
        'তাদের ধ্বংসের পর তাদের জনশূন্য বাড়িঘরের সাথে কথা '
        'বলতে দাঁড়ালেন এমন একজন নবীর দুঃখ নিয়ে যিনি তাঁর '
        'সম্প্রদায় হারিয়েছেন তারা তাঁর সাথে যা করেছিল তা সত্ত্বেও: '
        '"হে আমার সম্প্রদায়, আমি তোমাদের কাছে আমার রবের '
        'বার্তা পৌঁছে দিয়েছি এবং তোমাদের উপদেশ দিয়েছি, তাহলে '
        'আমি কীভাবে কাফির সম্প্রদায়ের জন্য দুঃখ করব?"',
    source:
        'সূরা হুদ: ৮৪-৯৫, সূরা আল-আরাফ: ৮৫-৯৩ ও সূরা '
        'আশ-শুআরা: ১৭৬-১৯১',
  ),
  'prophet-17': StoryTranslation(
    title: 'তালুত, জালুত ও তরুণ দাউদ',
    body:
        'মূসা আলাইহিস সালামের নবুওয়তের অনেক পরে, বনী '
        'ইসরাইলের নেতারা তাদের নবীর কাছে অনুরোধ জানাল '
        'তাদের জন্য একজন রাজা প্রেরণ করতে যার পতাকার নিচে '
        'তারা তাদের শত্রুদের বিরুদ্ধে যুদ্ধ করবে যারা তাদের '
        'বাড়িঘর থেকে বহিষ্কার করেছিল এবং তাদের সন্তানদের বন্দী '
        'করেছিল, তখন তাদের নবী তাদের সতর্ক করলেন: "যদি '
        'তোমাদের ওপর যুদ্ধ ফরজ করা হয় তবে কি তোমরা যুদ্ধ '
        'নাও করতে পারো?" কিন্তু তারা নিজেদের প্রতি আস্থা রেখে '
        'জোর দিল। তখন আল্লাহ তাদের জন্য তালুতকে রাজা নির্বাচন '
        'করলেন, তখন তাদের অধিকাংশ এতে আপত্তি জানাল কারণ '
        'তিনি রাজবংশ থেকে নন এবং তাদের মধ্যে সবচেয়ে ধনীও '
        'নন: "তাকে কীভাবে আমাদের ওপর রাজত্ব দেওয়া হবে যখন '
        'আমরা রাজত্বের বেশি অধিকারী আর তাকে সম্পদের প্রাচুর্যও '
        'দেওয়া হয়নি?" তখন তাদের নবী তাদের জানালেন যে আল্লাহ '
        'তাকে তাদের ওপর নির্বাচন করেছেন এবং তাকে জ্ঞান ও '
        'দৈহিক শক্তিতে অতিরিক্ত বৃদ্ধি দিয়েছেন, আর তাদের তার '
        'রাজত্বের সত্যতার একটি নিদর্শন দিলেন: বনী ইসরাইলের '
        'কাছে থাকা সিন্দুকের প্রত্যাবর্তন, যাতে তাদের রবের পক্ষ '
        'থেকে প্রশান্তি এবং মূসা ও হারুনের পরিবারের রেখে যাওয়া '
        'কিছু নিদর্শন ছিল, ফেরেশতারা যা বহন করছিল। তালুত তার '
        'বাহিনী নিয়ে বের হলেন, তখন তিনি তাদের জন্য একটি '
        'নদীর কাছে একটি চূড়ান্ত পরীক্ষা রাখলেন: "যে এর থেকে '
        'পান করবে সে আমার নয়, আর যে এর স্বাদ নেবে না সে '
        'আমার, কেবল যে তার হাত দিয়ে এক আঁজলা পানি নেবে '
        'সে ব্যতীত।" তখন সতর্কতা সত্ত্বেও বাহিনীর অধিকাংশ '
        'সীমাহীনভাবে পান করল, আর তাদের মধ্যে খুব কম মানুষই '
        'পরীক্ষায় উত্তীর্ণ হলো। যখন এই কম সংখ্যক লোক জালুতের '
        'বিশাল বাহিনীর মুখোমুখি হলো, তখন তাদের কেউ কেউ '
        'ভয়ে পিছু হটল, তখন তাদের মধ্যে দৃঢ়প্রতিজ্ঞ মুমিনরা একটি '
        'চিরন্তন বাক্য বলল: "কতই না ছোট দল আল্লাহর অনুমতিতে '
        'বড় দলের ওপর বিজয়ী হয়েছে, আর আল্লাহ ধৈর্যশীলদের '
        'সাথে আছেন।" তালুতের সারিতে একজন ছোট তরুণ ছিল '
        'যাকে তখনো যুদ্ধে পরিচিত ছিল না, তার নাম ছিল দাউদ, '
        'তখন সে বিস্ময়কর আত্মবিশ্বাসের সাথে সমগ্র বাহিনীকে '
        'ভীত করা শক্তিশালী ও ভয়ংকর জালুতকে চ্যালেঞ্জ করতে '
        'এগিয়ে গেল, সে তার গুলতি দিয়ে তাকে এমন একটি মারাত্মক '
        'আঘাত করল যা তাকে ভূপাতিত করল, তখন তার বাহিনী '
        'একটি ভয়াবহ পরাজয়ে পরাজিত হলো। আল্লাহ এরপর '
        'দাউদকে রাজত্ব ও হিকমত দিলেন, তাঁকে যা তিনি চেয়েছিলেন '
        'তা শেখালেন, এমনকি তিনি বনী ইসরাইলের সবচেয়ে বড় '
        'নবীদের একজন হলেন যদিও তিনি সারির পেছনে একজন '
        'অপরিচিত তরুণ ছিলেন।',
    source: 'সূরা আল-বাকারা: ২৪৬-২৫১',
  ),
  'prophet-18': StoryTranslation(
    title: 'জুলকারনাইন ও ইয়াজুজ-মাজুজের প্রাচীর',
    body:
        'জুলকারনাইন ছিলেন একজন সৎ ও ন্যায়পরায়ণ রাজা যাকে '
        'আল্লাহ পৃথিবীতে ক্ষমতা দিয়েছিলেন এবং তাকে প্রতিটি '
        'জিনিসের একটি উপায় দিয়েছিলেন, অর্থাৎ তার উদ্দেশ্যে '
        'পৌঁছানোর একটি মাধ্যম। তিনি বিশাল যাত্রায় বের হলেন, '
        'প্রথমে তিনি সূর্যাস্তের স্থানে পৌঁছালেন এবং তা দেখলেন — '
        'তার দৃষ্টিতে — একটি কালো কর্দমাক্ত ঝর্ণায় অস্ত যাচ্ছে, '
        'আর সেখানে তিনি একটি সম্প্রদায় পেলেন, তখন আল্লাহ '
        'তাকে তাদের বিষয়ে একটি পছন্দ দিলেন: তাদের মধ্যে '
        'জালিমদের শাস্তি দেবে নাকি তাদের প্রতি ইহসান করবে, '
        'তখন তিনি ন্যায়বিচার বেছে নিলেন: "যে অন্যায় করবে '
        'আমরা তাকে শাস্তি দেব, আর যে ঈমান আনবে ও সৎকর্ম '
        'করবে তার জন্য উত্তম প্রতিদান রয়েছে।" তারপর তিনি অন্য '
        'একটি দিকে গেলেন এমনকি সূর্যোদয়ের স্থানে পৌঁছালেন, '
        'তিনি এমন একটি সম্প্রদায় পেলেন যাদের জন্য আল্লাহ তার '
        'থেকে কোনো আচ্ছাদন রাখেননি, তারা যথাযথ সুরক্ষা ছাড়া '
        'সরাসরি এর তাপে উন্মুক্ত জীবনযাপন করছিল, তখন তিনি '
        'তাদের সাথেও একই ন্যায়বিচার করলেন। তারপর তিনি '
        'তৃতীয় একটি পথে গেলেন এমনকি দুটি বিশাল পাহাড়ের '
        'মধ্যবর্তী একটি স্থানে পৌঁছালেন, তিনি সেখানে এমন একটি '
        'সম্প্রদায় পেলেন যারা সহজে কথা বুঝত না, আর তারা ইয়াজুজ '
        'ও মাজুজের ক্ষতিতে বিরক্ত হয়ে পড়েছিল, দুটি বিপর্যয় '
        'সৃষ্টিকারী গোত্র যারা তাদের ওপর ক্রমাগত আক্রমণ করত '
        'এবং তাদের ফসল ও বাড়িঘর ধ্বংস করত। তারা জুলকারনাইনের '
        'কাছে অনুরোধ করল তাদের জন্য একটি প্রাচীর তৈরি করতে '
        'যা তাদের থেকে তাদের রক্ষা করবে বিনিময়ে তারা তার '
        'জন্য সম্পদ জড়ো করে দেবে, তখন তিনি একজন সৎ রাজার '
        'আত্মমর্যাদার সাথে বস্তুগত বিনিময় প্রত্যাখ্যান করলেন: "আমার '
        'রব আমাকে যা ক্ষমতা দিয়েছেন তা উত্তম, তোমরা আমাকে '
        'শক্তি দিয়ে সাহায্য করো, আমি তোমাদের ও তাদের মধ্যে '
        'একটি বাধা তৈরি করব।" তিনি তাদের কাছে লোহার টুকরো '
        'চাইলেন এবং দুটি পাহাড়ের মধ্যে তা দিয়ে নির্মাণ করলেন, '
        'শেষ পর্যন্ত যখন তিনি দুটি প্রান্ত সমান করলেন, তখন তিনি '
        'তাদের নির্দেশ দিলেন হাপর দিয়ে তাতে ফুঁ দিতে এমনকি '
        'লোহাটি আগুনের মতো জ্বলজ্বলে হয়ে উঠল, তারপর তিনি '
        'তার ওপর গলিত তামা ঢাললেন যা তার সাথে মিশে গেল '
        'এবং একটি দৃঢ়, অভেদ্য প্রাচীর হিসেবে শক্ত হলো যার '
        'উচ্চতা ও মসৃণতার কারণে তারা তাতে চড়তে পারত না, '
        'আর তার বিশাল দৃঢ়তার কারণে তারা তা ছিদ্র করতে পারত '
        'না। জুলকারনাইন এই মহান প্রকৌশল কৃতিত্বকে নিজের ও '
        'তার বুদ্ধিমত্তার সাথে সম্পর্কিত করলেন না, বরং একজন '
        'প্রকৃত মুমিনের বিনয়ের সাথে বললেন: "এটি আমার রবের '
        'পক্ষ থেকে একটি রহমত, যখন আমার রবের প্রতিশ্রুতি '
        'আসবে তখন তিনি একে সমতল করে দেবেন, আর আমার '
        'রবের প্রতিশ্রুতি সত্য," এই ঘোষণা করে যে এই প্রাচীর — '
        'তার দৃঢ়তা সত্ত্বেও — চিরকাল থাকবে না, বরং কিয়ামত '
        'নিকটবর্তী হলে তার নির্ধারিত সময়ে ভেঙে পড়বে।',
    source: 'সূরা আল-কাহফ: ৮৩-৯৮',
  ),
  'prophet-19': StoryTranslation(
    title: 'হাবিব আন-নাজ্জার, একটি গ্রামের মুমিন',
    body:
        'আল্লাহ একটি গ্রামে দুজন রাসূল পাঠালেন, তখন গ্রামবাসীরা '
        'তাদের অস্বীকার করল, তখন আল্লাহ তাদের একজন তৃতীয় '
        'রাসূল দিয়ে সমর্থন করলেন, তখন তারা গ্রামবাসীদের বলল: '
        '"নিশ্চয়ই আমরা তোমাদের কাছে প্রেরিত," কিন্তু সম্প্রদায় '
        'তুচ্ছতার সাথে উত্তর দিল: "তোমরা তো আমাদের মতোই '
        'মানুষ, আর দয়াময় কিছুই নাজিল করেননি, তোমরা কেবল '
        'মিথ্যা বলছ।" তারা তাদের অশুভ মনে করল — কুলক্ষণ ধরল '
        '— এবং তাদের দাওয়াত বন্ধ না করলে পাথর ছুঁড়ে মারার '
        'হুমকি দিল, তখন রাসূলরা দৃঢ়তার সাথে উত্তর দিল: "তোমাদের '
        'কুলক্ষণ তোমাদের সাথেই আছে," অর্থাৎ তোমাদের দুর্ভাগ্য '
        'তোমাদের নিজেদের থেকে, আমাদের থেকে নয়। সেই সংকটময় '
        'মুহূর্তে, শহরের দূর প্রান্ত থেকে একজন ব্যক্তি দৌড়ে এলো '
        '— কুরআন তার নাম স্পষ্টভাবে উল্লেখ করেনি, কিন্তু '
        'মুফাসসিররা তাকে হাবিব আন-নাজ্জার বলে ডেকেছেন — '
        'তখন সে তার সম্প্রদায়কে একজন আন্তরিক উপদেষ্টার কণ্ঠে '
        'ডাকল: "হে আমার সম্প্রদায়, রাসূলদের অনুসরণ করো, তাদের '
        'অনুসরণ করো যারা তোমাদের কাছে কোনো প্রতিদান চায় না '
        'আর যারা সঠিক পথে আছে।" তারপর সে তার নিজের ব্যক্তিগত '
        'ঈমান জনসাধারণের সামনে প্রকাশ্যে ঘোষণা করল তার '
        'কথার পরিণতির ভয় না করে: "নিশ্চয়ই আমি তোমাদের রবের '
        'প্রতি ঈমান এনেছি, তাই আমার কথা শোনো!" তার সম্প্রদায় '
        'তাদের বিশ্বাসের প্রতি এই প্রকাশ্য চ্যালেঞ্জ সহ্য করতে '
        'পারল না, তখন তারা তার ওপর ঝাঁপিয়ে পড়ল এবং কেবল '
        'তার ঈমান ঘোষণার কারণে কোনো দয়া ছাড়াই তৎক্ষণাৎ তাকে '
        'হত্যা করল। কিন্তু আল্লাহ তাকে একটি তাৎক্ষণিক ও বিস্ময়কর '
        'সম্মান দিলেন: তাকে বলা হলো "জান্নাতে প্রবেশ করো," '
        'তখন সে তার মৃত্যুর সেই একই মুহূর্তে শহীদ হয়ে তাতে '
        'প্রবেশ করল। আর এই মহান নিয়ামতেও, হাবিব তাকে হত্যাকারী '
        'তার সম্প্রদায়কে ভুলে যায়নি, বরং তার মৃত্যুর পরও তাদের '
        'জন্য মঙ্গল কামনা করল: "হায়, যদি আমার সম্প্রদায় জানত '
        'কীভাবে আমার রব আমাকে ক্ষমা করেছেন এবং আমাকে '
        'সম্মানিতদের অন্তর্ভুক্ত করেছেন।" আর যে গ্রাম রাসূলদের '
        'প্রত্যাখ্যান করেছিল এবং তাদের একমাত্র মুমিনকে হত্যা '
        'করেছিল, আল্লাহ তার ওপর কোনো বাহিনী বা জটিল আজাব '
        'পাঠাননি, বরং কেবল একটি চিৎকারই যথেষ্ট হলো: "আর '
        'আমরা তার পরে তার সম্প্রদায়ের ওপর আকাশ থেকে কোনো '
        'বাহিনী পাঠাইনি, আর পাঠানোরও প্রয়োজন ছিল না, তা তো '
        'ছিল কেবল একটি চিৎকার, তখনই তারা সবাই নিভে গেল," '
        'এটি একটি ইঙ্গিত যে আল্লাহর আজাব যখন নাজিল হওয়ার '
        'সিদ্ধান্ত নেয়, তখন এক মুহূর্তের বেশি কিছুরই প্রয়োজন হয় না।',
    source: 'সূরা ইয়াসিন: ১৩-২৯',
  ),
  'prophet-20': StoryTranslation(
    title: 'সেই বাগানের মালিকরা যারা গরিবদের প্রতি কার্পণ্য করেছিল',
    body:
        'একজন সৎ ব্যক্তির প্রচুর ফলযুক্ত একটি বিশাল বাগান ছিল, '
        'আর তার সৎ অভ্যাস ছিল ফসল কাটার সময় প্রতিবার তার '
        'পরিবারের জন্য বাকিটা জড়ো করার আগে দরিদ্র ও অভাবগ্রস্তদের '
        'জন্য একটি উদার অংশ ছেড়ে দেওয়া। এই ব্যক্তি মারা গেল, '
        'তার পরে তার ছেলেরা বাগানের উত্তরাধিকারী হলো, কিন্তু '
        'তারা — তাদের পিতার বিপরীতে — এবার গরিবদের বঞ্চিত '
        'করার জন্য গোপনে তাদের মধ্যে ষড়যন্ত্র করল, তারা শপথ '
        'করল যে তারা কেউ জাগার আগেই ভোরে বের হবে, যাতে '
        'তারা কোনো গরিব মানুষ টের না পেয়ে তার স্বাভাবিক '
        'অংশ চাইতে না পারে সব ফল নিজেদের জন্য জড়ো করবে, '
        'আর তারা তাদের কেউ "ইনশাআল্লাহ" না বলেই দৃঢ় সংকল্পের '
        'সাথে এতে শপথ করল। আর সেই একই রাতে, যখন তারা '
        'তাদের পরিকল্পনায় নিশ্চিন্তে ঘুমাচ্ছিল, তখন আল্লাহ তার '
        'পক্ষ থেকে বাগানের ওপর একটি আকস্মিক বিপর্যয় পাঠালেন '
        '— একটি ঝড় বা আগুন — যা কয়েক ঘণ্টার মধ্যে তা সম্পূর্ণ '
        'মুছে দিল, তখন তা কালো, পোড়া, বন্ধ্যা মাটির মতো হয়ে '
        'গেল, না কোনো ফল না জীবনের কোনো চিহ্ন। ভাইয়েরা '
        'তাদের সিদ্ধান্ত অনুযায়ী ভোরে উঠল, তারা চাপা কণ্ঠে '
        'ফিসফিস করে বেরিয়ে পড়ল: "যদি ফসল কাটতে চাও তবে '
        'সকালেই তোমাদের ক্ষেতে যাও, আজ কোনো গরিব যেন '
        'তোমাদের কাছে না আসে," আর তারা এই দৃঢ় সংকল্প নিয়ে '
        'বের হলো — গরিবদের প্রতিরোধে সম্পূর্ণ শক্তি নিয়ে দৃঢ়প্রতিজ্ঞ '
        'হয়ে। কিন্তু যখন তারা পৌঁছাল এবং সম্পূর্ণ ধ্বংস দেখল, '
        'তারা একমুহূর্তের জন্য মনে করল তারা পথ ভুল করেছে: '
        '"তারা বলল: নিশ্চয়ই আমরা পথ হারিয়েছি!" তারপর তারা '
        'বেদনাদায়ক সত্যটি বুঝল: "বরং আমরা বঞ্চিত হয়েছি," '
        'অন্যদের বঞ্চিত করার আমাদের দুষ্ট উদ্দেশ্যের কারণে আমাদের '
        'সব ফল থেকে বঞ্চিত করে আমাদের শাস্তি দেওয়া হয়েছে। '
        'তাদের মধ্যে সবচেয়ে ন্যায়পরায়ণ ব্যক্তি তিরস্কার করে বলল: '
        '"আমি কি তোমাদের বলিনি তোমরা কেন তাসবীহ পড়ো না?" '
        'তখন তারা সবাই অনুশোচনার সাথে তওবা করল: "আমাদের '
        'রব পবিত্র, নিশ্চয়ই আমরা জালিম ছিলাম," আর তারা এই '
        'পাপপূর্ণ পরিকল্পনার জন্য একে অপরকে দোষারোপ করতে '
        'শুরু করল, তাদের তওবায় সত্যবাদী হলে তাদের রব তাদের '
        'এর চেয়ে ভালো কিছু দেবেন এই আশায়।',
    source: 'সূরা আল-কালাম: ১৭-৩৩',
  ),
  'prophet-21': StoryTranslation(
    title: 'জাকারিয়া ও ইয়াহইয়া আলাইহিমাস সালাম',
    body:
        'জাকারিয়া আলাইহিস সালাম একজন বৃদ্ধ নবী ছিলেন, আর '
        'তাঁর স্ত্রী বন্ধ্যা ছিলেন যিনি তাঁর সারা জীবনে কখনো সন্তান '
        'জন্ম দেননি, তাই তাঁর কোনো উত্তরাধিকারী ছিল না যিনি তাঁর '
        'নবুওয়ত ও তাঁর পরে তাঁর বার্তা বহন করবেন। তিনি মারইয়ামের '
        'কাছে যাতায়াত করতেন যিনি শৈশব থেকে তাঁর মিহরাবে '
        'ইবাদত করতেন, প্রতিবার তিনি তাঁর কাছে গেলে তিনি অসময়ে '
        'ফলের রিজিক পেতেন, তখন তিনি বিস্মিত হয়ে জিজ্ঞেস '
        'করলেন: "হে মারইয়াম, তুমি এটি কোথা থেকে পেয়েছ?" '
        'তিনি তাঁর রবের প্রতি বিশ্বাসের সাথে উত্তর দিলেন: "এটি '
        'আল্লাহর পক্ষ থেকে, নিশ্চয়ই আল্লাহ যাকে ইচ্ছা বিনা হিসাবে '
        'রিজিক দেন।" এই দৃশ্য জাকারিয়ার হৃদয়ে সবকিছুর ওপর '
        'আল্লাহর ক্ষমতা সম্পর্কে একটি নতুন আশা জাগিয়ে তুলল, '
        'তখন তিনি সেই মুহূর্তে গোপন বিনম্রতার সাথে তাঁর রবের '
        'কাছে দোয়া করলেন, মানুষের সামনে তাঁর কণ্ঠ উঁচু না করে: '
        '"হে আমার রব, নিশ্চয়ই আমার হাড় দুর্বল হয়ে গেছে এবং '
        'মাথা বার্ধক্যের সাদা চুলে ভরে গেছে, আর হে আমার রব, '
        'আমি আপনার কাছে দোয়া করে কখনো ব্যর্থ হইনি, আর '
        'নিশ্চয়ই আমি আমার পরে আমার আত্মীয়দের নিয়ে ভীত, আর '
        'আমার স্ত্রী বন্ধ্যা, তাই আমাকে আপনার পক্ষ থেকে একজন '
        'ওয়ারিস দিন, যিনি আমার উত্তরাধিকারী হবেন এবং ইয়াকুবের '
        'পরিবারের উত্তরাধিকারী হবেন, আর তাকে, হে আমার রব, '
        'সন্তোষজনক করুন।" আল্লাহ তৎক্ষণাৎ তাঁর দোয়া একটি '
        'বিস্ময়কর সুসংবাদ দিয়ে কবুল করলেন: "হে জাকারিয়া, '
        'নিশ্চয়ই আমরা তোমাকে ইয়াহইয়া নামে একটি পুত্রের '
        'সুসংবাদ দিচ্ছি, এর আগে আমরা এই নামে কাউকে সৃষ্টি '
        'করিনি," অর্থাৎ এর আগে তার সম্মান ও বিশেষত্বের জন্য '
        'কাউকে এই নাম দেওয়া হয়নি। জাকারিয়া আল্লাহর ক্ষমতায় '
        'দৃঢ় বিশ্বাস থাকা সত্ত্বেও এই সংবাদে বিস্মিত হলেন: "হে '
        'আমার রব, আমার কীভাবে একটি পুত্র হবে যখন আমার '
        'স্ত্রী বন্ধ্যা এবং আমি নিজেও চরম বার্ধক্যে পৌঁছেছি?" তখন '
        'উত্তর এলো: "এমনই হবে, তোমার রব বলেছেন এটি আমার '
        'জন্য সহজ।" জাকারিয়া একটি নিদর্শন চাইলেন যাতে তাঁর '
        'হৃদয় প্রশান্ত হয়, তখন তাঁর নিদর্শন নির্ধারিত হলো তিনি '
        'পর পর তিন রাত মানুষের সাথে কথা বলা থেকে বিরত থাকবেন '
        'যদিও তাঁর দেহ সম্পূর্ণ সুস্থ ছিল কোনো ত্রুটি বা রোগ '
        'ছাড়াই, তখন তিনি মিহরাব থেকে তাঁর সম্প্রদায়ের সামনে '
        'বের হলেন কেবল হাত দিয়ে ইশারা করে যে তারা সকাল-'
        'সন্ধ্যা তাসবীহ পাঠ করুক, সম্পূর্ণ সুস্থতা সত্ত্বেও কথা বলতে '
        'অক্ষম। ইয়াহইয়া জন্মগ্রহণ করলেন, আর আল্লাহ তাঁকে '
        'শৈশবেই হিকমত দিলেন এবং তাঁকে তাঁর পিতামাতার প্রতি '
        'সদাচরণকারী ও তাদের প্রতি দয়ালু বানালেন, তিনি অহংকারী '
        'অবাধ্য ছিলেন না, তখন তাঁর জন্মের দিন, তাঁর মৃত্যুর দিন '
        'এবং জীবিত অবস্থায় পুনরুত্থানের দিন আল্লাহর শান্তি তাঁর '
        'ওপর ছিল।',
    source: 'সূরা মারইয়াম: ২-১৫ ও সূরা আলে ইমরান: ৩৭-৪১',
  ),
  'prophet-22': StoryTranslation(
    title: 'হুদ আলাইহিস সালাম ও আদ সম্প্রদায়',
    body:
        'আল্লাহ হুদ আলাইহিস সালামকে আদ সম্প্রদায়ের কাছে '
        'পাঠালেন, যারা বিশাল দৈহিক শক্তি ও বিশাল নির্মাণের '
        'অধিকারী ছিল, তারা উঁচু প্রাসাদ ও দৃঢ় দুর্গ নির্মাণ করত এই '
        'ভেবে যে তা তাদের পৃথিবীতে চিরকাল রাখবে। হুদ তাদের '
        'কেবল তাওহীদের দিকে ডাকলেন এবং তাদের প্রতি আল্লাহর '
        'নিয়ামত স্মরণ করিয়ে দিলেন: "স্মরণ করো যখন তিনি '
        'নূহের সম্প্রদায়ের পরে তোমাদের উত্তরাধিকারী বানিয়েছেন '
        'এবং সৃষ্টিতে তোমাদের শক্তি বৃদ্ধি করেছেন, তাই আল্লাহর '
        'নিয়ামতসমূহ স্মরণ করো যাতে তোমরা সফল হও।" কিন্তু '
        'তারা অহংকার করল এবং তাঁর দাওয়াতকে স্পষ্ট তুচ্ছতার '
        'সাথে উপহাস করল: "তুমি কি আমাদের কাছে এসেছ '
        'আমাদের দেবতাদের থেকে আমাদের ফিরিয়ে দিতে? তাহলে '
        'আমাদের প্রতিশ্রুত জিনিসটি নিয়ে এসো যদি তুমি সত্যবাদীদের '
        'অন্তর্ভুক্ত হও!" আর হুদ কোনো প্রকৃত প্রয়োজন ছাড়া কেবল '
        'গর্ব প্রদর্শনের জন্য টাওয়ার ও প্রাসাদ নির্মাণের জন্য '
        'তাদের নিন্দা করলেন: "তোমরা কি প্রতিটি উঁচু জায়গায় '
        'খেলার জন্য একটি নিদর্শন তৈরি করছ, আর তোমরা কি '
        'এমন কারখানা বানাচ্ছ যেন তোমরা চিরকাল থাকবে?" আর '
        'তিনি তাদের স্পষ্টভাবে সতর্ক করলেন যে যদি তারা তাদের '
        'অহংকার চালিয়ে যায় তাহলে একটি মহান আজাব তাদের '
        'জন্য অপেক্ষা করছে, তখন তারা তাদের গর্বিত দৈহিক শক্তির '
        'অহংকার নিয়ে উত্তর দিল: "কে আমাদের চেয়ে বেশি '
        'শক্তিশালী?" ভুলে গিয়ে যে তাদের সৃষ্টিকারী আল্লাহ তাদের '
        'চেয়ে অতুলনীয়ভাবে বেশি শক্তিশালী। যখন তারা তাদের '
        'জিদে অব্যাহত থাকল, একদিন তারা তাদের উপত্যকার দিকে '
        'একটি ঘন মেঘ দেখল এবং খুশি হলো এই ভেবে যে এটি '
        'দীর্ঘ খরার পর তারা যে বৃষ্টির অপেক্ষা করছিল তাই, তখন '
        'হুদ তাদের সতর্ক করে বললেন: "না, এটিই তো তা যা তোমরা '
        'তাড়াতাড়ি চেয়েছিলে, এমন একটি বাতাস যাতে যন্ত্রণাদায়ক '
        'আজাব রয়েছে, যা তার রবের নির্দেশে সবকিছু ধ্বংস করে '
        'দেবে।" তখন আল্লাহ তাদের ওপর অত্যন্ত ঠান্ডা ও প্রবল '
        'বাতাস পাঠালেন যা তিনি টানা সাত রাত আট দিন তাদের '
        'ওপর চাপিয়ে দিলেন, শক্তিশালী মানুষদের তাদের স্থান থেকে '
        'উপড়ে ফেলল এবং তাদের এমনভাবে ফেলে দিল যেন তারা '
        'ভেতর থেকে পচে যাওয়া খেজুর গাছের ফাঁপা কাণ্ড, শেষ '
        'পর্যন্ত আদ সম্প্রদায় সম্পূর্ণভাবে তাদের শিকড় পর্যন্ত ধ্বংস '
        'হয়ে গেল, আর হুদ ও তাঁর সাথে ঈমান আনাদের ব্যতীত '
        'তাদের কেউ অবশিষ্ট রইল না, তখন তাদের শক্তি ও তাদের '
        'প্রাসাদ আল্লাহর নির্দেশের সামনে কোনো কাজেই এলো না।',
    source:
        'সূরা আল-আরাফ: ৬৫-৭২, সূরা হুদ: ৫০-৬০ ও সূরা '
        'আল-হাক্কাহ: ৬-৮',
  ),

  // ===== প্রাণীদের কাহিনি =====
  'animal-1': StoryTranslation(
    title: 'পিঁপড়া তার সম্প্রদায়কে সতর্ক করে',
    body:
        'সুলাইমান আলাইহিস সালাম মানুষ, জিন ও পাখিদের সমন্বয়ে '
        'গঠিত তাঁর সৈন্যবাহিনীর একটি বিশাল মিছিলে যাত্রা করছিলেন '
        'যারা সুশৃঙ্খল সারিতে চলছিল, তাদের পথ একটি পিঁপড়া-পূর্ণ '
        'উপত্যকা দিয়ে গেল, তখন একটি পিঁপড়া দূর থেকে এই বিশাল '
        'বাহিনীকে তার অসংখ্য পায়ে এগিয়ে আসতে দেখল, সে তার '
        'ছোট সম্প্রদায়ের প্রতি বিপদ বুঝল যারা হয়তো বুঝতে পারবে '
        'না কত বড় কিছু তাদের কাছে আসছে, তখন সে তাদের মধ্যে '
        'উচ্চস্বরে চিৎকার করল: "হে পিঁপড়ারা, তোমাদের গর্তে প্রবেশ '
        'করো, সুলাইমান ও তার সৈন্যবাহিনী না জেনে তোমাদের '
        'পিষে না ফেলুক।" তার কথায় সুলাইমান ও তার সৈন্যবাহিনী '
        'সম্পর্কে সুন্দর ধারণা লক্ষ্য করুন, সে বলেনি যে তারা ইচ্ছাকৃতভাবে '
        'ও অনিষ্টের সাথে আমাদের পিষে ফেলবে, বরং বলেছে "না '
        'জেনে," এই ঘটনা ঘটলে আগেভাগেই তাদের ক্ষমা করে দিয়ে। '
        'আর আল্লাহ সুলাইমানকে প্রাণী ও পাখির ভাষা বোঝার মুজিজা '
        'দিয়েছিলেন, তিনি তার কথা স্পষ্টভাবে শুনলেন যদিও তার '
        'শরীর ছোট এবং তার কণ্ঠস্বর দুর্বল যা অন্য কেউ প্রায় শুনতেই '
        'পেত না। তখন সুলাইমান এই পিঁপড়ার বুদ্ধিমত্তা এবং তার '
        'সম্প্রদায়ের জন্য তার সতর্কতায় হাসলেন, তিনি তাঁর বিশাল '
        'রাজত্বের পাশে একটি অতি ক্ষুদ্র প্রাণীর কথা শুনতে অহংকার '
        'করলেন না, বরং সাথে সাথে তাঁর রবের দিকে দোয়া ও কৃতজ্ঞতার '
        'সাথে ফিরলেন: "হে আমার রব, আমাকে সামর্থ্য দিন যাতে আমি '
        'আপনার সেই নিয়ামতের জন্য কৃতজ্ঞতা প্রকাশ করি যা আপনি '
        'আমার ও আমার পিতামাতার প্রতি করেছেন এবং আমি এমন '
        'সৎকর্ম করি যা আপনি পছন্দ করেন, আর আপনার রহমতের '
        'মাধ্যমে আমাকে আপনার সৎ বান্দাদের অন্তর্ভুক্ত করুন।" '
        'বাহ্যত ক্ষুদ্র এই ঘটনায় বিনয় সম্পর্কে বড় শিক্ষা রয়েছে, '
        'আর একজন বান্দার প্রতি আল্লাহর নিয়ামত — যতই বড় হোক '
        'না কেন — তাকে অহংকার ও দম্ভের দিকে নয় বরং আরও '
        'কৃতজ্ঞতার দিকে পরিচালিত করা উচিত।',
    source: 'সূরা আন-নামল: ১৮-১৯',
  ),
  'animal-2': StoryTranslation(
    title: 'সালিহ নবীর উষ্ট্রী',
    body:
        'সামুদ সম্প্রদায় ছিল পাহাড়ে ঘর খোদাইকারী একটি শক্তিশালী '
        'সম্প্রদায়, আল্লাহ তাদের কাছে সালিহ আলাইহিস সালামকে '
        'পাঠালেন, তিনি তাদের তাওহীদের এবং মূর্তিপূজা ত্যাগ করার '
        'দাওয়াত দিচ্ছিলেন, তারা তাঁর কাছে একটি অলৌকিক নিদর্শন '
        'চাইল তাঁর সত্যতা প্রমাণের জন্য, আল্লাহ তাদের জন্য একটি '
        'কঠিন পাথর থেকে একটি বিশাল দেহের উষ্ট্রী বের করলেন, তাদের '
        'সবার চোখের সামনে একটি স্পষ্ট নিদর্শন। সালিহ তাদের দুটি '
        'শর্ত দিলেন: তার সাথে কোনো খারাপ ব্যবহার না করা এবং '
        'সপ্তাহে একদিন তাকে একা কূপের পানি পান করতে দেওয়া, '
        'অন্য দিন মানুষ পান করবে, তিনি তাদের কঠোরভাবে সতর্ক '
        'করলেন যে তারা যদি তাকে হত্যা করে তাহলে তাদের ওপর '
        'তাৎক্ষণিক যন্ত্রণাদায়ক শাস্তি আসবে। মানুষ কিছুকাল এই '
        'উষ্ট্রীর সাথে বসবাস করল, কিন্তু তাদের কেউ কেউ তার প্রতি '
        'বিরক্ত হতে লাগল, তখন তাদের প্রবৃত্তি এবং সম্প্রদায়ের কিছু '
        'হতভাগ্য তাদের তার থেকে মুক্তি পেতে প্ররোচিত করল, তারা '
        'একত্রিত হয়ে তাকে হত্যা করল — অর্থাৎ তাকে বর্বরভাবে '
        'হত্যা করল — তাদের নবীর নির্দেশের প্রতি একটি স্পষ্ট '
        'চ্যালেঞ্জ হিসেবে। সালিহ যখন জানলেন তারা কী করেছে, তিনি '
        'তাদের নিকটবর্তী শাস্তি সম্পর্কে সতর্ক করলেন: "তোমাদের '
        'ঘরে তিন দিন উপভোগ করো, এটি একটি প্রতিশ্রুতি যা মিথ্যা '
        'নয়।" তিন দিন কেটে গেল মানুষের হৃদয় ভয় ও উপহাসের মধ্যে, '
        'চতুর্থ দিন এলে তাদের কাছে আকাশ থেকে একটি বিশাল '
        'চিৎকার এলো যা তাদের নিচের মাটিকে কাঁপিয়ে দিল, তারা '
        'তাদের ঘরে মৃতদেহ হয়ে পড়ে রইল, সবাই এক মুহূর্তে ধ্বংস '
        'হলো, বড় ছোট সবাই, কারণ তারা তাদের নবীর সাথে করা '
        'প্রতিশ্রুতি একটি সহজ বিষয়ে পালন করেনি: সপ্তাহে একদিন '
        'উষ্ট্রীকে পানি পান করতে দেওয়া।',
    source:
        'সূরা আল-আরাফ: ৭৩-৭৯, সূরা আশ-শামস: ১১-১৫ ও '
        'সূরা হুদ: ৬১-৬৮',
  ),
  'animal-3': StoryTranslation(
    title: 'গুহাবাসীদের কুকুর',
    body:
        'একদল মুমিন যুবক একটি গ্রামে ছিল যার অধিবাসীরা এমন '
        'একজন অত্যাচারী রাজার শাসনে মূর্তিপূজা করত যে মানুষকে '
        'তার পূজা করতে বাধ্য করত, তখন এই যুবকরা গোপনে '
        'আল্লাহর প্রতি ঈমান আনল এবং নিজেদের জন্য ফিতনা ও '
        'হত্যার ভয় করল, তারা তাদের দ্বীন নিয়ে পাহাড়ে একটি দূরের '
        'গুহায় পালিয়ে যাওয়ার সিদ্ধান্ত নিল যা কেউ জানত না, আশা '
        'করে যে আল্লাহ তাদের বিষয়ে সহজতা দেবেন। তারা পালিয়ে '
        'যাওয়ার সময়, তাদের কুকুর — যাকে তারা পালত — তাদের '
        'অনুসরণ করল এবং তাদের ছাড়ল না যদিও সে পরিস্থিতির বিপদ '
        'তাদের মতো বুঝত না, সে তার দুই সামনের পা গুহার মুখে '
        'ছড়িয়ে দিল যেন সে তাদের রক্ষা করছে এবং তাদের দরজায় '
        'একজন বিশ্বস্ত রক্ষী হিসেবে দাঁড়িয়ে আছে। আল্লাহ তাদের '
        'দীর্ঘ বছর ধরে গভীর ঘুমে ফেললেন, আল্লাহ এই সময় তাদের '
        'রক্ষা করলেন মাঝে মাঝে তাদের শরীর ডানে-বামে ঘুরিয়ে যাতে '
        'মাটির সংস্পর্শে তাদের শরীর ক্ষয় না হয়, তিনি কুকুরটিকেও '
        'একই অবস্থায় দরজায় তাদের সাথে রক্ষা করলেন। তাদের '
        'ঘুমের ওপর তিনশত নয় চান্দ্র বছর কেটে গেল, সময় অতিবাহিত '
        'হওয়া তারা টের পেল না, তারপর আল্লাহ তাদের ঘুম থেকে '
        'জাগালেন, তখন তাদের কেউ কেউ মনে করল তারা এক দিন বা '
        'তার কম সময় ঘুমিয়েছে, শেষ পর্যন্ত তারা তাদের একজনকে '
        'তাদের পুরনো টাকা দিয়ে খাবার কিনতে পাঠাল, তখন শহরবাসী '
        'জানল তাদের মুদ্রা অনেক পুরনো এবং দীর্ঘদিন ধরে ব্যবহৃত '
        'হচ্ছে না, তখন তারা এই দীর্ঘ শতাব্দীর পর তাদের পুনরুত্থানের '
        'মুজিজা জানল। এই কাহিনিতে লক্ষণীয় বিষয় হলো, কুকুরটিকে '
        'কুরআনে সম্মানের সাথে উল্লেখ করা হয়েছে এবং তাদের সাথে '
        'তার উপস্থিতিকে খারাপ মনে করা হয়নি, বরং এটি বন্ধুত্বের '
        'বিশ্বস্ততা এবং সৎসঙ্গের প্রতীক হয়ে উঠেছে, এমনকি বলা হয় '
        'যে এটি সেই কয়েকটি প্রাণীর মধ্যে একটি যাদের সম্মানের '
        'সাথে পবিত্র কুরআনে উল্লেখ করা হয়েছে।',
    source: 'সূরা আল-কাহফ: ৯-২৬',
  ),
  'animal-4': StoryTranslation(
    title: 'কুকুরকে পানি পান করানো ব্যক্তি',
    body:
        'নবী ﷺ তাঁর সাহাবিদের পূর্ববর্তী উম্মতের একজন ব্যক্তির '
        'কাহিনি শোনালেন যিনি একটি দীর্ঘ পথে হাঁটছিলেন, তখন '
        'তীব্র পিপাসা তাঁকে গ্রাস করল এমনকি এর তীব্রতায় তিনি '
        'প্রায় মারা যাচ্ছিলেন, তিনি তাঁর পথে একটি কূপ পেলেন, তিনি '
        'তাতে নেমে তৃপ্ত না হওয়া পর্যন্ত পানি পান করলেন, তিনি '
        'যখন সেখান থেকে বের হলেন তখন তিনি একটি কুকুর দেখলেন '
        'যে পিপাসার তীব্রতায় জিহ্বা বের করে হাঁপাচ্ছিল, এমনকি সে '
        'পিপাসার তীব্রতায় ভেজা মাটি খাচ্ছিল, তখন লোকটি মনে মনে '
        'বলল: "এই কুকুরটির আমার মতোই পিপাসা লেগেছে।" তাঁর '
        'হৃদয় সেই অসহায় প্রাণীর প্রতি নরম হলো যদিও তিনি তাকে '
        'চিনতেন না এবং তার সাথে তাঁর কোনো সম্পর্ক ছিল না, তিনি '
        'সিদ্ধান্ত নিলেন যে তিনি সাহায্য করতে সক্ষম থাকা অবস্থায় '
        'কোনো সৃষ্টিকে কষ্ট পেতে দেখে তার সামনে ছেড়ে দেবেন না। '
        'লোকটি আবার কূপে নামলেন, আর এতে তাঁর অতিরিক্ত পরিশ্রম '
        'ও সময় লাগল, তিনি তাঁর জুতা পানিতে ভরলেন, তারপর কূপ '
        'বেয়ে ওপরে উঠতে সক্ষম হওয়ার জন্য তা মুখে ধরলেন, তিনি '
        'কষ্ট করে উঠলেন যতক্ষণ না কুকুরের কাছে পৌঁছালেন এবং '
        'তাকে তৃপ্ত না হওয়া পর্যন্ত পানি পান করালেন। আল্লাহ তাঁকে '
        'এই দয়াময় কাজের জন্য কৃতজ্ঞতা জানালেন, যদিও এটি কোনো '
        'মানুষের প্রতি ছিল না বরং এমন একটি প্রাণীর প্রতি ছিল যার '
        'কাছ থেকে কোনো প্রতিদানের প্রত্যাশা করা যায় না, আল্লাহ '
        'এই কাজের কারণে তাঁর গুনাহ মাফ করে দিলেন। যখন সাহাবিরা '
        'বিস্ময়ে নবী ﷺ-কে জিজ্ঞেস করলেন: "হে আল্লাহর রাসূল, '
        'প্রাণীদের ক্ষেত্রেও কি আমাদের জন্য সওয়াব আছে?" তিনি '
        'তাদের এমন একটি মহান নীতি দিয়ে উত্তর দিলেন যা মানুষের '
        'প্রদর্শিত প্রতিটি দয়াকে অন্তর্ভুক্ত করে: "প্রতিটি জীবন্ত '
        'কলিজাধারী প্রাণীর মধ্যে সওয়াব রয়েছে," অর্থাৎ প্রতিটি জীবন্ত '
        'সৃষ্টির প্রতি সদাচরণকারীর জন্য সওয়াব রয়েছে, মানুষ হোক '
        'বা প্রাণী।',
    source: 'সহীহ বুখারী ও মুসলিম',
  ),
  'animal-5': StoryTranslation(
    title: 'সেই নারী যে একটি বিড়ালকে নির্যাতন করেছিল',
    body:
        'কুকুরের প্রতি দয়াশীল ব্যক্তির কাহিনির বিপরীতে, নবী ﷺ '
        'প্রাণীদের প্রতি কঠোর হৃদয় থেকে সতর্ক করেছেন, তিনি '
        'পূর্ববর্তী উম্মতের একজন নারীর কাহিনি বললেন যে একটি '
        'বিড়ালের কারণে জাহান্নামে প্রবেশ করেছিল, সরাসরি তাকে '
        'হত্যা করার জন্য নয়, বরং তাকে বেঁধে খাবার ও পানি ছাড়া আটকে '
        'রাখার জন্য যতক্ষণ না সে ক্ষুধা ও পিপাসায় মারা যায়, সে '
        'এতেই থামেনি, এমনকি তাকে মাটির পোকামাকড় খেতে বাধা '
        'দিয়েছিল যাতে সে তার ক্ষুধা মেটাতে পারে, তখন তার অপরাধ '
        'দ্বিগুণ হয়ে গেল: প্রাণীটিকে আটকে রাখা এবং একইসাথে তাকে '
        'বেঁচে থাকার সবচেয়ে সহজ উপায় থেকে বঞ্চিত করা। হাদীসে '
        'তার বিড়ালকে আটকে রাখার কারণ উল্লেখ নেই, তবে মূল শিক্ষা '
        'স্পষ্ট: প্রাণীদের প্রতি দয়া একটি ধর্মীয় কর্তব্য যা পরিত্যাগ '
        'করলে স্পষ্ট শাস্তি রয়েছে, যেমন এর প্রতি সদাচরণে মহান '
        'সওয়াব রয়েছে। এই কাহিনি হাদীসের কিছু বর্ণনায় কুকুরকে '
        'পানি পান করানো ব্যক্তির কাহিনির ঠিক বিপরীতে এসেছে, '
        'যাতে নবী ﷺ তাঁর সাহাবিদের সামনে দুটি বিপরীত মনোভাব '
        'উপস্থাপন করেন: একটি তার কর্তাকে তার দয়ার কারণে '
        'জান্নাতে প্রবেশ করিয়েছে, অন্যটি তার কর্ত্রীকে তার নিষ্ঠুরতার '
        'কারণে জাহান্নামে প্রবেশ করিয়েছে, যদিও উভয়েই এমন একটি '
        'প্রাণীর সাথে আচরণ করেছিল যার কোনো শক্তি বা সামর্থ্য নেই।',
    source: 'সহীহ বুখারী ও মুসলিম',
  ),
  'animal-6': StoryTranslation(
    title: 'কাক আদমের পুত্রকে শেখায়',
    body:
        'আদম আলাইহিস সালামের দুই পুত্র ছিল, কাবিল ও হাবিল, '
        'তাদের প্রত্যেকে তাদের আন্তরিকতা পরীক্ষা করার জন্য '
        'আল্লাহর কাছে একটি কুরবানি পেশ করল, আল্লাহ পরহেজগার '
        'হাবিলের কুরবানি কবুল করলেন এবং কাবিলের কুরবানি কবুল '
        'করলেন না যে তার কাছে থাকা সবচেয়ে খারাপ জিনিস পেশ '
        'করেছিল, তখন কাবিল তার ভাইয়ের প্রতি ঈর্ষা ও রাগে ভরে '
        'গেল, সে তাকে হুমকি দিয়ে বলল: "আমি অবশ্যই তোমাকে '
        'হত্যা করব।" তখন হাবিল রক্তপাত না চাওয়া একজন মুমিনের '
        'প্রজ্ঞার সাথে উত্তর দিলেন: "নিশ্চয়ই আল্লাহ কেবল পরহেজগারদের '
        'কাছ থেকেই কবুল করেন, তুমি যদি আমাকে হত্যা করার জন্য '
        'তোমার হাত আমার দিকে বাড়াও, আমি তোমাকে হত্যা করার '
        'জন্য আমার হাত তোমার দিকে বাড়াব না, নিশ্চয়ই আমি '
        'বিশ্বজগতের রব আল্লাহকে ভয় করি।" কিন্তু ঈর্ষা কাবিলের '
        'হৃদয়কে অন্ধ করে দিল, সে নিজ হাতে তার ভাইকে হত্যা করল, '
        'এভাবে সে মানবজাতির ইতিহাসের প্রথম হত্যাকারী হলো এবং '
        'পৃথিবীতে সংঘটিত প্রথম হত্যাকাণ্ড হলো। অপরাধের পর, কাবিল '
        'তার ভাইয়ের লাশের সামনে হতবিহ্বল হয়ে দাঁড়িয়ে রইল না '
        'জেনে সে কী করবে, কারণ এটিই ছিল প্রথমবার একজন মানুষ '
        'একটি লাশ দেখল, আর সে জানত না কীভাবে তাকে কবর দেবে। '
        'তখন আল্লাহ সরাসরি কাবিলের চোখের সামনে একটি কাক '
        'পাঠালেন যে তার নখর ও ঠোঁট দিয়ে মাটি খুঁড়ছিল, তাকে '
        'শেখানোর জন্য কীভাবে একটি গর্ত খুঁড়ে তার ভাইয়ের লাশ '
        'লুকাবে, আর এই কাকটি ছিল অন্য একটি কাক যাকে তার মতো '
        'আরেকটি কাক হত্যা করেছিল, তখন জীবিত কাকটি তার মৃত '
        'সঙ্গীকে কবর দিতে এলো। কাবিল যখন এই দৃশ্য দেখল, সে '
        'তার অপরাধের জন্য এবং তার ভাইকে কবর দিতেও অক্ষম '
        'হওয়ার জন্য তীব্রভাবে অনুতপ্ত হলো, সে নিজের সামনে তার '
        'ভুল স্বীকার করে বলল: "হায় আমার দুর্ভাগ্য, আমি কি এই '
        'কাকটির মতোও হতে পারলাম না যে আমার ভাইয়ের লাশ '
        'লুকিয়ে ফেলি?" তখন সে অনুতপ্তদের অন্তর্ভুক্ত হলো, কিন্তু '
        'সময় পার হয়ে যাওয়ার পর।',
    source: 'সূরা আল-মায়িদা: ২৭-৩১',
  ),
  'animal-7': StoryTranslation(
    title: 'উজাইরের গাধা যাকে মৃত্যুর পর পুনরুজ্জীবিত করা হয়েছিল',
    body:
        'একজন সৎ ব্যক্তি — বলা হয় তিনি উজাইর আলাইহিস সালাম '
        'ছিলেন — এমন একটি গ্রামের পাশ দিয়ে গেলেন যা সম্পূর্ণভাবে '
        'ধ্বংস হয়ে গিয়েছিল, তার ছাদ তার দেয়ালের ওপর ভেঙে '
        'পড়েছিল, আর তার অধিবাসীরা অনেক আগেই ধ্বংস হয়ে '
        'গিয়েছিল এমনকি তার মধ্যে জীবনের কোনো চিহ্ন অবশিষ্ট '
        'ছিল না, তিনি এই ধ্বংসাবশেষ নিয়ে চিন্তা করতে দাঁড়ালেন '
        'এবং নিজেকে বিস্ময়ে জিজ্ঞেস করলেন: "আল্লাহ কীভাবে এটিকে '
        'তার মৃত্যুর পর পুনরুজ্জীবিত করবেন?" এটি আল্লাহর ক্ষমতা '
        'নিয়ে সন্দেহের প্রশ্ন ছিল না, বরং তার সামনের ধ্বংসের '
        'ভয়াবহতা সম্পর্কে একটি স্বাভাবিক বিস্ময় ছিল। তখন আল্লাহ '
        'তাকে সেখানে পুরো একশ বছর মৃত রাখলেন, তারপর তাকে '
        'পুনরুজ্জীবিত করলেন, এবং তাকে জিজ্ঞেস করলেন: "আপনি '
        'কতক্ষণ ছিলেন?" তিনি প্রকৃতপক্ষে কী ঘটেছিল তা না জেনে '
        'উত্তর দিলেন: "আমি এক দিন বা এক দিনের কিছু অংশ ছিলাম," '
        'তিনি মনে করলেন তার ঘুম দীর্ঘ ছিল না। তাকে বলা হলো: '
        '"বরং আপনি একশ বছর ছিলেন, আপনার খাবার ও পানীয়ের '
        'দিকে তাকান যা মোটেও নষ্ট হয়নি" — অর্থাৎ একটি পূর্ণ '
        'শতাব্দী কেটে যাওয়া সত্ত্বেও পরিবর্তিত হয়নি এবং নষ্ট হয়নি '
        '— "আর আপনার গাধার দিকে তাকান।" আর এখানেই সবচেয়ে '
        'বড় মুজিজা ঘটল: তিনি তার গাধার হাড়গুলো দেখলেন যা দীর্ঘ '
        'সময়ের কারণে ক্ষয়প্রাপ্ত ও ছড়িয়ে ছিটিয়ে ছিল, তিনি নিজের '
        'চোখে দেখলেন কীভাবে আল্লাহ সেগুলোকে তাদের স্থান থেকে '
        'তুলে ধরেন এবং হাড়ের ওপর হাড় সাজান, তারপর সেগুলোকে '
        'মাংস দিয়ে ঢেকে দেন, তারপর তাতে প্রাণ দেন, এমনকি গাধাটি '
        'জীবিত হয়ে তার সামনে দাঁড়িয়ে ডাকতে লাগল যেন কিছুই '
        'ঘটেনি। এসব যখন তার চোখের সামনে সম্পূর্ণ স্পষ্ট হলো, '
        'তার হৃদয়ে সামান্যতম সন্দেহও রইল না, তিনি আল্লাহর পূর্ণ '
        'ক্ষমতা স্বীকার করে বললেন: "আমি জানি নিশ্চয়ই আল্লাহ '
        'সবকিছুর ওপর ক্ষমতাবান।"',
    source: 'সূরা আল-বাকারা: ২৫৯',
  ),
  'animal-8': StoryTranslation(
    title: 'মাটির কীট যা সুলাইমানের মৃত্যু প্রকাশ করেছিল',
    body:
        'আল্লাহ সুলাইমান আলাইহিস সালামের জন্য জিনদের '
        'সৈন্যবাহিনীকে অধীন করে দিলেন যারা তার জন্য এমন কঠিন '
        'কাজ করত যা মানুষের সাধ্যের বাইরে ছিল: তার জন্য বিশাল '
        'প্রাসাদ, মূর্তি এবং বড় জলাধারের মতো বিশাল পাত্র এবং তাদের '
        'বিশালতার কারণে তাদের স্থান থেকে না নড়া বিশাল হাঁড়ি '
        'তৈরি করত, আর জিনরা দাবি করত যে তারা গায়েব জানে, যা '
        'ছিল একটি ভিত্তিহীন দাবি যা দিয়ে তারা মানুষ থেকে নিজেদের '
        'আলাদা করতে চেয়েছিল। সুলাইমান আলাইহিস সালামের '
        'মৃত্যুর সময় এলো যখন তিনি তার অভ্যাস অনুযায়ী তার লাঠিতে '
        'হেলান দিয়ে জিনদের কাজ পর্যবেক্ষণ করছিলেন, তখন আল্লাহ '
        'সেই অবস্থাতেই তার রুহ কবজ করলেন, কিন্তু তার পবিত্র দেহ '
        'তার লাঠিতে হেলান দিয়ে সোজা দাঁড়িয়ে রইল, তখন তার '
        'চারপাশের জিন ও মানুষ তার মৃত্যু তাৎক্ষণিকভাবে বুঝতে '
        'পারল না, তারা মনে করত তিনি এখনও জীবিত আছেন এবং '
        'তার স্বাভাবিক সতর্কতায় তাদের কাজ পর্যবেক্ষণ করছেন, তখন '
        'তারা মাসের পর মাস কঠোর পরিশ্রম চালিয়ে গেল এই ভেবে '
        'যে তিনি ওপর থেকে তাদের দেখছেন। তার মৃত্যুর সত্যতা প্রকাশ '
        'পায়নি যতক্ষণ না মাটির একটি ছোট কীট — অর্থাৎ উইপোকা, '
        'পিঁপড়ার মতো একটি পোকা যা কাঠ খায় — দিনের পর দিন '
        'খুব ধীরে ধীরে তার লাঠি কুরে খেতে শুরু করল, শেষ পর্যন্ত '
        'সে তার ভেতরটা কেউ টের না পেয়েই সম্পূর্ণ খেয়ে ফেলল, '
        'অবশেষে লাঠিটি দেহের ভারে ভেঙে গেল, তখন সুলাইমান '
        'আলাইহিস সালামের দেহ মাটিতে পড়ল; তখনই জিনরা নিশ্চিত '
        'জানল যে তিনি অনেক আগেই মারা গিয়েছিলেন, আর তারা যদি '
        'সত্যিই তাদের দাবি অনুযায়ী গায়েব জানত তাহলে তারা এত '
        'মাস ধরে বৃথা এমন কঠোর পরিশ্রমে লিপ্ত থাকত না তাদের '
        'নির্দেশ দিতে অক্ষম একজন মৃত ব্যক্তির জন্য। এই বাহ্যত '
        'ছোট ঘটনায় — একটি প্রায় অদৃশ্য ছোট পোকার কাজ — '
        'মানুষকে দেখানোর জন্য বড় শিক্ষা রয়েছে যে জিনদের গায়েব '
        'জানার দাবি মিথ্যা, আর আল্লাহই একমাত্র যিনি দৃষ্টির অগোচরে '
        'থাকা বিষয় জানেন, আর জিনরা যদি সত্যিই গায়েব জানত '
        'তাহলে তারা এমন একজন মৃত ব্যক্তির জন্য অপমানজনক '
        'শ্রমে লিপ্ত থাকত না যে তাদের নির্দেশ দিতে পারে না।',
    source: 'সূরা সাবা: ১৪',
  ),

  // ===== তাবিঈন ও সৎ ব্যক্তিদের কাহিনি =====
  'righteous-1': StoryTranslation(
    title: 'উওয়াইস আল-কারনি',
    body:
        'নবী ﷺ তাঁর সাহাবিদের একটি বিখ্যাত হাদীসে জানালেন যে '
        'তাঁর পরে ইয়েমেনের অধিবাসীদের মধ্য থেকে কারন গোত্রের '
        'উওয়াইস ইবনে আমির নামে একজন ব্যক্তি আসবেন, এবং তিনি '
        'তাঁর সাহাবিদের সূক্ষ্ম চিহ্ন দিলেন যাতে তারা তাঁকে চিনতে '
        'পারেন: তাঁর ত্বকের একটি রোগ ছিল, তিনি আল্লাহর কাছে '
        'দোয়া করলেন, আল্লাহ তা সম্পূর্ণ দূর করলেন কেবল একটি '
        'দিরহাম পরিমাণ ছোট জায়গা ব্যতীত যা ইচ্ছাকৃতভাবে তাঁর '
        'ব্যক্তিগত পরিচয়ের চিহ্ন হিসেবে রেখে দেওয়া হয়েছিল, তাঁর '
        'নিষ্ঠা ও আল্লাহর প্রতি আন্তরিকতা এত বড় মাত্রায় পৌঁছেছিল '
        'যে তিনি আল্লাহর কসম খেলে আল্লাহ তাঁর কসম পূরণ করবেন '
        'বলা হতো। তাঁর একজন বৃদ্ধা মা ছিলেন যাঁর প্রতি তিনি '
        'সদাচরণ করতেন এবং সেবা করতেন। নবী ﷺ বিশেষভাবে '
        'খলিফা উমর ইবনুল খাত্তাবকে অসিয়ত করেছিলেন যে তাঁর '
        'সাথে দেখা হলে তাঁর কাছে ক্ষমা প্রার্থনার দোয়া করার জন্য '
        'অনুরোধ করবেন, কারণ তাঁর দোয়া কবুল হয়। বছর পার হলো, '
        'শেষ পর্যন্ত ইয়েমেনের অধিবাসীদের একটি প্রতিনিধিদল মদিনায় '
        'উমর ইবনুল খাত্তাবের কাছে এলো, তখন উমর তাঁর অভ্যাস '
        'অনুযায়ী জিজ্ঞেস করলেন যেমন প্রতিবার ইয়েমেনের প্রতিনিধিদল '
        'এলে জিজ্ঞেস করতেন: "তোমাদের মধ্যে কি উওয়াইস ইবনে '
        'আমির আছেন?" শেষ পর্যন্ত তিনি তাঁকে আগতদের মধ্যে '
        'খুঁজে পেলেন। উমর তাঁকে তাঁর নাম, গোত্র ও অবস্থা জিজ্ঞেস '
        'করলেন, তিনি নবী ﷺ-এর বলা একই বৈশিষ্ট্য দিয়ে উত্তর '
        'দিলেন: "মুরাদ থেকে তারপর কারন থেকে, আর আমার একজন '
        'মা আছেন যাঁর আমি সেবা করি, আর আমার ত্বকের রোগ ছিল '
        'আমি আল্লাহর কাছে দোয়া করলাম আল্লাহ তা দূর করলেন '
        'কেবল দিরহামের মতো একটি জায়গা ব্যতীত।" তখন উমর '
        'নিশ্চিত হলেন যে এটিই সেই কাঙ্ক্ষিত ব্যক্তি, তিনি জনসাধারণের '
        'কাছে অপরিচিত একজন ব্যক্তির কাছে খলিফার বিনয়ের সাথে '
        'অনুরোধ করলেন: "আমার জন্য ক্ষমা প্রার্থনা করুন।" তখন '
        'উওয়াইস তাঁর জন্য ক্ষমা প্রার্থনা করলেন, যদিও উওয়াইস '
        'নিজে জীবনে কখনো নবী ﷺ-কে দেখেননি এবং তাঁর সাথে '
        'কখনো সাক্ষাৎ করেননি, কিন্তু তাঁর হৃদয়ের ঈমান এবং আল্লাহর '
        'সাথে তাঁর আন্তরিকতা এত বড় মর্যাদায় পৌঁছেছিল যে তিনি '
        'একেবারে সর্বোত্তম তাবিঈনদের একজন হলেন, আর এটি একটি '
        'শিক্ষা যে আল্লাহর কাছে মর্যাদা বেশি প্রকাশের দ্বারা নয় '
        'বরং হৃদয়ের সত্যতা ও কর্মের আন্তরিকতার দ্বারা।',
    source: 'সহীহ মুসলিম',
  ),
  'righteous-2': StoryTranslation(
    title: 'গুহায় তিন ব্যক্তি',
    body:
        'তিনজন ব্যক্তি একটি পুরনো যাত্রায় বেরিয়ে পড়ল, তখন বৃষ্টি '
        'তাদের ধরল এবং তারা পাহাড়ের একটি গুহায় আশ্রয় নিল, '
        'তখন পাহাড়ের চূড়া থেকে একটি বিশাল পাথর পড়ে গুহার '
        'দরজা সম্পূর্ণভাবে বন্ধ করে দিল, তারা অন্ধকারে আটকা পড়ল '
        'না নড়তে পারছিল না বের হতে পারছিল, তারা নিশ্চিত হলো '
        'যে যদি তারা এভাবেই থাকে তাহলে তারা এই অন্ধকার '
        'কারাগারে ক্ষুধা ও পিপাসায় মারা যাবে। তখন হতাশার '
        'মুহূর্তে একজন অন্যজনকে বলল: "আল্লাহর কসম, এই পাথর '
        'থেকে তোমাদের কেবল তোমাদের সৎকর্মের মাধ্যমে আল্লাহর '
        'কাছে দোয়াই বাঁচাতে পারে।" তখন তাদের প্রথমজন তার '
        'কাহিনি বলতে শুরু করল: "হে আল্লাহ, আমার দুই বৃদ্ধ '
        'পিতামাতা ছিলেন, আমি আমার পরিবার বা সম্পদকে তাঁদের '
        'আগে কখনো দুধ পান করাতাম না, একদিন কাঠের সন্ধান '
        'আমাকে দূরে নিয়ে গেল, সন্ধ্যা পর্যন্ত আমি তাঁদের কাছে '
        'ফিরিনি এবং তাঁরা ঘুমিয়ে পড়লেন, আমি তাঁদের জন্য দুধ '
        'দোহন করলাম এবং তাঁদের ঘুমন্ত পেলাম, আমি তাঁদের জাগাতে '
        'অপছন্দ করলাম, আর তাঁদের আগে আমার পরিবার বা সম্পদকে '
        'দুধ পান করাতেও অপছন্দ করলাম, তাই আমি পাত্র হাতে নিয়ে '
        'ফজর পর্যন্ত অপেক্ষা করলাম, আর শিশুরা আমার পায়ের কাছে '
        'ক্ষুধায় কাঁদছিল। হে আল্লাহ, যদি আমি এটি আপনার সন্তুষ্টির '
        'জন্য করে থাকি, তাহলে আমরা যে বিপদে আছি তা থেকে '
        'আমাদের মুক্ত করুন।" তখন পাথরটি সামান্য নড়ল, কিন্তু '
        'তারা এখনো বের হতে পারল না। দ্বিতীয়জন বলল: "হে '
        'আল্লাহ, আমার এক চাচাতো বোন ছিল যাকে আমি তীব্রভাবে '
        'ভালোবাসতাম, আমি তাকে একটি খারাপ কাজের জন্য চেয়েছিলাম '
        'কিন্তু সে অস্বীকার করল, শেষ পর্যন্ত একটি তীব্র দুর্ভিক্ষের '
        'বছর তার ওপর এলো, সে অভাবগ্রস্ত হয়ে আমার কাছে এলো, '
        'আমি তাকে একশ বিশ দিনার দিলাম এই শর্তে যে সে নিজেকে '
        'আমার কাছে সমর্পণ করবে, আমি যখন তার ওপর ক্ষমতা '
        'পেলাম, সে বলল: \'আল্লাহকে ভয় করো এবং যথাযথ অধিকার '
        'ছাড়া মোহর খুলো না,\' তখন তীব্র ভালোবাসা সত্ত্বেও আমি '
        'আপনার ভয়ে তাকে ছেড়ে দিলাম এবং তাকে দেওয়া সম্পদও '
        'তার কাছে রেখে দিলাম। হে আল্লাহ, যদি আমি এটি আপনার '
        'সন্তুষ্টির জন্য করে থাকি, তাহলে আমরা যে বিপদে আছি তা '
        'থেকে আমাদের মুক্ত করুন।" তখন পাথরটি আরও নড়ল, কিন্তু '
        'তারা এখনো বের হতে পারল না। তৃতীয়জন বলল: "হে আল্লাহ, '
        'আমি কয়েকজন শ্রমিক নিয়োগ করেছিলাম এবং তাদের সবাইকে '
        'তাদের মজুরি দিয়েছিলাম কেবল একজন ব্যতীত যে তার মজুরি '
        'রেখে চলে গিয়েছিল, আমি তার মজুরি ব্যবসায় বৃদ্ধি করলাম '
        'যতক্ষণ না তা অনেক বেড়ে সম্পদ, গরু, ছাগল ও দাসে পরিণত '
        'হলো, তারপর সে বছরের পর বছর পরে এসে তার অধিকার '
        'চাইল, আমি তাকে বললাম: \'আপনি আমার সম্পদে যা দেখছেন '
        'তা সবই আপনার,\' সে সবকিছু নিয়ে গেল কিছুই রেখে গেল না। '
        'হে আল্লাহ, যদি আমি এটি আপনার সন্তুষ্টির জন্য করে থাকি, '
        'তাহলে আমরা যে বিপদে আছি তা থেকে আমাদের মুক্ত করুন।" '
        'তখন এই শেষ দোয়ার পর পাথরটি সম্পূর্ণ খুলে গেল, তিনজনই '
        'সূর্যালোকে হেঁটে মুক্ত হয়ে বেরিয়ে এলো, তাদের সত্যিকারের '
        'কর্মের বরকতে যা তারা কেবল আল্লাহর জন্য একনিষ্ঠভাবে '
        'করেছিল কোনো মানুষ তা জানত না তা সত্ত্বেও।',
    source: 'সহীহ বুখারী ও মুসলিম',
  ),
  'righteous-3': StoryTranslation(
    title: 'উমর ইবনে আবদুল আজিজ ও তাঁর ন্যায়বিচার',
    body:
        'উমর ইবনে আবদুল আজিজ ছিলেন উমাইয়াদের সবচেয়ে '
        'ধনী যুবকদের একজন, তিনি তাঁর সময়ের রাজপুত্রদের মতো '
        'আরামদায়ক জীবন যাপন করতেন, শেষ পর্যন্ত খলিফা সুলাইমান '
        'ইবনে আবদুল মালিকের মৃত্যুর পর অপ্রত্যাশিতভাবে খিলাফত '
        'তাঁর কাছে এলো যিনি তাঁকে তাঁর উত্তরসূরি হিসেবে বেছে '
        'নিয়েছিলেন যদিও তিনি তাঁর পুত্র ছিলেন না। তাঁর খিলাফতের '
        'প্রথম দিনে, তিনি জনগণের সামনে এলেন কাঁদতে কাঁদতে '
        'খুতবা দিলেন, বললেন যে তাঁর এই বিষয়ে কোনো আকাঙ্ক্ষা '
        'বা লোভ নেই, তিনি জনগণকে অন্য কারো কাছে বাইআত '
        'দিতে বললেন যদি তারা চায়, কিন্তু জনগণ তাঁর তাকওয়া '
        'জানার কারণে খুশি মনে তাঁর কাছে বাইআত দিল। ক্ষমতা '
        'গ্রহণের পর তাঁর প্রথম কাজ ছিল তাঁর ও তাঁর পরিবারের কাছে '
        'থাকা সব সম্পত্তি যা তারা বৈধ অধিকার দিয়ে পায়নি তা জড়ো '
        'করা এবং সবকিছু বায়তুল মালে ফিরিয়ে দেওয়া, এমনকি তাঁর '
        'পরনের আংটিও বিক্রি করা হলো এবং তার মূল্য সরকারি '
        'কোষাগারে জমা দেওয়া হলো; এভাবে তাঁর পরিবারের অবস্থা '
        'অতিরিক্ত সম্পদ থেকে সাধারণ জীবিকার জীবনে পরিণত হলো। '
        'তিনি মুসলিম ও অমুসলিমের মধ্যে কোনো পার্থক্য না করে '
        'তাঁর সব প্রজার মধ্যে ন্যায়বিচারের প্রতি গভীর মনোযোগ '
        'দিলেন, তিনি প্রতিটি অঞ্চলের গভর্নরদের চিঠি লিখলেন '
        'জনগণের ওপর থেকে অত্যাচার তুলে নিতে এবং অধিকার তার '
        'প্রকৃত মালিকদের কাছে ফিরিয়ে দিতে, এমনকি বলা হয় যে '
        'তাঁর শাসনামলে ন্যায়বিচারের প্রাচুর্য ও অত্যাচারের স্বল্পতার '
        'কারণে দারিদ্র্য প্রায় নির্মূল হয়ে গিয়েছিল, আর মানুষ যাকাত '
        'গ্রহণের যোগ্য কাউকে খুঁজত কিন্তু গ্রহণ করার মতো কোনো '
        'দরিদ্র মানুষ পেত না। তাঁর খিলাফত মাত্র আড়াই বছর স্থায়ী '
        'হলো, তারপর তিনি অল্প বয়সেই মারা গেলেন, কিন্তু তাঁর '
        'ন্যায়বিচারের প্রভাব ইসলামের ইতিহাসে চিরস্থায়ী হয়ে রইল, '
        'এমনকি তাঁকে প্রথম চার খলিফার পর পঞ্চম রাশিদুন খলিফা '
        'হিসেবে গণ্য করা হয়।',
    source:
        'ইতিহাস ও সীরাতের কিতাব — ইবনুল জাওজীর উমর '
        'ইবনে আবদুল আজিজের সীরাতের মতো',
  ),
  'righteous-4': StoryTranslation(
    title: 'হাসান আল-বসরীর তাকওয়া',
    body:
        'হাসান আল-বসরী তাবিঈনদের সবচেয়ে বিখ্যাত আলিমদের '
        'একজন এবং উপদেশে সবচেয়ে তাকওয়াবান ও প্রজ্ঞাবান ছিলেন, '
        'এমনকি তিনি কথা বললে তাঁর আশেপাশের লোকেরা তাঁর '
        'সত্যতা ও তাঁর নিজের কথায় প্রভাবিত হওয়ার কারণে কাঁদতেন। '
        'একজন লোক একদিন তাঁকে জিজ্ঞেস করল: "আপনি কেমন '
        'সকাল করলেন, হে আবু সাঈদ?" তিনি একটি প্রজ্ঞাময় উত্তর '
        'দিলেন যা ভুলে যাওয়া হয়নি: "আমরা সকাল-সন্ধ্যা করি আর '
        'আমাদের নির্ধারিত সময় অন্যের হাতে, তাই যে জীবিত অবস্থায় '
        'মৃত্যু দেখতে চায় সে আমাদের দেখুক। আমরা দুনিয়ায় অতিথি '
        'হিসেবে সকাল করি, আর আমাদের সম্পদ এতে একটি ধার, '
        'তাই অতিথি বিদায় নেবে, আর ধার ফেরত দিতে হবে।" তিনি '
        'অন্যদের পাপের চেয়ে নিজের অহংকার ও আত্মপ্রশংসার প্রতি '
        'বেশি ভয় পেতেন, তিনি তাঁর সাহাবিদের বলতেন: "আমি '
        'কখনো এমন কিছু দেখিনি যাতে আমি আল্লাহকে তার চেয়ে '
        'বড় না দেখেছি," তিনি প্রতিটি দৃশ্যে আল্লাহর মহত্ত্ব স্মরণ '
        'করার প্রতি ইঙ্গিত করছিলেন। মৃত্যু স্মরণে তাঁর সবচেয়ে '
        'বিখ্যাত উক্তিগুলোর একটি: "আমি মৃত্যুর চেয়ে বেশি নিশ্চিত, '
        'সন্দেহহীন এমন কিছু দেখিনি যা এত বেশি সন্দেহযুক্ত, '
        'নিশ্চয়তাবিহীন এমন কিছুর মতো মনে হয়; মানুষ মৃত্যু সম্পর্কে '
        'নিশ্চিত হওয়া সত্ত্বেও এমন কাজ করে যেন তারা এতে নিশ্চিত '
        'নয়," হাসান দেখেছিলেন যে মৃত্যু সম্পর্কে নিশ্চিত থাকা সত্ত্বেও '
        'এর প্রতি উদাসীনতা মানুষের আচরণের সবচেয়ে বিস্ময়কর '
        'বৈপরীত্যগুলোর একটি। তিনি দুনিয়ায় বিরাগী জীবন যাপন '
        'করলেন যদিও খলিফা ও গভর্নররা তাঁর উপদেশ শুনতে তাঁর '
        'কাছে আসতেন এবং অনেক বিষয়ে তাঁর মতামত অনুসরণ '
        'করতেন, এই মর্যাদা মর্যাদা বা সম্পদের জন্য ব্যবহার না করে।',
    source:
        'জীবনীর কিতাব — আবু নুয়াইমের হিলইয়াতুল আউলিয়ার '
        'মতো',
  ),
  'righteous-5': StoryTranslation(
    title: 'সাঈদ ইবনে মুসাইয়িবের দৃঢ়তা',
    body:
        'সাঈদ ইবনে মুসাইয়িব তাঁর সময়ের তাবিঈনদের নেতা ছিলেন '
        'এবং সাহাবিদের বিচার ও রায় সম্পর্কে সবচেয়ে জ্ঞানী ছিলেন, '
        'এমনকি তাঁর জ্ঞান প্রতিটি অঞ্চলে দৃষ্টান্ত হিসেবে উদাহরণ '
        'দেওয়া হতো, জ্ঞানপিপাসুরা তাঁর কাছে সর্বত্র থেকে আসতেন। '
        'তাঁর সময়ের শাসক তাঁকে প্রস্তাব দিলেন তাঁর মেয়েকে খলিফার '
        'পুত্রের সাথে বিয়ে দিতে, এটি এমন একটি প্রস্তাব ছিল যা '
        'অনেক মানুষের স্বপ্ন ছিল এতে থাকা মর্যাদা ও প্রভাবের '
        'কারণে, কিন্তু সাঈদ কোনো দ্বিধা ছাড়াই এই প্রস্তাব প্রত্যাখ্যান '
        'করলেন, কারণ তিনি চাননি তাঁর জ্ঞান বা মানুষের সাথে '
        'নৈকট্য দুনিয়াবি লাভ অর্জনের বা ক্ষমতার সাথে আত্মীয়তার '
        'উপায় হোক, তিনি এর পরিবর্তে তাঁর মেয়েকে তাঁর একজন '
        'দরিদ্র জ্ঞানপিপাসু ছাত্রের সাথে বিয়ে দিলেন, তাঁর সম্পদ '
        'বা মর্যাদার জন্য নয় বরং তাঁর জ্ঞান ও তাকওয়ার সম্মানার্থে। '
        'সাঈদ কিছু গভর্নরের কাছ থেকে তীব্র চাপের মুখোমুখি হলেন '
        'যারা চেয়েছিলেন তিনি একটি নির্দিষ্ট বাইআত দিন বা তিনি '
        'সঠিক মনে করা একটি মতামত ত্যাগ করুন, তিনি এই সবকিছু '
        'প্রত্যাখ্যান করলেন এবং তাঁর অবস্থান রক্ষার জন্য তীব্র কষ্ট '
        'ও প্রহার সহ্য করলেন, কিন্তু তিনি তাঁর মতামত থেকে এক '
        'বিন্দুও সরলেন না, তিনি প্রায়ই তাঁর বিখ্যাত উক্তি পুনরাবৃত্তি '
        'করতেন: "আমি আমার দ্বীন কারো দুনিয়ার সাথে বিক্রি করি '
        'না।" এই দৃঢ়তা দিয়ে তিনি সত্যের ওপর অবিচল থাকার '
        'একটি দৃষ্টান্ত হলেন, তাঁর মৃত্যুর শতাব্দীর পরও ফিকহ ও '
        'তাকওয়ায় অনুসরণীয় একজন শিক্ষক হিসেবে থেকে গেলেন।',
    source:
        'জীবনীর কিতাব — যাহাবীর সিয়ার আলামিন নুবালার '
        'মতো',
  ),
  'righteous-6': StoryTranslation(
    title: 'পরীক্ষায় ইমাম আহমদ ইবনে হাম্বলের দৃঢ়তা',
    body:
        'খলিফা মামুন ও তাঁর পরে মুতাসিমের সময়ে, রাষ্ট্র আকিদার '
        'একটি মতামত গ্রহণ করল যা বলে কুরআন সৃষ্ট, তারা হুমকি '
        'ও শাস্তির অধীনে আলিমদের এটি বলতে বাধ্য করল, অনেক '
        'আলিম কারাদণ্ড বা মৃত্যুর ভয়ে সম্মত হলেন, কেবল ইমাম '
        'আহমদ ইবনে হাম্বল একাই এই মতামত প্রত্যাখ্যান করার জন্য '
        'দাঁড়িয়ে রইলেন সালাফের আকিদা থেকে শিখেছিলেন তা দৃঢ়ভাবে '
        'ধরে রেখে, তিনি এমন কোনো কথা বলতে অস্বীকার করলেন '
        'যার প্রমাণ কিতাব ও সুন্নাহে নেই, যত মূল্যই তাঁকে দিতে হোক '
        'না কেন। ইমাম আহমদকে দীর্ঘ বছর কারাদণ্ড দেওয়া হলো, '
        'জনসাধারণের সামনে তীব্র চাবুক দিয়ে প্রহার করা হলো '
        'এমনকি তিনি একাধিকবার অজ্ঞান হয়ে গেলেন, তা সত্ত্বেও তিনি '
        'তাঁর অবস্থান থেকে সরলেন না, তিনি তাঁর চারপাশের মানুষকে '
        'বলতেন: "আমি কীভাবে এমন কথা বলব যা আল্লাহ বলেননি '
        'এবং তাঁর রাসূলও বলেননি এবং আমার আগে সাহাবিরাও '
        'বলেননি?" আর যখন তাঁকে বেছে নিতে বলা হলো তাদের সাথে '
        'একমত হয়ে মুক্ত ও সম্মানিত হবেন, নাকি তাঁর মতামতে '
        'অবিচল থেকে নির্যাতিত হবেন, তিনি তাঁর সত্য বলে বিশ্বাস '
        'করা বিষয়ের বিরোধিতার চেয়ে নির্যাতন বেছে নিলেন। এই '
        'পরীক্ষা তিন খলিফার শাসনামল জুড়ে দীর্ঘ বছর ধরে চলল, '
        'শেষ পর্যন্ত পরিস্থিতি পরিবর্তিত হলো এবং ইমাম আহমদ '
        'একাই প্রায় বড় আলিমদের মধ্যে যে আহলুস সুন্নাহর মতামত '
        'রক্ষা করেছিলেন তা জয়ী হলো; এভাবে তিনি এই চিরন্তন '
        'দৃষ্টান্ত হলেন যে একজন ব্যক্তির সত্যের ওপর দৃঢ়তা একটি '
        'সমগ্র উম্মতের আকিদাকে বিচ্যুতি থেকে রক্ষা করতে পারে।',
    source:
        'জীবনী ও ইতিহাসের কিতাব — যাহাবীর সিয়ার আলামিন '
        'নুবালার মতো',
  ),
  'righteous-7': StoryTranslation(
    title: 'ফুদাইল ইবনে ইয়াদের তওবা',
    body:
        'ফুদাইল ইবনে ইয়াদ তাঁর তওবার আগে খুরাসান ও সারাখসের '
        'মধ্যে যাত্রীদের ভয় দেখানো একজন বিখ্যাত ডাকাত ছিলেন, '
        'তাঁর নিষ্ঠুরতা ও ডাকাতির সাহসের জন্য পরিচিত ছিলেন। '
        'তাঁর বিস্ময়কর তওবার কাহিনি শুরু হলো এক রাতে যখন তিনি '
        'অন্যায়ভাবে ভালোবাসা একজন নারীকে দেখার জন্য একটি '
        'দেয়ালে উঠছিলেন, তিনি যখন দেয়ালের ওপরে ছিলেন, তখন '
        'তিনি একজন কারীকে পার্শ্ববর্তী বাড়ি থেকে আল্লাহর কিতাবের '
        'একটি আয়াত পাঠ করতে শুনলেন: "যারা ঈমান এনেছে তাদের '
        'অন্তর আল্লাহর স্মরণে বিনম্র হওয়ার সময় কি এখনো আসেনি?" '
        'তখন এই আয়াতটি তাঁর হৃদয়ে আঘাত করল, তিনি দেয়ালের '
        'ওপর থাকা অবস্থায়ই তৎক্ষণাৎ নিজেকে বললেন: "হ্যাঁ, হে '
        'আমার রব, সময় এসেছে।" তিনি যা করতে চেয়েছিলেন তা '
        'ছেড়ে তৎক্ষণাৎ দেয়াল থেকে নেমে গেলেন, সেই রাতে থাকার '
        'জন্য একটি ভাঙা ও পরিত্যক্ত জায়গার দিকে গেলেন, সেখানে '
        'তিনি হঠাৎ ভয়ে একে অপরের সাথে কথা বলা কিছু যাত্রীর '
        'সাথে মিলিত হলেন, তারা বলছিল: "ডাকাত ফুদাইল ঘুমালে '
        'আমরা ফজরে রওনা দেব যাতে সে আমাদের পথ না আটকায়।" '
        'নিজের নাম শোনা এবং সেই মুহূর্তে মানুষের তাঁর প্রতি ভয় '
        'তাঁর হৃদয়ের ভাঙন ও অনুশোচনা আরও বাড়িয়ে দিল, তিনি '
        'নিজেকে বললেন: "আমি রাতগুলো পাপে কাটাই এবং তাদের '
        'রিজিকের সন্ধানে যাত্রাকারী মুসলিম যাত্রীদের ভয় দেখাই, '
        'আল্লাহর কসম, আল্লাহ আমাকে এই জায়গায় নিয়ে এসেছেন '
        'আমাকে হিদায়াত দিতে!" তিনি সেই রাত থেকে তাঁর পুরনো '
        'জীবন সম্পূর্ণভাবে ত্যাগ করলেন, নিজেকে ইবাদত ও জ্ঞানার্জনের '
        'জন্য উৎসর্গ করলেন এমনকি তিনি তাঁর সময়ের সবচেয়ে বড় '
        'আলিমদের একজন এবং সবচেয়ে বেশি ইবাদতকারী ও তাকওয়াবান '
        'হলেন, এমনকি তাঁকে "আবিদুল হারামাইন" উপাধি দেওয়া '
        'হলো মক্কা ও মদিনায় তাঁর দীর্ঘ অবস্থান ও ইবাদতের কারণে; '
        'এভাবে তিনি ভয়ঙ্কর একজন ডাকাত থেকে জুহদ ও তাকওয়ায় '
        'অনুসরণীয় একজন পথপ্রদর্শকে রূপান্তরিত হলেন।',
    source:
        'জীবনীর কিতাব — আবু নুয়াইমের হিলইয়াতুল আউলিয়ার '
        'মতো',
  ),
  'righteous-8': StoryTranslation(
    title: 'রাবিয়া আল-আদাবিয়া ও আল্লাহর ভালোবাসা',
    body:
        'রাবিয়া আল-আদাবিয়া বসরায় একটি দরিদ্র পরিবারে জন্মগ্রহণ '
        'করেছিলেন, শৈশবেই এতিম হয়েছিলেন, শেষ পর্যন্ত তিনি '
        'দাসত্বে পড়লেন এবং একজন ব্যক্তির কাছে দাসী হিসেবে '
        'বিক্রি হলেন। তাঁর মালিক একরাতে দেখলেন একটি আলো '
        'পুরো ঘর আলোকিত করছে যখন তিনি মধ্যরাতে সিজদায় '
        'নামাজ পড়ছিলেন, তখন তিনি বুঝলেন তিনি অন্য দাসীদের '
        'মতো নন, তখন তিনি তাঁর ইবাদতের আন্তরিকতা দেখে তৎক্ষণাৎ '
        'একটি সম্মান হিসেবে তাঁকে মুক্ত করে দিলেন। এরপর রাবিয়া '
        'নিজেকে সম্পূর্ণভাবে কেবল তাঁর রবের ইবাদতে উৎসর্গ '
        'করলেন, তাঁর কাছে আসা ধনী ও তাকওয়াবান, উচ্চ মর্যাদার '
        'অনেক বিয়ের প্রস্তাব প্রত্যাখ্যান করলেন, তিনি বলতেন যে '
        'তিনি তাঁর হৃদয়ে তাঁর রবের ভালোবাসা ব্যতীত কোনো স্থান '
        'পান না যা তাঁকে দুনিয়ার সব কিছু থেকে ব্যস্ত রেখেছে। '
        'রাবিয়া মানুষকে শেখানোর জন্য বিখ্যাত হলেন যে প্রকৃত '
        'ইবাদত কেবল তাঁর জান্নাতের আশায় বা তাঁর জাহান্নামের '
        'ভয়ে নয় বরং আল্লাহর প্রতি একটি বিশুদ্ধ ভালোবাসা হওয়া '
        'উচিত, তিনি তাঁর বিখ্যাত দোয়ায় বলতেন: "হে আল্লাহ, যদি '
        'আমি আপনার জাহান্নামের ভয়ে আপনার ইবাদত করি, তাহলে '
        'আমাকে তা দিয়ে পুড়িয়ে দিন; আর যদি আমি আপনার জান্নাতের '
        'আশায় আপনার ইবাদত করি, তাহলে তা থেকে আমাকে বঞ্চিত '
        'করুন; কিন্তু যদি আমি কেবল আপনার সত্তার জন্য আপনার '
        'ইবাদত করি, তাহলে আপনার চিরন্তন সৌন্দর্য থেকে আমাকে '
        'বঞ্চিত করবেন না।" তিনি রাতের সময়গুলো তাঁর নামাজে '
        'কাঁদতে কাঁদতে কাটাতেন, তাঁর রবের স্মরণে এত গভীরভাবে '
        'ডুবে যেতেন যে তিনি তাঁর চারপাশের দুনিয়ার বিষয়গুলো '
        'ভুলে যেতেন; এভাবে তাঁর দৃষ্টান্ত পরবর্তী প্রজন্মের জন্য '
        'ইবাদতে সম্পূর্ণ আন্তরিকতার অর্থ বুঝার ভিত্তি হলো, যেকোনো '
        'হিসাব বা প্রতিদান থেকে দূরে।',
    source:
        'জীবনীর কিতাব — ইবনুল জাওজীর সিফাতুস সাফওয়ার '
        'মতো',
  ),

  // ===== শিশুদের জন্য কাহিনি =====
  'child-1': StoryTranslation(
    title: 'জমজম ও ছোট্ট ইসমাইল',
    body:
        'নবী ইব্রাহিম তাঁর স্ত্রী হাজেরা ও শিশু পুত্র ইসমাইলকে এমন '
        'একটি উপত্যকায় রেখে গেলেন যেখানে পানি বা ফসল কিছুই '
        'ছিল না, তাঁর রবের নির্দেশ পালনে। হাজেরা তাঁকে জিজ্ঞেস '
        'করলেন: "আল্লাহ কি আপনাকে এটি করতে নির্দেশ দিয়েছেন?" '
        'তিনি বললেন: "হ্যাঁ," তখন তিনি প্রশান্তির সাথে বললেন: '
        '"তাহলে তিনি আমাদের নষ্ট করবেন না।" তাদের কাছে থাকা '
        'পানি শেষ হয়ে গেলে এবং ইসমাইল পিপাসায় কাঁদতে '
        'শুরু করলে, হাজেরা সাফা ও মারওয়া পাহাড়ের মধ্যে সাতবার '
        'দৌড়ালেন এমন পানি বা মানুষের চিহ্নের খোঁজে যা তাঁকে '
        'সাহায্য করতে পারে, অথচ ইসমাইল পিপাসার তীব্রতায় কাঁদছিলেন '
        'এবং বালুর ওপর তাঁর ছোট পা নাড়াচাড়া করছিলেন। তখন '
        'আল্লাহ তাঁর পায়ের নিচ থেকে একটি প্রচুর পানির ঝর্ণা '
        'প্রবাহিত করলেন, হাজেরা দ্রুত তা জড়ো করতে লাগলেন এবং '
        'বললেন: "জাম্মি, জাম্মি" — অর্থাৎ একত্রিত হও — সেখান '
        'থেকেই এর নাম হলো জমজম। এই কূপ থেকে যা একজন '
        'তরুণী মা ও তাঁর শিশু জনমানবহীন মরুভূমিতে পান করেছিলেন, '
        'হাজার হাজার বছর পর আজও তা পানি দিয়ে প্রবাহিত হয়, '
        'প্রতি বছর লক্ষ লক্ষ হাজি ও উমরাহকারী এর থেকে পান করেন।',
    source: 'সহীহ বুখারী (শিশুদের জন্য সরলীকৃত)',
  ),
  'child-2': StoryTranslation(
    title: 'সত্যবাদী বালক',
    body:
        'একটি ছোট বালক ছিল যে রাজার জাদুকরের কাছে শিক্ষা '
        'নিচ্ছিল, প্রতিদিন তার পথে সে একজন সৎ সন্ন্যাসীর পাশ '
        'দিয়ে যেত, তার কথা তার ভালো লাগত, তখন সে গোপনে '
        'আল্লাহর প্রতি ঈমান আনল। আল্লাহ তাকে একটি বিস্ময়কর '
        'বরকত দিলেন: আল্লাহর অনুমতিতে অসুস্থদের সুস্থ করার '
        'জন্য দোয়া করার ক্ষমতা, এমনকি সে জন্ম থেকে দেখতে না '
        'পারা এক অন্ধকে সুস্থ করল। অত্যাচারী রাজা এটি জানল এবং '
        'সে রাজা ছাড়া অন্য রবের প্রতি ঈমান আনায় রাগান্বিত হলো, '
        'তখন সে অনেক উপায়ে তাকে হত্যা করার চেষ্টা করল, কিন্তু '
        'আল্লাহ প্রতিবার তাকে রক্ষা করলেন। শেষ পর্যন্ত, বালকটি '
        'রাজাকে তাকে হত্যা করার একটি উপায় বলল: মানুষকে এক '
        'জায়গায় জড়ো করে এই কথা বলে তাকে তীর দিয়ে আঘাত '
        'করা: "আল্লাহর নামে, যিনি বালকের রব।" আর যদিও এতে '
        'তার মৃত্যু হবে, তবুও সে চেয়েছিল সবাই তার মৃত্যুর আগে '
        'তাদের রবের প্রতি ঈমান ঘোষণা করুক। তখন রাজা তাই করল, '
        'বালকটি মারা গেল, কিন্তু এই দৃশ্য প্রত্যক্ষ করা সবাই একসাথে '
        'চিৎকার করে বলল: "আমরা বালকের রবের প্রতি ঈমান '
        'আনলাম!" এভাবে বালকটি তার মৃত্যু সত্ত্বেও বিজয়ী হলো, '
        'কারণ তার মাধ্যমেই তার সমগ্র সম্প্রদায় ঈমান আনল।',
    source: 'সহীহ মুসলিম (শিশুদের জন্য সরলীকৃত)',
  ),
  'child-3': StoryTranslation(
    title: 'কাঁদা খেজুর কাণ্ড',
    body:
        'নবী ﷺ জুমার দিন মসজিদে একটি পুরনো খেজুর গাছের '
        'কাণ্ডে হেলান দিয়ে মানুষকে খুতবা দিতেন, কারণ তখনো '
        'কোনো মিম্বার ছিল না। যখন তাঁর সাহাবিরা তাঁর জন্য ধাপযুক্ত '
        'একটি সুন্দর কাঠের মিম্বার তৈরি করলেন এবং নবী ﷺ পুরনো '
        'কাণ্ডটি ছেড়ে মিম্বারে উঠলেন, তখন মসজিদে থাকা সবাই '
        'একটি অদ্ভুত শব্দ শুনল: সেই কাণ্ড থেকে আসা কান্না ও ফোঁপানোর '
        'শব্দ, যা একটি দুঃখী ছোট শিশুর কান্নার মতো মনে হচ্ছিল! সেই '
        'কাণ্ডটি নবী ﷺ থেকে বিচ্ছিন্ন হওয়ার দুঃখে কাঁদছিল, কারণ '
        'এটি তাঁর হেলান দেওয়ার অভ্যস্ত হয়ে গিয়েছিল, তখন নবী ﷺ '
        'তৎক্ষণাৎ তাঁর মিম্বার থেকে নেমে তাঁর পবিত্র হাত দিয়ে '
        'কাণ্ডটি জড়িয়ে ধরলেন যতক্ষণ না তা চুপ ও শান্ত হলো, ঠিক '
        'যেমন একজন মা তার কাঁদতে থাকা শিশুকে জড়িয়ে ধরেন। '
        'আর নবী ﷺ তাঁর সাহাবিদের বললেন: "আমি যদি একে জড়িয়ে '
        'না ধরতাম, তাহলে এটি কিয়ামত পর্যন্ত এভাবেই কাঁদতে '
        'থাকত আমার থেকে বিচ্ছেদের দুঃখে।"',
    source: 'সহীহ বুখারী (শিশুদের জন্য সরলীকৃত)',
  ),
  'child-4': StoryTranslation(
    title: 'কথা বলা নেকড়ে',
    body:
        'একজন রাখাল মরুভূমিতে তার ছাগল চরাচ্ছিল, তখন হঠাৎ '
        'একটি নেকড়ে এসে তার একটি ছাগল ধরে নিয়ে দৌড়ে গেল, '
        'রাখাল দ্রুত তার পিছু নিল এবং ছাগলটিকে তার থেকে বাঁচাতে '
        'সক্ষম হলো। কিন্তু নেকড়েটি এমন কিছু করল যা আগে কখনো '
        'ঘটেনি: এটি একটি উঁচু স্থানে দাঁড়াল এবং এমন ভাষায় কথা '
        'বলল যা রাখাল বুঝতে পারল, তাকে বলল: "তুমি কি আল্লাহকে '
        'ভয় করো না? তুমি আমাকে আল্লাহর দেওয়া রিজিক থেকে '
        'বঞ্চিত করছ!" রাখাল অত্যন্ত বিস্মিত হলো, আগে কি কেউ '
        'কখনো একটি নেকড়েকে মানুষের মতো কথা বলতে দেখেছে? '
        'সে দ্রুত মানুষকে যা ঘটেছে তা জানাতে গেল, তখন খবরটি '
        'নবী ﷺ-এর কাছে পৌঁছাল, তিনি এই ঘটনাটি সত্য বলে '
        'নিশ্চিত করলেন এবং একে অস্বাভাবিক মনে করলেন না, তিনি '
        'বললেন এটি কিয়ামতের নিকটবর্তী হওয়ার নিদর্শনগুলোর '
        'একটি, আর আল্লাহ সবকিছুর ওপর ক্ষমতাবান, এমনকি তিনি '
        'চাইলে তাঁর অনুমতিতে একটি প্রাণীকেও কথা বলাতে পারেন।',
    source: 'সহীহ বুখারী (শিশুদের জন্য সরলীকৃত)',
  ),
  'child-5': StoryTranslation(
    title: 'মূসা ও সৎ ব্যক্তি',
    body:
        'মূসা আলাইহিস সালাম একজন সৎ ব্যক্তির কাছ থেকে শিখতে '
        'চাইলেন যাকে আল্লাহ একটি বিশেষ জ্ঞান দিয়েছিলেন যা '
        'অন্য কেউ জানত না, তখন সেই ব্যক্তি একটি শর্তে তাঁর সাথে '
        'থাকতে রাজি হলেন: মূসা তিনি নিজে ব্যাখ্যা করার আগে '
        'তাঁর করা কোনো কাজ সম্পর্কে প্রশ্ন করবেন না। কিন্তু মূসা '
        'সেই ব্যক্তিকে খুবই অদ্ভুত কাজ করতে দেখলেন: প্রথমে তিনি '
        'একটি নৌকা ছিদ্র করলেন যা তাদের বিনামূল্যে বহন করছিল, '
        'তখন মূসা বিস্মিত হয়ে তাঁর প্রতিশ্রুতি সত্ত্বেও তাকে প্রশ্ন '
        'করলেন! তারপর তিনি সেই ব্যক্তিকে একটি নিরপরাধ ছোট '
        'বালককে হত্যা করতে দেখলেন, তখন মূসা নিজেকে ধরে '
        'রাখতে পারলেন না এবং আবার প্রশ্ন করলেন, তখন সেই '
        'ব্যক্তি তাঁকে বললেন: "আমি কি বলিনি যে আপনি আমার সাথে '
        'ধৈর্য ধরতে পারবেন না?" তারপর তৃতীয় একটি গ্রামে সেখানকার '
        'মানুষ তীব্র ক্ষুধা সত্ত্বেও তাদের খাবার দিতে অস্বীকার করল, '
        'তা সত্ত্বেও সেই ব্যক্তি একটি ধসে পড়ার মতো দেয়াল বিনা '
        'মজুরিতে মেরামত করলেন! মূসা তৃতীয়বার জিজ্ঞেস করলেন, '
        'তখন সেই ব্যক্তি বললেন: "এটিই আমার ও আপনার মধ্যে '
        'বিচ্ছেদ, তবে আমি আগে আপনাকে যা করেছি তার সব হিকমত '
        'বলে দেব।" তিনি তাঁকে বললেন নৌকাটি গরিব মানুষদের ছিল, '
        'এবং তিনি এটিকে ত্রুটিযুক্ত করেছিলেন যাতে প্রতিটি ভালো '
        'নৌকা জোরপূর্বক নিয়ে যাওয়া একজন অত্যাচারী রাজা থেকে '
        'এটি রক্ষা পায়। আর বালকটি, বড় হলে তার মুমিন পিতামাতাকে '
        'কষ্ট দেওয়া একজন খারাপ মানুষ হতো, তাই আল্লাহ তাদের '
        'তার বদলে তার চেয়ে ভালো একটি সন্তান দিলেন। আর দেয়ালটি, '
        'তার নিচে দুই ছোট এতিমের একটি লুকানো ধনভাণ্ডার ছিল, '
        'আল্লাহ তা তাদের জন্য সংরক্ষণ করলেন যতক্ষণ না তারা বড় '
        'হয়। এভাবে মূসা জানলেন যে প্রতিটি অদ্ভুত কাজে একটি '
        'বড় হিকমত ছিল যা সেই সৎ ব্যক্তি তাঁকে না বললে তিনি '
        'কখনো জানতে পারতেন না।',
    source: 'সূরা আল-কাহফ: ৬০-৮২ (শিশুদের জন্য সরলীকৃত)',
  ),
  'child-6': StoryTranslation(
    title: 'জান্নাতে আদমের কাহিনি',
    body:
        'আল্লাহ আমাদের পিতা আদমকে মাটি দিয়ে সৃষ্টি করলেন, '
        'তাঁর মধ্যে রুহ ফুঁ দিলেন এবং তাঁকে তাঁর চারপাশের সব '
        'কিছুর নাম শেখালেন। তারপর তাঁর জন্য হাওয়া নামে একটি '
        'স্ত্রী সৃষ্টি করলেন, তাঁদের দুজনকে সুন্দর জান্নাতে বসবাস '
        'করালেন এবং তাঁদের বললেন: "এর ফল থেকে যা ইচ্ছা খাও, '
        'যেখানে ইচ্ছা যাও, কেবল একটি গাছ ব্যতীত, তার কাছে যেয়ো '
        'না।" কিন্তু শয়তান — যে আদমকে সিজদা করতে অস্বীকার '
        'করার পর থেকে তাঁর শত্রু হয়েছিল — নীরবে তাঁদের কুমন্ত্রণা '
        'দিতে এলো এবং মিথ্যা কসম খেল যে সে একজন বিশ্বস্ত '
        'উপদেষ্টা, আর এই গাছটি তাঁদের চিরকালের জন্য ফেরেশতা '
        'বানিয়ে দেবে। আদম ও হাওয়া তার কসমে বিশ্বাস করলেন '
        'এবং তাঁদের রবের সতর্কতা ভুলে গেলেন, তখন তাঁরা সেই '
        'গাছ থেকে খেলেন, তৎক্ষণাৎ তাঁরা লজ্জা ও অনুশোচনা '
        'অনুভব করলেন। তখন তাঁরা তৎক্ষণাৎ আল্লাহর কাছে ক্ষমা '
        'চাইলেন এবং তাঁদের শেখানো বাক্য দিয়ে দোয়া করলেন: '
        '"হে আমাদের রব, আমরা নিজেদের ওপর অন্যায় করেছি, '
        'আপনি যদি আমাদের ক্ষমা না করেন এবং আমাদের প্রতি '
        'রহমত না করেন তাহলে আমরা অবশ্যই ক্ষতিগ্রস্তদের অন্তর্ভুক্ত '
        'হব।" তখন আল্লাহ তাঁদের তওবা কবুল করলেন কারণ তিনি '
        'পরম ক্ষমাশীল, অতি দয়ালু, কিন্তু তাঁদের পৃথিবীতে নামিয়ে '
        'দিলেন প্রথম দুই মানুষ হিসেবে যারা এতে বসবাস করবেন, '
        'আর এটি সবার জন্য একটি শিক্ষা হোক যে শয়তানের কুমন্ত্রণায় '
        'বিশ্বাস না করা, তা যতই সুন্দর মনে হোক না কেন।',
    source:
        'সূরা আল-বাকারা: ৩৫-৩৭ ও সূরা ত্বহা: ১১৫-১২৩ '
        '(শিশুদের জন্য সরলীকৃত)',
  ),

  // ===== সাহাবিদের ঘটনাবলি =====
  'companion-1': StoryTranslation(
    title: 'গুহায় আবু বকর',
    body:
        'যখন নবী ﷺ মক্কা থেকে মদিনায় হিজরত করলেন সেই '
        'মুশরিকদের ষড়যন্ত্র থেকে পালিয়ে যারা তাঁকে তাঁর শয্যায় '
        'হত্যা করতে একমত হয়েছিল, তখন তাঁর ঘনিষ্ঠতম বন্ধু আবু '
        'বকর আস-সিদ্দিক এই বিপজ্জনক যাত্রায় তাঁর সঙ্গী হলেন, '
        'তাঁরা দুজন একটি অস্বাভাবিক পথ বেছে নিলেন, প্রথমে তাঁরা '
        'মক্কার দক্ষিণে সাওর গুহায় লুকালেন — মদিনার দিকের '
        'সম্পূর্ণ বিপরীত দিকে যাতে তাঁদের খোঁজকারীদের বিভ্রান্ত '
        'করা যায় — এবং সেখানে পুরো তিন দিন থাকলেন। কুরাইশ '
        'পথ অনুসরণে দক্ষ লোকদের প্রতিটি দিকে পাঠাল তাঁদের '
        'খুঁজতে, এমনকি তাদের কেউ কেউ গুহার মুখ পর্যন্ত পৌঁছে '
        'সেখানে দাঁড়িয়ে কথা বলল, তখন আবু বকর তাদের খুব '
        'কাছের কণ্ঠস্বর শুনলেন, তিনি প্রচণ্ড ভয় পেলেন, নিজের '
        'জন্য নয় বরং নবী ﷺ-এর জন্য, তিনি ফিসফিস করে বললেন: '
        '"হে আল্লাহর রাসূল, তাদের কেউ যদি তাদের পায়ের নিচে '
        'তাকায় তবে আমাদের দেখে ফেলবে।" তখন নবী ﷺ তাঁকে '
        'তাঁর রবের ওপর ভরসাকারী একজন মুমিনের দৃঢ়তার সাথে '
        'উত্তর দিলেন: "হে আবু বকর, তুমি এমন দুজন সম্পর্কে কী '
        'মনে করো যাদের তৃতীয়জন আল্লাহ? দুঃখ করো না, নিশ্চয়ই '
        'আল্লাহ আমাদের সাথে আছেন।" আর আল্লাহ এই ঘটনায় '
        'বিশেষভাবে কুরআনে একটি আয়াত নাজিল করলেন যা সেই '
        'নাজুক মুহূর্তে নবী ﷺ-এর ওপর অবতীর্ণ প্রশান্তি চিরস্থায়ী '
        'করেছে, আর আল্লাহ শত্রুদের এত কাছাকাছি থাকা সত্ত্বেও '
        'তাঁদের উভয়কে রক্ষা করলেন, শেষ পর্যন্ত খোঁজকারীরা গুহা '
        'আবিষ্কার না করেই ফিরে গেল; এভাবে নবী ﷺ ও তাঁর সঙ্গী '
        'মদিনায় হিজরত যাত্রা নিরাপদে সম্পন্ন করলেন।',
    source: 'সূরা আত-তাওবা: ৪০ — সহীহ বুখারী',
  ),
  'companion-2': StoryTranslation(
    title: 'বিলাল ইবনে রাবাহের ধৈর্য',
    body:
        'বিলাল ইবনে রাবাহ ছিলেন মক্কায় উমাইয়া ইবনে খালাফের '
        'কাছে কাজ করা একজন হাবশি দাস, যখন তিনি ইসলামের '
        'দাওয়াত শুনলেন তখনই তিনি পুরো হৃদয় দিয়ে ঈমান আনলেন, '
        'তাঁর মালিক তাঁর ইসলাম গ্রহণের কথা জানল এবং সে তীব্রভাবে '
        'ক্রুদ্ধ হলো এবং তাঁর দ্বীন থেকে ফিরিয়ে আনতে তাঁকে নির্যাতন '
        'করার সিদ্ধান্ত নিল। সে তাঁকে দুপুরের সময় বের করত যখন '
        'মক্কার বালুতে সূর্যের তাপ প্রচণ্ড থাকত, তাঁকে চামড়া প্রায় '
        'ঝলসে দেওয়ার মতো গরম বালুর ওপর পিঠের ওপর ফেলে '
        'রাখত, তারপর তাঁর নির্যাতন বাড়াতে এবং তাঁকে নড়াচড়া '
        'থেকে বিরত রাখতে একটি ভারী পাথর তাঁর বুকের ওপর রাখার '
        'নির্দেশ দিত, সে তাঁকে বলতেই থাকত: "তুমি এভাবেই থাকবে '
        'যতক্ষণ না মারা যাও বা মুহাম্মদকে অস্বীকার করে লাত ও '
        'উজ্জার পূজা করো।" কিন্তু বিলাল, এই অসহনীয় নির্যাতনের '
        'মাঝে, ব্যথার তীব্রতায় ভাঙা কণ্ঠে একটি অবিচল শব্দ বলতে '
        'থাকলেন: "আহাদ, আহাদ" (এক), এই সমস্ত নির্যাতন সত্ত্বেও '
        'আল্লাহর একত্ব ঘোষণা করে এবং কষ্ট যতই বাড়ুক না কেন '
        'তাঁর আকিদায় কোনো আপস মেনে না নিয়ে। একদিন আবু বকর '
        'আস-সিদ্দিক সেখান দিয়ে গেলেন এবং এই বেদনাদায়ক দৃশ্য '
        'দেখলেন, তাঁর হৃদয় বিলালের অবস্থায় ব্যথিত হলো, তিনি '
        'তাঁর মালিকের কাছে গেলেন এবং বড় অর্থের বিনিময়ে তাঁকে '
        'কিনতে দর কষাকষি করলেন, তারপর কেনার সাথে সাথেই '
        'আল্লাহর সন্তুষ্টির জন্য তাঁকে মুক্ত করলেন। এরপর বিলাল '
        'বড় সাহাবিদের একজন হলেন, নবী ﷺ তাঁকে ইসলামের '
        'ইতিহাসের প্রথম মুয়াজ্জিন হিসেবে বেছে নিলেন, তাঁর সুন্দর '
        'কণ্ঠস্বরের সাথে যার জন্য তাঁকে নির্যাতন করা হয়েছিল যেন '
        'তা লুকিয়ে না ফেলেন, এমনকি মক্কা বিজয়ের দিন তিনি নিজে '
        'কাবার ছাদে উঠলেন এবং তাঁকে নির্যাতনকারী কুরাইশদের '
        'সামনে নামাজের জন্য আজান দিলেন; এটি একটি সাক্ষ্য যে '
        'প্রকৃত ঈমান যেকোনো নির্যাতনের চেয়ে শক্তিশালী তা যতই '
        'তীব্র হোক না কেন।',
    source: 'নবী সীরাতের কিতাব',
  ),
  'companion-3': StoryTranslation(
    title: 'নবী ﷺ-এর শয্যায় আলী',
    body:
        'যখন কুরাইশের নেতারা নবী ﷺ-কে একটি চতুর উপায়ে হত্যা '
        'করতে একমত হলো — প্রতিটি গোত্র থেকে একজন যুবক '
        'একসাথে হত্যায় অংশগ্রহণ করবে, যাতে তাঁর রক্ত গোত্রগুলোর '
        'মধ্যে বিভক্ত হয়ে যায় এবং বনু হাশিম তাদের সবার বিরুদ্ধে '
        'প্রতিশোধ নিতে না পারে — তখন আল্লাহ তাঁর নবীকে ﷺ এই '
        'ষড়যন্ত্র বাস্তবায়নের আগেই জানালেন। হত্যাকারীরা রাতে '
        'নবী ﷺ-এর ঘরের দরজার চারপাশে জড়ো হলো তাঁর বের '
        'হওয়ার অপেক্ষায় তাঁকে আক্রমণ করার জন্য, তখন নবী ﷺ তাঁর '
        'চাচাতো ভাই আলী ইবনে আবি তালিবকে, যিনি তখনও যুবক '
        'ছিলেন, প্রস্তাব দিলেন তাঁর সবুজ চাদর পরে তাঁর শয্যায় '
        'শুয়ে থাকতে যাতে বাইরে ওঁৎ পেতে থাকা লোকদের ভুল '
        'ধারণা হয় যে নবী ﷺ এখনো তাঁর ঘরে ঘুমাচ্ছেন, অথচ তিনি '
        'নিজে আল্লাহর দেওয়া সুযোগ থেকে তাদের মধ্যে দিয়ে '
        'না দেখা অবস্থায় সরে যাবেন। আলী পরিস্থিতির বিপদ সম্পূর্ণ '
        'জানা সত্ত্বেও কোনো দ্বিধা ছাড়াই তৎক্ষণাৎ রাজি হলেন, কারণ '
        'তিনি জানতেন যে উন্মুক্ত তরবারিগুলো যেকোনো মুহূর্তে তাঁর '
        'ওপর পড়তে পারে তাঁকে ঘুমন্ত নবী ﷺ মনে করে। আলী সেই '
        'শয্যায় সারারাত শুয়ে রইলেন, দরজায় হত্যাকারীদের ফিসফিসানি '
        'শুনতে শুনতে, নির্ভীক দৃঢ় হৃদয়ে, রাসূলুল্লাহ ﷺ-কে রক্ষা '
        'করার এই মহান আত্মত্যাগ গণনা করতে করতে। আর সকালে, '
        'যখন হত্যাকারীরা দ্রুত কক্ষে প্রবেশ করল, তারা চাদরের '
        'নিচ থেকে নবী ﷺ-এর পরিবর্তে আলীকে বের হতে দেখে '
        'বিস্মিত হলো, তারা বুঝল যে যাত্রা তাদের থেকে অনেক ঘণ্টা '
        'আগেই শুরু হয়ে গেছে, আর সেই মুহূর্তে নবী ﷺ ইতিমধ্যে '
        'সাওর গুহার দিকে তাঁর পথে একটি নিরাপদ দূরত্ব অতিক্রম '
        'করেছিলেন, তারপর মদিনার দিকে।',
    source: 'নবী সীরাতের কিতাব',
  ),
  'companion-4': StoryTranslation(
    title: 'উসমান ও রুমার কূপ',
    body:
        'মদিনায় মুসলিমরা হিজরতের পর একটি বড় সমস্যার '
        'মুখোমুখি হলো: পানের উপযোগী মিষ্টি পানির অভাব, কারণ '
        'তার চারপাশের বেশিরভাগ কূপ লবণাক্ত বা অপর্যাপ্ত ছিল, '
        'অথচ রুমার কূপ নামে একটি মিষ্টি, ভালো পানির কূপ ছিল, '
        'কিন্তু এটি একজন ইহুদি ব্যক্তির ব্যক্তিগত সম্পত্তি ছিল যে '
        'মানুষের প্রয়োজনের সুযোগ নিয়ে এক বালতি পানি খুব '
        'উচ্চমূল্যে বিক্রি করত, যা দরিদ্র মুসলিমদের ওপর ভারী বোঝা '
        'ফেলছিল। নবী ﷺ তাঁর সাহাবিদের জড়ো করলেন এবং '
        'তাঁদের তীব্রভাবে উৎসাহিত করলেন, তাঁদের বললেন: "কে '
        'রুমার কূপ কিনে মুসলিমদের জন্য ওয়াকফ করবে যাতে তার '
        'বিনিময়ে জান্নাত পায়?" তখন উসমান ইবনে আফফান '
        'রাদিয়াল্লাহু আনহু — যিনি তাঁর উদারতার জন্য বিখ্যাত ধনী '
        'সাহাবিদের একজন ছিলেন — তৎক্ষণাৎ ইহুদি মালিকের কাছে '
        'গেলেন, তিনি এটি সম্পূর্ণরূপে কিনতে চেষ্টা করলেন কিন্তু '
        'ইহুদি এর মূল্য জেনে সম্পূর্ণ বিক্রয় প্রত্যাখ্যান করল, তখন '
        'উসমান তাকে একটি মধ্যবর্তী সমাধান দিলেন: তিনি কেবল '
        'অর্ধেক কিনবেন, এই শর্তে যে একদিন মুসলিমদের জন্য এবং '
        'একদিন ইহুদির জন্য পালাক্রমে। ইহুদি অনিচ্ছায় রাজি হলো, '
        'তখন উসমান তাঁর নিজের সম্পদ থেকে বড় অর্থ দিয়ে অর্ধেক '
        'কিনলেন, আর মুসলিমদের জন্য নির্ধারিত দিনে মানুষ দুই '
        'দিনের জন্য যথেষ্ট পানি নিত, তাই অন্য দিন কারো পানি '
        'কিনতে হতো না, শেষ পর্যন্ত ইহুদি ক্রেতা না পাওয়ায় বাকি '
        'অর্ধেকও সস্তা দামে বিক্রি করতে বাধ্য হলো। উসমান কূপটি '
        'সম্পূর্ণভাবে আল্লাহর সন্তুষ্টির জন্য ওয়াকফ করলেন যাতে '
        'সব মুসলিম চিরকালের জন্য বিনামূল্যে উপকৃত হতে পারে; '
        'এভাবে এই সদকা ইসলামের ইতিহাসের সবচেয়ে বড় ওয়াকফগুলোর '
        'একটি হলো, আর এই ওয়াকফের জমি চৌদ্দ শতাব্দীরও বেশি '
        'সময় পার হওয়া সত্ত্বেও আজও বিদ্যমান ও কার্যকর।',
    source: 'তিরমিযি ও নাসাঈর বর্ণনা',
  ),
  'companion-5': StoryTranslation(
    title: 'খালিদ ইবনে ওয়ালিদ, আল্লাহর তরবারি',
    body:
        'খালিদ ইবনে ওয়ালিদ তাঁর ইসলাম গ্রহণের আগে কুরাইশের '
        'সবচেয়ে কঠোর ও যুদ্ধকলায় সবচেয়ে দক্ষ অশ্বারোহীদের '
        'একজন ছিলেন, এমনকি তিনিই ছিলেন যিনি উহুদ যুদ্ধে '
        'মুশরিকদের নেতৃত্ব দিয়েছিলেন এবং একটি বুদ্ধিমান সামরিক '
        'কৌশল খুঁজে পেয়েছিলেন — তীরন্দাজদের পাহাড়ের পেছন '
        'দিয়ে ঘেরাও — যা যুদ্ধের শুরুতে মুসলিমদের বিজয় সত্ত্বেও '
        'তাদের ওপর একটি বেদনাদায়ক আঘাত হানল। কিন্তু বছরের '
        'পর বছর তাঁর হৃদয় ধীরে ধীরে পরিবর্তিত হতে লাগল, যখন '
        'তিনি ইসলামের মুজিজা এবং সত্যের আলো তাঁর সামনে আরও '
        'স্পষ্ট হতে দেখলেন, শেষ পর্যন্ত তিনি তাঁর ইসলাম ঘোষণা '
        'করার সিদ্ধান্ত নিলেন, তিনি মদিনার দিকে গেলেন এবং নবী '
        'ﷺ-এর সামনে ইসলাম গ্রহণ করলেন যিনি তাঁকে বিশাল '
        'আনন্দে স্বাগত জানালেন এবং তাঁকে সেই দ্বীনের সেবায় '
        'একটি উজ্জ্বল ভবিষ্যতের সুসংবাদ দিলেন যার বিরুদ্ধে তিনি '
        'গতকালই যুদ্ধ করছিলেন। তাঁর ইসলাম গ্রহণের পর থেকে, '
        'খালিদ তাঁর সমস্ত বিশাল সামরিক অভিজ্ঞতা ইসলামের সেবায় '
        'নিয়োজিত করলেন, নবী ﷺ তাঁকে সিদ্ধান্তমূলক যুদ্ধের '
        'নেতৃত্ব দিলেন এবং তাঁকে চিরকালের জন্য একটি উপাধি '
        'দিলেন: "সাইফুল্লাহিল মাসলুল" (আল্লাহর কোষমুক্ত তরবারি), '
        'দ্বীন রক্ষায় তাঁর অসাধারণ সাহসিকতার সম্মানে। খালিদ তাঁর '
        'জীবনে একশটিরও বেশি যুদ্ধে অংশগ্রহণ করেছিলেন — তাঁর '
        'ইসলাম গ্রহণের আগে ও পরে উভয় সময়ে — এবং তিনি এর '
        'একটিতেও কখনো পরাজিত হননি, এটি সমগ্র মানব ইতিহাসে '
        'একটি বিরল সামরিক কৃতিত্ব। আর যুদ্ধক্ষেত্রে এই সমস্ত '
        'সাহসিকতা ও বীরত্ব সত্ত্বেও, খালিদ তিনি সবসময় যেমন '
        'আশা করতেন এবং বলতেন সেভাবে শহীদ হয়ে মারা যাননি, '
        'বরং তিনি তাঁর স্বাভাবিক অসুস্থতায় তাঁর শয্যায় মৃত্যুবরণ '
        'করলেন, তখন তিনি তাঁর মৃত্যুর আগে কেঁদে অনুশোচনার '
        'সাথে বললেন: "আমি এমন এমন যুদ্ধ প্রত্যক্ষ করেছি, আমার '
        'শরীরে এক বিঘতও জায়গা নেই যাতে তরবারির আঘাত বা '
        'বর্শার খোঁচা বা তীরের ক্ষত নেই, আর এখন দেখুন আমি '
        'গাধা যেভাবে মারা যায় সেভাবে আমার শয্যায় মারা যাচ্ছি, '
        'তাই কাপুরুষদের চোখ কখনো শান্তিতে ঘুমাবে না।"',
    source: 'নবী সীরাতের কিতাব',
  ),
  'companion-6': StoryTranslation(
    title: 'মুসআব ইবনে উমাইর ও তাঁর আত্মত্যাগ',
    body:
        'মুসআব ইবনে উমাইর তাঁর ইসলাম গ্রহণের আগে মক্কার '
        'সবচেয়ে আরামদায়ক জীবনযাপনকারী এবং সবচেয়ে সুন্দর '
        'পোশাক পরিহিত যুবকদের একজন ছিলেন, একটি ধনী পরিবারের '
        'পুত্র যারা তাঁকে আদর করত এবং জীবনের প্রতিটি বিলাসিতা '
        'সরবরাহ করত, এমনকি বলা হয় যে তাঁকে সুন্দর চেহারা ও '
        'পোশাকের সৌন্দর্যে দৃষ্টান্ত হিসেবে উদাহরণ দেওয়া হতো। '
        'যখন তিনি গোপনে ইসলাম গ্রহণ করলেন এবং তাঁর মা তাঁর '
        'ইসলাম গ্রহণের কথা জানলেন, তখন তিনি তাঁকে আটকে '
        'রাখলেন এবং তাঁর নতুন দ্বীন ত্যাগ করতে বাধ্য করার জন্য '
        'প্রতিটি উপায় ব্যবহার করলেন, কিন্তু তাঁর পরিবারের তীব্র '
        'চাপ সত্ত্বেও তিনি তাঁর ঈমান থেকে এক বিন্দুও সরলেন না, '
        'শেষ পর্যন্ত তাঁর মা তাঁকে ত্যাগ করলেন তাঁকে আগে দেওয়া '
        'সব সম্পদ থেকে বঞ্চিত করে, তখন মুসআব হঠাৎ বিলাসী '
        'জীবন থেকে চরম দারিদ্র্যের জীবনে চলে গেলেন, এমনকি '
        'তিনি এমন তালিমারা পুরনো পোশাক পরতে শুরু করলেন যা '
        'তাঁর শরীরও ঠিকমতো ঢাকত না। নবী ﷺ হিজরতের আগে '
        'তাঁকে মদিনায় পাঠালেন যাতে তিনি তার অধিবাসীদের কুরআন '
        'শেখান এবং তাদের ইসলামের দাওয়াত দেন; এভাবে তিনি '
        'ইসলামের ইতিহাসের প্রথম দূত হলেন এবং এত বড় সাফল্য '
        'অর্জন করলেন যে আউস ও খাজরাজের অনেক নেতা তাঁর হাতে '
        'ইসলাম গ্রহণ করলেন, এবং পরে নবী ﷺ-এর হিজরতের পথও '
        'প্রস্তুত করলেন। মুসআব উহুদ যুদ্ধে তাঁর হাতে মুসলিমদের '
        'পতাকা বহন করা অবস্থায় শহীদ হলেন, তাঁর সব শক্তি দিয়ে '
        'তা রক্ষা করছিলেন যতক্ষণ না তাঁর ডান হাত কেটে গেল তখন '
        'তিনি তা বাম হাতে ধরলেন, বাম হাতও কেটে গেল, তারপর '
        'তিনি তাঁর কাটা হাত দুটি দিয়ে পতাকা জড়িয়ে ধরলেন যতক্ষণ '
        'না শহীদ হলেন। যখন তারা তাঁকে কাফন দিতে এলো, তারা তাঁর '
        'জন্য যথেষ্ট কাপড় পেল না, যদি তারা তাঁর মাথা ঢাকে তবে '
        'তাঁর পা প্রকাশ পায়, আর যদি তাঁর পা ঢাকে তবে মাথা প্রকাশ '
        'পায়, তখন নবী ﷺ নির্দেশ দিলেন তাঁর মাথা ঢাকতে এবং তাঁর '
        'পায়ে কিছু ইজখির ঘাস রাখতে। নবী ﷺ তাঁর ওপর তীব্রভাবে '
        'কাঁদলেন মক্কায় মুসআবের ইসলাম গ্রহণের আগের সুন্দর '
        'পোশাক স্মরণ করে, তাঁর শাহাদাতের সময়ের অবস্থার সাথে '
        'তুলনা করে।',
    source: 'নবী সীরাতের কিতাব',
  ),
  'companion-7': StoryTranslation(
    title: 'ইসলামের প্রথম শহীদা সুমাইয়া',
    body:
        'সুমাইয়া বিনতে খাইয়াত এমন একজন নারী ছিলেন যাঁর '
        'রক্ষা করার মতো কোনো গোত্রের শক্তি ছিল না বা তাঁকে '
        'রক্ষা করার মতো কোনো সম্পদও ছিল না, তিনি আম্মার ইবনে '
        'ইয়াসিরের মা ছিলেন এবং মক্কায় ইসলামের সবচেয়ে '
        'বিপজ্জনক সময়ে ঈমান আনা প্রথম দিকের মানুষদের একজন '
        'ছিলেন। এই কারণেই, আবু জাহল ও কুরাইশের নেতারা তাঁর '
        'পরিবারকে — সুমাইয়া, তাঁর স্বামী ইয়াসির এবং তাঁদের পুত্র '
        'আম্মারকে — অন্যদের জন্য একটি কঠিন শিক্ষা করার জন্য '
        'বেছে নিল, কারণ অধিকাংশ প্রাথমিক মুসলিমদের যেমন তাদের '
        'গোত্রের সুরক্ষা ছিল তাঁদের তা ছিল না। তাঁদের দুপুরের সময় '
        'মক্কার জ্বলন্ত বালুতে বের করা হতো এবং তাঁদের দ্বীন থেকে '
        'ফিরিয়ে আনার চেষ্টায় টানা কয়েক দিন ভয়ংকরতম উপায়ে '
        'নির্যাতন করা হতো। নবী ﷺ এই বিপদে তাঁদের পাশ দিয়ে '
        'যেতেন, সেই প্রাথমিক পর্যায়ে তাঁদের সাহায্য করতে অক্ষম '
        'হয়ে, তখন তিনি তাঁদের সেই বাক্য দিয়ে সান্ত্বনা দিতেন যা '
        'ইতিহাস চিরস্থায়ী করেছে: "ধৈর্য ধরো, হে ইয়াসির পরিবার, '
        'নিশ্চয়ই তোমাদের প্রতিশ্রুতি জান্নাত।" সুমাইয়া তাঁর ঈমান '
        'এক বিন্দুও না নড়িয়ে অসহনীয় নির্যাতন সহ্য করলেন, শেষ '
        'পর্যন্ত আবু জাহল এই ধরনের নির্যাতনের মুখে তাঁর বিস্ময়কর '
        'দৃঢ়তায় বিরক্ত হলো, তখন সে তাঁকে একটি মারাত্মক জায়গায় '
        'বর্শা দিয়ে আঘাত করল, তখন তিনি তৎক্ষণাৎ শহীদ হয়ে পড়ে '
        'গেলেন। এভাবে সুমাইয়া সমগ্র ইসলামের ইতিহাসের প্রথম '
        'শহীদা হলেন, দুনিয়ার চোখে একজন দুর্বল নারী, যাঁর কোনো '
        'মর্যাদা বা ক্ষমতা ছিল না, কিন্তু তাঁর ঈমান তাঁর জল্লাদদের '
        'সব অস্ত্রের চেয়ে শক্তিশালী ছিল।',
    source: 'নবী সীরাতের কিতাব',
  ),
  'companion-8': StoryTranslation(
    title: 'সালমান আল-ফারিসি ও সত্যের সন্ধানে যাত্রা',
    body:
        'সালমান মূলত একটি ধনী পরিবারের ফার্সি ছিলেন, তিনি '
        'অগ্নিপূজায় বড় হয়েছিলেন, কিন্তু তিনি এতে সন্তুষ্ট হননি, '
        'তিনি গোপনে সত্য দ্বীন খুঁজতে শুরু করলেন শেষ পর্যন্ত '
        'তিনি খ্রিস্টান পাদ্রিদের সাথে পরিচিত হলেন, তিনি তাঁর '
        'পরিবার ও সম্পদ ত্যাগ করলেন এবং সম্পূর্ণ হিদায়াতের '
        'খোঁজে একজন থেকে অন্য পাদ্রির কাছে ভ্রমণ করতে লাগলেন '
        'যখনই তাদের একজন মারা যেতেন তখন আরও সত্যবাদী ও '
        'জ্ঞানী একজনের কাছে যেতেন। তাঁর সাথে থাকা শেষ পাদ্রি '
        'মারা যাওয়ার আগে আরবের ভূমিতে শীঘ্রই আবির্ভূত হতে '
        'যাওয়া একজন নবীর নিদর্শন সম্পর্কে অসিয়ত করলেন: তিনি '
        'দুটি কালো পাথুরে ভূমির মধ্যবর্তী — একটি আগ্নেয় ভূমিতে '
        '— খেজুর গাছে ভরা একটি স্থানে হিজরত করবেন, তিনি '
        'উপহার গ্রহণ করবেন কিন্তু সদকা খাবেন না, তাঁর দুই কাঁধের '
        'মাঝখানে নবুওয়তের মোহর থাকবে। সালমান এই ভূমি খুঁজতে '
        'যাত্রা করলেন, কিন্তু পথে কিছু বেদুইন তাঁকে প্রতারণা করে '
        'দাস হিসেবে বিক্রি করে দিল, শেষ পর্যন্ত তাঁর পরিণতি হলো '
        'মদিনা আল-মুনাওয়ারাতেই দাসত্ব — সেই ভূমি যা তিনি খুঁজছিলেন '
        'না জেনে যে তিনি ইতিমধ্যে সেখানে পৌঁছে গেছেন। যখন '
        'নবী ﷺ মদিনায় হিজরত করলেন, সালমান তিনটি নিদর্শনই '
        'পরীক্ষা করলেন এবং তা তাঁর চোখের সামনে একে একে সত্য '
        'প্রমাণিত হলো, তখন তিনি তৎক্ষণাৎ ইসলামে প্রবেশ করতে '
        'চাইলেন, কিন্তু তিনি তখনও দাস ছিলেন, তখন নবী ﷺ ও তাঁর '
        'সাহাবিরা তাঁকে মুক্ত হতে সাহায্য করলেন, তাঁরা তাঁর মালিকের '
        'সাথে চুক্তি করলেন যে তাঁর স্বাধীনতার বিনিময়ে অনেক '
        'খেজুর গাছ রোপণ করবেন, তাঁরা তা করলেন এবং সালমান '
        'মুক্ত হলেন, তিনি নবী ﷺ-এর হৃদয়ে সবচেয়ে প্রিয় সাহাবিদের '
        'একজন হলেন; পরবর্তীতে খন্দক যুদ্ধে মদিনা রক্ষা করা '
        'পরিকল্পনাটিও তাঁরই ছিল।',
    source: 'নবী সীরাতের কিতাব',
  ),
  'companion-9': StoryTranslation(
    title: 'ওহীর সূচনায় খাদিজা রাদিয়াল্লাহু আনহা',
    body:
        'খুওয়াইলিদের কন্যা খাদিজা মক্কার একজন সম্মানিত ব্যবসায়ী '
        'ছিলেন, নবুওয়তের আগে মুহাম্মদ ﷺ যখন তাঁর ব্যবসা '
        'পরিচালনা করতেন তখন তাঁর সততা ও বিশ্বস্ততায় তিনি মুগ্ধ '
        'হয়েছিলেন, তখন তিনি তাঁকে বিয়ে করলেন। যখন প্রথমবার '
        'তাঁর কাছে হেরা গুহায় ওহী নাজিল হলো, এবং জিবরাইল তাঁকে '
        'শক্তভাবে জড়িয়ে ধরলেন এবং নির্দেশ দিলেন: "পড়ো," তখন '
        'নবী ﷺ এই অভিজ্ঞতার ভয়াবহতায় তীব্রভাবে ভীত হলেন, '
        'কাঁপতে কাঁপতে তিনি তাঁর ঘরে ফিরলেন বলতে বলতে: "আমাকে '
        'চাদর দাও, আমাকে চাদর দাও," তিনি যা দেখেছিলেন তার '
        'জন্য নিজের প্রাণ নিয়ে ভীত ছিলেন। খাদিজা তাঁকে আশ্বস্ত '
        'করতে একমুহূর্তও দ্বিধা করলেন না, বরং তিনি তাঁকে সেই '
        'কথাগুলো বললেন যা সীরাতের কিতাব চিরস্থায়ী করেছে: '
        '"কখনো না, আল্লাহর কসম, আল্লাহ আপনাকে কখনো '
        'অপমানিত করবেন না, নিশ্চয়ই আপনি আত্মীয়তার সম্পর্ক '
        'রক্ষা করেন, দুর্বলদের বোঝা বহন করেন, নিঃস্বদের উপার্জন '
        'করে দেন, অতিথিকে আপ্যায়ন করেন এবং সত্যের বিপদে '
        'সাহায্য করেন।" তারপর তিনি তৎক্ষণাৎ তাঁকে তাঁর চাচাতো '
        'ভাই ওয়ারাকা ইবনে নাওফালের কাছে নিয়ে গেলেন, যিনি '
        'খ্রিস্টধর্মের একজন বৃদ্ধ পণ্ডিত ছিলেন এবং পূর্ববর্তী কিতাব '
        'সম্পর্কে জানতেন, তখন ওয়ারাকা তাঁকে জানালেন যে তাঁর '
        'কাছে যা এসেছে তা সেই মহান ফেরেশতা যা মূসা আলাইহিস '
        'সালামের কাছে আসত, আর তিনি এই উম্মতের নবী, তিনি '
        'তাঁকে সতর্ক করলেন যে তাঁর দাওয়াত প্রকাশ্যে ঘোষণা '
        'করলে তাঁর সম্প্রদায়ের শত্রুতার মুখোমুখি হবেন। খাদিজা '
        'একেবারে প্রথম মানুষ ছিলেন যিনি ইসলামে ঈমান এনেছিলেন, '
        'তিনি অবরোধ ও বয়কটের সবচেয়ে কঠিন বছরগুলোতে '
        'দাওয়াতের সাহায্যে তাঁর সমস্ত সম্পদ ব্যয় করেছিলেন, নবী '
        'ﷺ তাঁর আনুগত্য কখনো ভোলেননি, এমনকি তাঁর মৃত্যুর '
        'বহু বছর পরও, যখনই তিনি তাঁর বোনকে দেখতেন তখনই '
        'তাঁকে ভালোবাসার সাথে স্মরণ করতেন এবং তাঁকে চেনা '
        'সবাইকে সম্মান করতেন।',
    source: 'সহীহ বুখারী ও মুসলিম — নবী সীরাতের কিতাব',
  ),
  'companion-10': StoryTranslation(
    title:
        'জায়েদ ইবনে হারিসা নবী ﷺ-কে তাঁর পিতার ওপর অগ্রাধিকার '
        'দেন',
    body:
        'জায়েদ ইবনে হারিসাকে শৈশবে একটি আক্রমণে বন্দী করা '
        'হয়েছিল এবং দাস হিসেবে বিক্রি করা হয়েছিল শেষ পর্যন্ত '
        'তাঁর বিষয়টি খাদিজা রাদিয়াল্লাহু আনহার কাছে পৌঁছাল, তিনি '
        'পরে নবুওয়তের আগে নবী ﷺ-কে উপহার দিলেন, তখন তিনি '
        'তাঁকে মুক্ত করে দত্তক নিলেন এবং তাঁর নিজের পুত্রের মতো '
        'আচরণ করলেন। বহু বছর পর, জায়েদের পিতা ও চাচা একটি '
        'ক্লান্তিকর অনুসন্ধানের পর অবশেষে মক্কায় পৌঁছাতে সক্ষম '
        'হলেন, তাঁরা তাঁকে ফিরিয়ে নিতে একটি বড় মুক্তিপণ নিয়ে '
        'এলেন, আশা করে যে তিনি তৎক্ষণাৎ তাঁর প্রকৃত পরিবার ও '
        'তাঁর হারানো স্বাধীনতায় ফিরে আসবেন। কিন্তু নবী ﷺ, তাঁর '
        'মহৎ চরিত্রের সাথে, তাঁর পিতাকে বললেন: "তাকে ডাকুন এবং '
        'তাকে পছন্দ করার সুযোগ দিন, যদি সে আপনাকে বেছে নেয় '
        'তবে সে মুক্তিপণ ছাড়াই আপনার, আর যদি সে আমাকে বেছে '
        'নেয় তবে আল্লাহর কসম, আমি এমন নই যে যে আমাকে বেছে '
        'নিয়েছে তার ওপর কাউকে বেছে নেব।" তাঁরা জায়েদকে একত্র '
        'করলেন এবং তাঁকে একদিকে তাঁর পিতা ও চাচার মধ্যে, আর '
        'অন্যদিকে নবী ﷺ-এর সাথে থাকার মধ্যে পছন্দ করার সুযোগ '
        'দিলেন, কেউ সন্দেহ করেনি যে তিনি তাঁর পরিবার ও স্বাধীনতা '
        'বেছে নেবেন, কিন্তু জায়েদ সবাইকে অবাক করে বললেন: "আমি '
        'আপনার ওপর কাউকে বেছে নেব না, আপনি আমার জন্য পিতা '
        'ও চাচা উভয়ের স্থানে।" তাঁর পিতা হতবাক হলেন এবং বুঝতে '
        'চেষ্টা করলেন কীভাবে তাঁর পুত্র দাসত্বকে স্বাধীনতা ও পরিবারের '
        'ওপর অগ্রাধিকার দিচ্ছেন, তখন জায়েদ ব্যাখ্যা করলেন যে '
        'তিনি এই মানুষটির মধ্যে এমন কিছু দেখেছেন যা তাঁকে পূর্ণ '
        'ইচ্ছায় এই পছন্দ করতে পরিচালিত করেছে। নবী ﷺ এই গভীর '
        'আনুগত্যে অত্যন্ত অভিভূত হলেন, তিনি তৎক্ষণাৎ তাঁকে কাবায় '
        'নিয়ে গেলেন এবং জনসাধারণের সামনে ঘোষণা করলেন: '
        '"সাক্ষী থাকো যে জায়েদ আমার পুত্র, সে আমার উত্তরাধিকারী '
        'হবে এবং আমি তার উত্তরাধিকারী হব," তখন তাঁকে জায়েদ '
        'ইবনে মুহাম্মদ বলে ডাকা শুরু হলো শেষ পর্যন্ত পরে কুরআন '
        'নাজিল হলো যা দত্তক গ্রহণের ধারণা সংশোধন করল, তখন '
        'তাঁর নাম আবার জায়েদ ইবনে হারিসা হলো, কিন্তু নবী '
        'ﷺ-এর হৃদয়ে তাঁর মর্যাদা একই রইল, আর তিনিই একমাত্র '
        'সাহাবি যাঁর নাম সরাসরি মহিমান্বিত কুরআনে উল্লেখ করা '
        'হয়েছে।',
    source: 'নবী সীরাতের কিতাব — সূরা আল-আহযাব: ৪-৫ ও ৩৭',
  ),

  // ===== যুদ্ধসমূহ =====
  'battle-1': StoryTranslation(
    title: 'মহান বদর যুদ্ধ',
    body:
        'এটি ছিল মুসলিম ও কুরাইশের মধ্যে প্রথম বড় সামরিক '
        'সংঘাত, এর ঘটনাবলি শুরু হলো যখন নবী ﷺ আবু সুফিয়ানের '
        'নেতৃত্বে শাম থেকে ফিরে আসা কুরাইশের একটি বাণিজ্য '
        'কাফেলা আটকাতে বের হলেন, কিন্তু আবু সুফিয়ান এটি জানল '
        'এবং তার কাফেলার পথ পরিবর্তন করে তা বাঁচাল, একই '
        'সাথে কুরাইশের কাছে জরুরি সাহায্যের অনুরোধ করে একজন '
        'দূত পাঠাল। কুরাইশ এক হাজারেরও বেশি সৈন্যের একটি '
        'পুরোপুরি সজ্জিত বাহিনী নিয়ে বের হলো, অথচ নবী ﷺ-এর '
        'সাথে ছিল কেবল তিনশত তেরো জন, তাদের অধিকাংশের '
        'কোনো বর্ম বা পর্যাপ্ত ঘোড়া ছিল না, তারা তাদের কাছে '
        'থাকা কয়েকটি উটে পালাক্রমে চড়ছিল। যখন দুই বাহিনী '
        'বদরের কূপগুলোর কাছে কাছাকাছি এলো, নবী ﷺ তাঁর তাঁবুতে '
        'প্রবেশ করে তাঁর রবের কাছে তীব্র প্রার্থনায় দোয়া করলেন '
        'তাঁর দুই হাত এত ওপরে তুলে যে তাঁর চাদর তাঁর কাঁধ থেকে '
        'পড়ে গেল, তিনি বললেন: "হে আল্লাহ, আপনি যদি এই দলটিকে '
        'ধ্বংস করেন, তবে পৃথিবীতে আপনার ইবাদত করা হবে না।" '
        'তখন আবু বকর আস-সিদ্দিক তাঁকে আশ্বস্ত করলেন: "হে '
        'আল্লাহর রাসূল, আপনার রবের কাছে আপনার আকুতি যথেষ্ট, '
        'নিশ্চয়ই তিনি আপনাকে দেওয়া প্রতিশ্রুতি পূরণ করবেন।" '
        'আল্লাহ তাঁর দোয়া কবুল করলেন, তিনি মুমিনদের সাথে যুদ্ধ '
        'করতে এবং তাদের পা দৃঢ় করতে ফেরেশতাদের নাজিল '
        'করলেন, তখন যুদ্ধ সংঘটিত হলো এবং মুসলিমরা তাদের '
        'সংখ্যা ও অস্ত্রের স্বল্পতা সত্ত্বেও একটি নিরঙ্কুশ বিজয় অর্জন '
        'করল; মক্কায় মুসলিমদের নির্যাতনকারী কুরাইশের নেতাদের '
        'মধ্যে সত্তর জন নিহত হলো, তাদের মধ্যে আবু জাহলও ছিল, '
        'আরও সত্তর জনকে বন্দী করা হলো। এই দিনকে ফুরকানের '
        'দিন বলা হয়েছে কারণ এটি সত্য ও মিথ্যার মধ্যে খুব স্পষ্টভাবে '
        'পার্থক্য করেছে এবং মদিনায় উদীয়মান ইসলামি রাষ্ট্রের পা '
        'সেই যুগের সবচেয়ে বড় আরব শক্তির সামনে দৃঢ় করেছে।',
    source: 'সূরা আল-আনফাল — নবী সীরাতের কিতাব',
  ),
  'battle-2': StoryTranslation(
    title: 'উহুদ যুদ্ধ',
    body:
        'বদরে তাদের লজ্জাজনক পরাজয়ের পর, কুরাইশ তাদের শক্তি '
        'জড়ো করল এবং প্রতিশোধ নিতে তিন হাজার সৈন্যের বাহিনী '
        'নিয়ে বের হলো, নবী ﷺ তাঁর এক হাজার সাহাবি নিয়ে '
        'উহুদ পাহাড়ের কাছে তাদের মুখোমুখি হতে বের হলেন, কিন্তু '
        'মুনাফিকদের নেতা আবদুল্লাহ ইবনে উবাই তাঁর মতামত গৃহীত '
        'না হওয়ায় রাগান্বিত হয়ে অর্ধেক পথে বাহিনীর এক-তৃতীয়াংশ '
        'নিয়ে ফিরে গেল, তখন নবী ﷺ-এর সাথে কেবল সাতশত '
        'যোদ্ধা রইল। নবী ﷺ একটি সতর্ক পরিকল্পনা করলেন, তিনি '
        'পঞ্চাশ জন দক্ষ তীরন্দাজকে বাহিনীর পেছনের একটি ছোট '
        'পাহাড়ে উঠতে নির্দেশ দিলেন এবং তাদের এমন একটি চূড়ান্ত '
        'নির্দেশ দিলেন যাতে কোনো ইজতিহাদের অবকাশ নেই: '
        '"তোমরা যা-ই দেখো না কেন তোমাদের স্থান ত্যাগ করো না, '
        'আমরা জিতি বা হারি, যতক্ষণ না আমি তোমাদের কাছে খবর '
        'পাঠাই।" যুদ্ধ শুরু হলো এবং কুরাইশের সারি মুসলিমদের '
        'আক্রমণে ভেঙে গেল, তারা পিছু ফিরে পালাল, তখন তীরন্দাজরা '
        'মনে করল যুদ্ধ একটি চূড়ান্ত বিজয়ে শেষ হয়ে গেছে, তখন '
        'তারা তাদের সেনাপতি আবদুল্লাহ ইবনে জুবাইরের সতর্কতা '
        'সত্ত্বেও গনিমত সংগ্রহের প্রতিযোগিতায় পাহাড় থেকে নেমে '
        'এলো, যিনি তাদের নবী ﷺ-এর অসিয়ত স্মরণ করিয়ে দিয়েছিলেন '
        'কিন্তু কেবল কয়েকজনই তাঁর কথা শুনল। খালিদ ইবনে '
        'ওয়ালিদ — এবং তখনো তিনি মুশরিক ছিলেন কুরাইশের '
        'সারিতে যুদ্ধ করছিলেন — এই হঠাৎ খোলা ফাঁকটির সুযোগ '
        'নিলেন, তিনি তাঁর অশ্বারোহী বাহিনী নিয়ে পাহাড়ের পেছন '
        'দিয়ে ঘুরে মুসলিমদের ওপর পেছন থেকে আকস্মিক আক্রমণ '
        'করলেন যখন তারা গনিমত নিয়ে ব্যস্ত ছিল, তখন যুদ্ধের '
        'ভারসাম্য হঠাৎ পরিবর্তিত হলো, সারিগুলো বিশৃঙ্খল হলো, '
        'নবী ﷺ নিজেই তাঁর পবিত্র মুখে আহত হলেন এবং তাঁর '
        'সামনের দাঁত ভেঙে গেল, সবচেয়ে ভালো সাহাবিদের মধ্যে '
        'সত্তর জন শহীদ হলেন তাদের মধ্যে তাঁর চাচা আল্লাহর সিংহ '
        'হামজাও ছিলেন। এই যুদ্ধ প্রতীয়মান বিজয়ের মুহূর্তেও '
        'নেতৃত্বের নির্দেশ লঙ্ঘনের বিপদ সম্পর্কে একটি বড় ও গভীর '
        'শিক্ষা হলো, এই বিষয়ে কুরআন নাজিল হলো যা নির্দেশ '
        'লঙ্ঘনকারীদের তিরস্কার করে এবং মুমিনদের হৃদয় দৃঢ় করে।',
    source: 'সূরা আলে ইমরান: ১২১-১৭৫ — নবী সীরাতের কিতাব',
  ),
  'battle-3': StoryTranslation(
    title: 'খন্দক যুদ্ধ',
    body:
        'এই যুদ্ধে সেই সময় পর্যন্ত মুসলিমদের বিরুদ্ধে জড়ো হওয়া '
        'সবচেয়ে বড় শক্তি একত্রিত হলো, কারণ কুরাইশ ও গাতাফান '
        'গোত্র বনু নাদির ইহুদিদের সাথে যুক্ত হলো যারা মদিনা থেকে '
        'বহিষ্কারের পর এই জোটকে উস্কে দিয়েছিল, আক্রমণকারী '
        'দলগুলোর সংখ্যা দশ হাজার যোদ্ধায় পৌঁছাল যারা মুসলিমদের '
        'সম্পূর্ণভাবে ধ্বংস করতে এবং তাদের উদীয়মান রাষ্ট্রকে '
        'মূল থেকে উপড়ে ফেলতে চেয়েছিল। নবী ﷺ যখন আসন্ন '
        'বিপদের বিশালতা জানলেন, তিনি মদিনা রক্ষার উপায় নিয়ে '
        'তাঁর সাহাবিদের সাথে পরামর্শ করলেন, তখন সালমান আল-'
        'ফারিসি — যিনি ইতিমধ্যে ফারস ভূমিতে এই প্রতিরক্ষা পদ্ধতি '
        'জানতেন এবং আরবদের কাছে আগে অপরিচিত ছিল — মদিনার '
        'উন্মুক্ত অংশের চারপাশে একটি গভীর ও প্রশস্ত পরিখা খনন '
        'করার প্রস্তাব দিলেন যেখান দিয়ে শত্রু সহজে আক্রমণ করতে '
        'পারত। নবী ﷺ এই ধারণাটি পছন্দ করলেন, তখন সমস্ত '
        'মুসলিম দিন-রাত অক্লান্তভাবে পরিখা খনন করতে লাগল, নবী '
        'ﷺ নিজেও তাঁর পবিত্র হাত দিয়ে তাদের সাথে মাটি বহন '
        'করে এবং তীব্র শীত ও তীক্ষ্ণ ক্ষুধা তাদের সাথে ভাগ করে '
        'কাজ করলেন, শেষ পর্যন্ত তারা এই বিশাল কাজ কয়েক দিনের '
        'মধ্যেই সম্পন্ন করল যদিও এটি বিশাল ছিল। যখন দলগুলো '
        'পৌঁছাল এবং মদিনা ঘিরে একটি পরিখা দেখল, তারা অত্যন্ত '
        'বিস্মিত হলো, কারণ তারা এর আগে তাদের যুদ্ধে এই পদ্ধতি '
        'কখনো দেখেনি, তারা সরাসরি আক্রমণে অভ্যস্ত তাদের ঘোড়া '
        'নিয়ে তা অতিক্রম করতে পারল না, তারা মদিনাকে দূর থেকে '
        'দীর্ঘ দিন অবরোধ করে রাখল যাতে ভেতরে অবরুদ্ধ মুসলিমদের '
        'ওপর শীত ও ক্ষুধা তীব্র হয়ে উঠল। অবরোধের চূড়ান্ত পর্যায়ে, '
        'আল্লাহ দলগুলোর ওপর একটি অন্ধকার রাতে তীব্র ঠান্ডা '
        'বাতাস পাঠালেন যা তাদের তাঁবু উপড়ে ফেলল, তাদের আগুন '
        'নিভিয়ে দিল এবং তাদের পাত্র উল্টে দিল, তখন কোনো স্পষ্ট '
        'কারণ ছাড়াই তাদের হৃদয়ে ভয় ছড়িয়ে পড়ল, তখন তাদের '
        'নেতা আবু সুফিয়ান রাতেই তার পুরো বাহিনী নিয়ে কোনো '
        'উল্লেখযোগ্য যুদ্ধ ছাড়াই পিছু হটার সিদ্ধান্ত নিল; এভাবে '
        'অবরোধ ভেঙে গেল এবং যুদ্ধ আল্লাহর মুসলিমদের তাদের '
        'সম্মুখীন হওয়া সবচেয়ে বড় বিপদ থেকে রক্ষার মাধ্যমে শেষ '
        'হলো।',
    source: 'সূরা আল-আহযাব: ৯-২৭ — নবী সীরাতের কিতাব',
  ),
  'battle-4': StoryTranslation(
    title: 'হুদাইবিয়ার সন্ধি',
    body:
        'নবী ﷺ চৌদ্দশতাধিক সাহাবি নিয়ে কেবল উমরাহ পালনের '
        'জন্য মক্কার দিকে বের হলেন, তারা সাধারণ ভ্রমণকারীর '
        'তরবারি ছাড়া কোনো যুদ্ধাস্ত্র বহন করছিল না এবং তাদের '
        'উদ্দেশ্যের নিরাপত্তার একটি স্পষ্ট ঘোষণা হিসেবে ইহরামের '
        'পোশাকে ছিল। কিন্তু কুরাইশ আরবদের সামনে তার মর্যাদা '
        'হারানোর ভয়ে তাদের মক্কায় প্রবেশের অনুমতি দিতে অস্বীকার '
        'করল, তখন নবী ﷺ মক্কার কাছে হুদাইবিয়া নামক এলাকায় '
        'থামলেন, আর আলোচনা ও দূত বিনিময়ের পর, একটি সন্ধি '
        'হলো যার শর্তাবলি দুই পক্ষের মধ্যে যুদ্ধ ছাড়াই পুরো দশ '
        'বছর ধরে চলবে, এই শর্তে যে মুসলিমরা এই বছর উমরাহ '
        'ছাড়াই ফিরে যাবে এবং পরের বছর এসে কেবল তিন দিন '
        'উমরাহ করবে। সন্ধির শর্তাবলি বাহ্যত মুসলিমদের জন্য '
        'ক্ষতিকর মনে হলো, এমনকি কিছু বড় সাহাবি এই শর্তাবলিতে '
        'রাগান্বিত হলেন, উমর ইবনুল খাত্তাব নবী ﷺ-কে তীব্রভাবে '
        'আপত্তি জানিয়ে বললেন: "আমরা কি সত্যের ওপর নই আর '
        'তারা কি মিথ্যার ওপর নয়? তাহলে কেন আমরা আমাদের '
        'দ্বীনে দুর্বলতা দেখাব?" তখন নবী ﷺ পূর্ণ বিশ্বাসের সাথে '
        'উত্তর দিলেন: "আমি আল্লাহর রাসূল এবং তিনি আমাকে '
        'কখনো নষ্ট করবেন না।" আর সন্ধির সবচেয়ে বিস্ময়কর শর্ত '
        'ছিল কুরাইশের মধ্য থেকে যে কেউ মুসলিম হয়ে মুসলিমদের '
        'কাছে আসবে তাকে ফেরত পাঠানো হবে, অথচ মুসলিমদের '
        'মধ্য থেকে যে তাদের কাছে ফিরে যাবে তাকে ফেরত দেওয়া '
        'হবে না, এটি বাহ্যত সম্পূর্ণ অন্যায্য একটি শর্ত ছিল। কিন্তু '
        'আল্লাহ কুরআনে এই সন্ধিকে "স্পষ্ট বিজয়" বলে অভিহিত '
        'করেছেন, কারণ পরবর্তীতে সত্যটি স্পষ্টভাবে প্রকাশ পেয়েছিল: '
        'দুই পক্ষের মধ্যে যুদ্ধ বন্ধ হওয়া মানুষের নির্ভয়ে একে অপরের '
        'সাথে মেলামেশার জন্য একটি প্রশস্ত দরজা খুলে দিল, এমনকি '
        'পরবর্তী মাত্র দুই বছরে দাওয়াতের শুরু থেকে পূর্ববর্তী পুরো '
        'উনিশ বছরে যারা ইসলাম গ্রহণ করেছিল তার চেয়ে বহুগুণ '
        'বেশি মানুষ ইসলাম গ্রহণ করল।',
    source: 'সূরা আল-ফাতহ — নবী সীরাতের কিতাব',
  ),
  'battle-5': StoryTranslation(
    title: 'মক্কা বিজয়',
    body:
        'কুরাইশ হুদাইবিয়ার সন্ধি ভঙ্গ করল যখন তারা তাদের '
        'মিত্রদের মুসলিমদের মিত্রদের ওপর আক্রমণে সাহায্য '
        'করেছিল, তখন নবী ﷺ সেই সময় পর্যন্ত মুসলিমদের জন্য '
        'জড়ো হওয়া সবচেয়ে বড় দশ হাজার যোদ্ধার বাহিনী নিয়ে '
        'তাদের দিকে বের হলেন, সেই শহরের দিকে যাত্রা করলেন '
        'যা মাত্র আট বছর আগে তাঁকে অন্যায়ভাবে বহিষ্কার করেছিল। '
        'নবী ﷺ বাহিনীর গন্তব্য তাঁর অনেক সাহাবির কাছ থেকেও '
        'গোপন রাখলেন আকস্মিকতার উপাদান রক্ষার জন্য, তিনি '
        'কুরাইশ কোনো উল্লেখযোগ্য প্রতিরোধ সংগঠিত করতে না '
        'পারার মধ্যেই মক্কায় প্রবেশ করলেন এবং তাঁর সেনাপতিদের '
        'নির্দেশ দিলেন কেবল তাদের সাথেই যুদ্ধ করতে যারা তাদের '
        'সাথে যুদ্ধ করবে। আর যখন নবী ﷺ অবশেষে কাবার দরজায় '
        'দাঁড়ালেন, আর কুরাইশের মানুষ বছরের পর বছর ধরে তাঁর '
        'ও তাঁর সাহাবিদের ওপর তারা যা নির্যাতন, বহিষ্কার, অবরোধ '
        'ও যুদ্ধের মাধ্যমে করেছিল তার পর তীব্র ভয়ে তাদের '
        'পরিণতির অপেক্ষা করছিল, সবাই মুসলিমদের ওপর হওয়া '
        'ক্ষতির বিশালতার সাথে সামঞ্জস্যপূর্ণ কঠোর প্রতিশোধের '
        'আশা করছিল। কিন্তু নবী ﷺ সবাইকে সমগ্র মানব ইতিহাসের '
        'সবচেয়ে বড় ক্ষমার দৃষ্টান্তগুলোর একটি দিয়ে অবাক করে '
        'দিলেন, তিনি শান্তভাবে তাদের জিজ্ঞেস করলেন: "হে কুরাইশ '
        'সম্প্রদায়, তোমরা কি মনে করো আমি তোমাদের সাথে কী '
        'করব?" তখন তারা সবকিছু সত্ত্বেও এখনো তাঁর উদারতা '
        'জেনে উত্তর দিল: "মঙ্গল, একজন মহান ভাই ও মহান ভাইয়ের '
        'পুত্র।" তখন তিনি তাদের সেই চিরন্তন বাক্য বললেন: "যাও, '
        'তোমরা সবাই মুক্ত।" তিনি পূর্ণ ক্ষমতা থাকা সত্ত্বেও কারো '
        'কাছ থেকে প্রতিশোধ না নিয়ে তাঁকে কষ্ট দেওয়া, তাঁর '
        'সাহাবিদের নির্যাতন করা, পূর্ববর্তী যুদ্ধগুলোতে তাঁর সাথে '
        'যুদ্ধ করা এবং তাঁর কিছু আত্মীয়কে হত্যা করা সবাইকে ক্ষমা '
        'করলেন। এই বিশাল ক্ষমা বিজয়ের অল্প সময় পরেই সমগ্র '
        'মক্কাবাসীর ইসলাম গ্রহণের সরাসরি কারণ হলো, কারণ তারা '
        'এই দ্বীনের শিক্ষা শোনার আগেই তার নৈতিকতা নিজের '
        'চোখে দেখেছিল।',
    source: 'নবী সীরাতের কিতাব',
  ),
  'battle-6': StoryTranslation(
    title: 'বীরে মাউনা অভিযান — কুররাদের বিয়োগান্তক কাহিনি',
    body:
        'নাজদের একটি গোত্রের নেতা আবু বারা আমির ইবনে মালিক '
        'নামে একজন ব্যক্তি নবী ﷺ-এর কাছে এলেন, তিনি তাঁকে '
        'প্রস্তাব দিলেন তাঁর সাথে কিছু সাহাবিকে পাঠাতে যাতে তারা '
        'তাঁর সম্প্রদায়কে কুরআন ও ইসলাম শেখাতে পারেন, এবং তিনি '
        'পথে ব্যক্তিগতভাবে তাঁদের রক্ষার প্রতিশ্রুতি দিলেন। নবী ﷺ '
        'এই মিশনের জন্য তাঁর সবচেয়ে ভালো সাহাবিদের মধ্যে '
        'সত্তর জন বেছে নিলেন, যারা কুররা নামে পরিচিত ছিল তাদের '
        'কুরআন মুখস্থ ও রাতের ইবাদতের প্রাচুর্যের কারণে, তাদের '
        'কেউ কেউ দিনে কাজ করে জীবিকা উপার্জন করতেন তারপর '
        'তা সদকা করে দিতেন এবং তাঁদের রাত কুরআন পাঠ ও তা '
        'নিয়ে অধ্যয়নে কাটাতেন, এমনকি তাঁদের আহলুস সুফফা বলা '
        'হতো জ্ঞান ও ইবাদতের জন্য নবী ﷺ-এর মসজিদে তাঁদের '
        'ধারাবাহিক অবস্থানের কারণে। এই সত্তর জন কোনো যুদ্ধের '
        'উদ্দেশ্য ছাড়াই একটি সম্পূর্ণ শান্তিপূর্ণ মিশনে বের হলেন '
        'এবং যাত্রা করে মাউনা নামক একটি কূপের কাছে অবস্থান '
        'নিলেন। তাঁরা তাঁদের একজনকে নবী ﷺ-এর চিঠি নিয়ে '
        'আমির ইবনে তুফাইলের কাছে — সেই এলাকার অন্য একটি '
        'গোত্রের নেতা — পাঠালেন, কিন্তু এই বিশ্বাসঘাতক ব্যক্তি '
        'চিঠিটি না পড়েই দূতকে হত্যা করল, তারপর নাজদের গোত্রগুলোকে '
        'বাকি কুররাদের ওপর বিশ্বাসঘাতকতার সাথে আক্রমণ করতে '
        'উস্কে দিল যখন তারা নিরাপদ ছিল কোনো বিশ্বাসঘাতকতার '
        'আশা করছিল না, যদিও আবু বারা তাঁদের রক্ষার প্রতিশ্রুতি '
        'দিয়েছিলেন। বিশ্বাসঘাতক গোত্রগুলো কুররাদের প্রতিটি দিক '
        'থেকে ঘিরে ফেলল এবং সম্পূর্ণ অসাবধানতায় তাঁদের ওপর '
        'হঠাৎ আক্রমণ করল, তখন সাহাবিরা এই আকস্মিকতা ও এই '
        'বিশাল সংখ্যার মুখে তাঁদের অল্প সংখ্যা সত্ত্বেও একটি '
        'বিরল সাহসিকতার সাথে যুদ্ধ করলেন, শেষ পর্যন্ত তাঁরা '
        'প্রায় সবাই শহীদ হলেন কেবল এক বা দুইজন ব্যতীত যারা '
        'অলৌকিকভাবে বেঁচে গিয়েছিলেন যাতে তাঁরা যা ঘটেছিল '
        'তা নবী ﷺ-কে জানাতে পারেন। নবী ﷺ এই বিয়োগান্তক '
        'ঘটনায় তীব্র দুঃখ পেলেন যা তিনি তাঁর জীবনে অন্য কোনো '
        'বিপদে কখনো এতটা দুঃখিত হননি, এমনকি তিনি একটি পূর্ণ '
        'মাস ধরে তাঁর নামাজে কুনুত পড়লেন সেই বিশ্বাসঘাতক '
        'গোত্রগুলোর বিরুদ্ধে বদদোয়া করে যারা তাঁর সাহাবিদের '
        'হত্যা করেছিল যখন তাঁরা মানুষকে মঙ্গল শেখানোর একটি '
        'শান্তিপূর্ণ মিশনে ছিলেন। আর এই ঘটনা সীরাতে বিশ্বাসঘাতকতা '
        'ও প্রতিশ্রুতি ভঙ্গের বিপদ সম্পর্কে সবচেয়ে বেদনাদায়ক '
        'শিক্ষাগুলোর একটি হিসেবে রয়ে গেছে, আর এই দ্বীন প্রচারে '
        'কুরআনের প্রথম বাহকরা যে ভারী মূল্য দিয়েছিলেন তার '
        'সম্পর্কেও।',
    source: 'সহীহ বুখারী ও মুসলিম — নবী সীরাতের কিতাব',
  ),
  'battle-7': StoryTranslation(
    title: 'মুতা যুদ্ধ',
    body:
        'নবী ﷺ শামে বুসরার শাসকের কাছে তাকে ইসলামের '
        'দাওয়াত দিয়ে একটি চিঠি নিয়ে একজন দূত পাঠালেন, কিন্তু '
        'রোমানদের একজন বিশ্বস্ত আমির দূতকে হত্যা করল, আর '
        'দূত হত্যা করা ছিল আরবদের কাছে সবচেয়ে বড় অমার্জনীয় '
        'অপরাধগুলোর একটি, তখন নবী ﷺ বিশাল রোমান সাম্রাজ্যের '
        'মুখোমুখি হতে মাত্র তিন হাজার যোদ্ধার একটি বাহিনী প্রস্তুত '
        'করলেন এবং জায়েদ ইবনে হারিসাকে তাদের সেনাপতি নিযুক্ত '
        'করলেন এবং অসিয়ত করলেন: "জায়েদ শহীদ হলে জাফর '
        'ইবনে আবি তালিব, জাফর শহীদ হলে আবদুল্লাহ ইবনে '
        'রাওয়াহা।" মুসলিমরা মুতায় রোমান ও তাদের মিত্রদের '
        'সৈন্যবাহিনীর মুখোমুখি হলো, আর তাদের সংখ্যা এক লাখ '
        'যোদ্ধারও বেশি ছিল, এটি মুসলিমরা আগে কখনো দেখেনি '
        'এমন একটি বিশাল পার্থক্য ছিল। জায়েদ ইবনে হারিসা '
        'তীব্রভাবে যুদ্ধ করতে করতে প্রথমে শহীদ হলেন, তখন জাফর '
        'ইবনে আবি তালিব পতাকা নিলেন এবং তাঁর ডান হাত কাটা '
        'পড়া পর্যন্ত যুদ্ধ চালিয়ে গেলেন, তখন তিনি তা বাম হাতে '
        'ধরলেন, বাম হাতও কাটা পড়ল, তারপর তিনি তাঁর কাটা '
        'বাহু দুটি দিয়ে পতাকা জড়িয়ে ধরলেন যতক্ষণ না শহীদ হলেন, '
        'আল্লাহ তাঁকে দুটি ডানা দিয়ে বদলে দিলেন যা দিয়ে তিনি '
        'জান্নাতে উড়ে বেড়ান, তখন সেদিন থেকে তাঁকে জাফর '
        'আত-তাইয়ার (উড়ন্ত) বলা হলো। তাঁর পরে আবদুল্লাহ ইবনে '
        'রাওয়াহা পতাকা নিলেন তিনিও শহীদ হলেন, শেষ পর্যন্ত নবী '
        'ﷺ-এর নিযুক্ত করা তিনজন সেনাপতিই একই দিনে শহীদ '
        'হলেন। তাঁদের পরে খালিদ ইবনে ওয়ালিদ পতাকা নিলেন — '
        'তিনি তখনো কয়েক মাস আগে ইসলাম গ্রহণ করেছিলেন — '
        'তিনি একটি বিরল সামরিক প্রতিভা প্রদর্শন করলেন, যেখানে '
        'তিনি বাহিনীর বিন্যাস পরিবর্তন করলেন এবং কিছু ইউনিট '
        'পেছনে ও কিছু সামনে রাখলেন, তখন রোমানরা মনে করল '
        'মুসলিমদের কাছে একটি বড় শক্তিবৃদ্ধি এসেছে, তখন তারা '
        'কিছুটা পিছু হটল, তখন খালিদ এই সুযোগের ব্যবহার করে '
        'সম্পূর্ণ মুসলিম বাহিনীকে অতিরিক্ত বড় ক্ষতি ছাড়াই সম্পূর্ণ '
        'শৃঙ্খলার সাথে প্রত্যাহার করলেন, আর এটি নিজেই একটি '
        'বড় সামরিক কৃতিত্ব যে একটি ছোট বাহিনী তার চেয়ে '
        'দশগুণেরও বেশি শক্তির মুখোমুখি হয়ে ধ্বংস না হয়ে '
        'পিছু হটতে পারল।',
    source: 'নবী সীরাতের কিতাব',
  ),
  'battle-8': StoryTranslation(
    title: 'হুনাইন যুদ্ধ',
    body:
        'মক্কা বিজয়ের অব্যবহিত পরে, হাওয়াজিন ও সাকিফ গোত্র '
        'একটি বড় বাহিনী নিয়ে জড়ো হলো বিজয়ের পর তাদের '
        'শক্তি আরও দৃঢ় হওয়ার আগেই মুসলিমদের মুখোমুখি হওয়ার '
        'সংকল্প নিয়ে, তখন নবী ﷺ বারো হাজার যোদ্ধার একটি '
        'বাহিনী নিয়ে বের হলেন, যা সেই সময় পর্যন্ত ইসলামি বাহিনীর '
        'মধ্যে সবচেয়ে বড় বাহিনী ছিল, এমনকি কিছু মুসলিম তাদের '
        'সংখ্যার প্রাচুর্যে গর্বিত হয়ে বলল: "আজ আমরা সংখ্যাল্পতার '
        'কারণে পরাজিত হব না।" কিন্তু কেবল সংখ্যার প্রতি এই '
        'আস্থা একটি বিপজ্জনক পরাজয়ের কারণ হওয়ার কাছাকাছি '
        'পৌঁছাল, কারণ হাওয়াজিন বাহিনী হুনাইন উপত্যকার সংকীর্ণ '
        'পথগুলোতে ওঁৎ পেতে ছিল এবং ফজরের সময় তীব্র তীর '
        'বৃষ্টি দিয়ে মুসলিম বাহিনীর সামনের অংশে হঠাৎ আক্রমণ '
        'করল, তখন সামনের সারিগুলো বিশৃঙ্খল হয়ে হঠাৎ পিছু হটে '
        'গেল, আর পরিস্থিতি এত দ্রুত পরিবর্তিত হলো যে কিছুক্ষণের '
        'জন্য মনে হলো মুসলিমরা পরাজিত হবে। কিন্তু নবী ﷺ '
        'তাঁর স্থানে সম্পূর্ণ অটল রইলেন এতটুকুও নড়লেন না, তাঁর '
        'সাদা খচ্চরে চড়ে, তাঁর উচ্চ কণ্ঠে ডাকতে লাগলেন: "আমি '
        'নবী, মিথ্যা নয়, আমি আবদুল মুত্তালিবের পুত্র।" তারপর তিনি '
        'তাঁর চাচা আব্বাসকে — যাঁর কণ্ঠস্বর ছিল উচ্চ ও শক্তিশালী — '
        'নির্দেশ দিলেন পিছু হটা লোকদের ডাকতে: "হে সামুরা '
        'গাছের অধিবাসীরা!" — বাইআতে রিদওয়ানের দিকে ইঙ্গিত '
        'করে — তখন তারা তাঁর ডাক শুনল এবং তাদের প্রতিশ্রুতি '
        'স্মরণ করল আর তাদের মধ্যে সাহস ফিরে এলো, তখন তারা '
        'প্রতিটি দিক থেকে দৌড়ে নবী ﷺ-এর কাছে ফিরে এলো '
        'শেষ পর্যন্ত তারা আবার তাঁর চারপাশে জড়ো হলো, আর যুদ্ধ '
        'দ্রুত তাদের পক্ষে ফিরে গেল পরাজয় প্রায় ঘটে যাওয়ার পর, '
        'তখন হাওয়াজিন বাহিনী চরম পরাজয় বরণ করল, মুসলিমরা '
        'উট, ছাগল ও বন্দীদের বিশাল গনিমত অর্জন করল। আর '
        'এই উপলক্ষে কুরআনের আয়াত নাজিল হলো।',
    source: 'সূরা আত-তাওবা: ২৫-২৬ — নবী সীরাতের কিতাব',
  ),
};
